// Package types holds the value types shared by core, the minters, the
// market and the readers. Every type is plain data (no pointers into realm
// state), so passing one across a realm boundary hands over a copy and
// never a capability.
package types

import (
	"errors"
)

// State is a collection's lifecycle (design §4.1):
//
//	Draft -> Scheduled -> Minting -> Closed -> Final
//
// Scheduled->Minting and Minting->Closed happen by block height; core
// reports the effective state and materializes it on the next write.
type State int

const (
	StateDraft State = iota
	StateScheduled
	StateMinting
	StateClosed
	StateFinal
)

func (s State) String() string {
	switch s {
	case StateDraft:
		return "draft"
	case StateScheduled:
		return "scheduled"
	case StateMinting:
		return "minting"
	case StateClosed:
		return "closed"
	case StateFinal:
		return "final"
	}
	return "unknown"
}

// MaxUnitPrice caps every price (ugnot) so price*count and fee math stay
// far from int64 overflow: 1e15 ugnot = 1e9 GNOT.
const MaxUnitPrice = 1_000_000_000_000_000

// Payee receives Bps/10000 of a payment.
type Payee struct {
	Addr address
	Bps  int64
}

// CollectionSpec is what a minter asks core to create. Payees travel as
// "addr:bps,…" strings and are parsed by core, so core never stores a slice
// allocated by another realm.
type CollectionSpec struct {
	Name, Symbol, Description string
	EngineID, Params          string
	MaxSupply, RoyaltyBps     int64
	PrimaryPayees             string
	RoyaltyPayees             string
}

// BeaconCommitted is the platform's commit-reveal beacon as a collection's
// randomness source (LaunchSpec.BeaconSource "" means the same).
const BeaconCommitted = "committed"

// LaunchSpec freezes a collection's sale window and commitments (I-6).
//
// BeaconSource picks the second entropy source when UseBeacon is set:
// "" or BeaconCommitted for the platform beacon's commit-reveal, or the
// package path of an admin-approved randomness provider realm (e.g. a drand
// relay); it must be "" without UseBeacon.
type LaunchSpec struct {
	StartHeight, EndHeight int64
	RevealWindow           int64 // blocks after close; core bounds it
	CreatorCommit          string
	UseBeacon              bool
	BeaconSource           string
}

// CollectionInfo is core's typed read model for other realms.
type CollectionInfo struct {
	ID, Name, Symbol, Description string
	Creator                       address
	Minter, EngineID, Params      string
	State                         State
	MaxSupply, Minted, Reserved   int64
	StartHeight, EndHeight        int64
	RevealDeadline                int64 // 0 before Launch
	RoyaltyBps                    int64
	Badge                         string // provenance badge once Final
}

// Fees are the protocol's fee parameters; core enforces hard caps.
type Fees struct {
	CreateFee    int64 // ugnot per collection
	PrimaryBps   int64 // of every primary sale
	SecondaryBps int64 // of every market sale
	Treasury     address
	EngineCapBps int64 // platform cap on engine-author fees (<= engine.MaxFeeBps)
}

// Phase kinds.
const (
	PhaseAllow  = "allow"
	PhasePublic = "public"
)

// Phase is one sale window. A fixed price has StartPrice == FloorPrice and
// no steps; a Dutch auction starts at StartPrice and drops StepAmount every
// StepBlocks until FloorPrice (design §4.5). WalletCap counts lifetime
// mints of the collection (I-9); 0 means no cap.
type Phase struct {
	Kind, Set                string
	StartHeight, EndHeight   int64
	StartPrice, FloorPrice   int64
	StepBlocks, StepAmount   int64
	WalletCap                int64
}

// Validate checks a phase in isolation; the minter checks the set grammar
// and how phases relate to each other.
func (p Phase) Validate() error {
	switch p.Kind {
	case PhasePublic:
		if p.Set != "" {
			return errors.New("a public phase has no allowlist set")
		}
	case PhaseAllow:
		if p.Set == "" {
			return errors.New("an allow phase needs a set")
		}
	default:
		return errors.New("phase kind must be allow or public")
	}
	if p.StartHeight <= 0 || p.EndHeight < p.StartHeight {
		return errors.New("phase heights must satisfy 0 < start <= end")
	}
	if p.FloorPrice < 0 || p.StartPrice < p.FloorPrice || p.StartPrice > MaxUnitPrice {
		return errors.New("prices must satisfy 0 <= floor <= start <= MaxUnitPrice")
	}
	if p.StartPrice == p.FloorPrice {
		if p.StepBlocks != 0 || p.StepAmount != 0 {
			return errors.New("a fixed-price phase has no steps")
		}
	} else if p.StepBlocks <= 0 || p.StepAmount <= 0 {
		return errors.New("a Dutch phase needs positive stepBlocks and stepAmount")
	}
	if p.WalletCap < 0 {
		return errors.New("walletCap must be >= 0")
	}
	return nil
}

// Covers reports whether height h is inside the phase window.
func (p Phase) Covers(h int64) bool {
	return h >= p.StartHeight && h <= p.EndHeight
}

// PriceAt is the unit price at height h:
//
//	max(floor, start - floor((h-startH)/stepBlocks) * stepAmount)
//
// computed so that no intermediate value can overflow.
func (p Phase) PriceAt(h int64) int64 {
	if p.StartPrice == p.FloorPrice || h <= p.StartHeight {
		return p.StartPrice
	}
	steps := (h - p.StartHeight) / p.StepBlocks
	if steps > (p.StartPrice-p.FloorPrice)/p.StepAmount {
		return p.FloorPrice
	}
	price := p.StartPrice - steps*p.StepAmount
	if price < p.FloorPrice {
		return p.FloorPrice
	}
	return price
}

package safe

// AvgBlockMs is the measured mainnet average block time (RA §1: 200k blocks
// in 708,660 s). Use it only for UI estimates and defaults; every on-chain
// rule is stated in blocks.
const AvgBlockMs = 3540

// BlocksFor converts a duration to blocks, rounding up.
func BlocksFor(seconds int64) int64 {
	if seconds <= 0 {
		return 0
	}
	return (seconds*1000 + AvgBlockMs - 1) / AvgBlockMs
}

package safe

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
)

// MaxMerkleDepth bounds a proof: 2^32 leaves is far beyond any allowlist.
const MaxMerkleDepth = 32

func Sha256Hex(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

// --- commit–reveal v2 (design §4.2) --------------------------------------
//
// Every formula is domain-separated by platform, purpose, version, chain and
// collection, so a secret or commit is useless anywhere else (RA M-5). They
// live here, not in core, so the frontend's verifier, the beacon service and
// the tests all port one definition.

// Commit is the value a creator ("creator") or the beacon ("beacon") commits
// to for collection cid on chain chainID.
func Commit(chainID, cid, role, secret string) string {
	return Sha256Hex(Domain + "|commit|v2|" + chainID + "|" + cid + "|" + role + "|" + secret)
}

// InitialEntropy seeds a collection's mint-entropy accumulator.
func InitialEntropy(chainID, cid string) string {
	return Sha256Hex(Domain + "|acc|v2|" + chainID + "|" + cid)
}

// MixEntropy folds one mint call into the accumulator. The inputs are
// public, but none existed when the secrets were committed, which is what
// stops a committer from choosing the map their own mints receive.
func MixEntropy(acc string, to address, height, first, last int64) string {
	return Sha256Hex(acc + "|" + to.String() + "|" + strconv.FormatInt(height, 10) + "|" +
		strconv.FormatInt(first, 10) + "-" + strconv.FormatInt(last, 10))
}

// Salt binds both secrets ("" when not revealed) to the final accumulator.
func Salt(cid, creatorSecret, beaconSecret, acc string) string {
	return Sha256Hex(Domain + "|salt|v2|" + cid + "|" + creatorSecret + "|" + beaconSecret + "|" + acc)
}

// Seed is the per-token engine seed once the salt is final.
func Seed(cid, tid, salt string) string {
	return Sha256Hex(Domain + "|seed|v1|" + cid + "|" + tid + "|" + salt)
}

// --- allowlist merkle proofs (design §4.6) -------------------------------

// AllowlistLeaf is the leaf for addr in collection cid's allowlist tree.
func AllowlistLeaf(cid string, addr address) string {
	return Sha256Hex(Domain + "|al|v1|" + cid + "|" + addr.String())
}

// MerkleVerify checks a sorted-pair sha256 proof ("hex,hex,…", leaf to
// root). An empty proof means the tree has a single leaf equal to the root.
// Malformed input is simply false: proofs come from untrusted callers.
func MerkleVerify(rootHex, leafHex, proof string) bool {
	root, err := hex.DecodeString(rootHex)
	if err != nil || len(root) != 32 {
		return false
	}
	node, err := hex.DecodeString(leafHex)
	if err != nil || len(node) != 32 {
		return false
	}
	if proof != "" {
		steps := strings.Split(proof, ",")
		if len(steps) > MaxMerkleDepth {
			return false
		}
		for _, step := range steps {
			sibling, err := hex.DecodeString(step)
			if err != nil || len(sibling) != 32 {
				return false
			}
			node = hashPair(node, sibling)
		}
	}
	return bytes.Equal(node, root)
}

// MerkleNodeTag prefixes every inner node (SA-I2): an inner node hashes
// 0x01 || lo || hi, while a leaf is the hash of a text that starts with
// Domain ("art|al|v1|…"), so an inner node can never be presented as a leaf
// or the other way round.
const MerkleNodeTag = byte(0x01)

// hashPair hashes the two children in byte order, so a proof needs no
// left/right flags.
func hashPair(a, b []byte) []byte {
	if bytes.Compare(b, a) < 0 {
		a, b = b, a
	}
	buf := make([]byte, 0, 65)
	buf = append(buf, MerkleNodeTag)
	buf = append(buf, a...)
	buf = append(buf, b...)
	sum := sha256.Sum256(buf)
	return sum[:]
}

// MerkleParent is hashPair on hex nodes, for tests and the off-chain builder.
func MerkleParent(aHex, bHex string) string {
	a, errA := hex.DecodeString(aHex)
	b, errB := hex.DecodeString(bHex)
	if errA != nil || errB != nil {
		panic("MerkleParent: invalid hex")
	}
	return hex.EncodeToString(hashPair(a, b))
}

package safe

import (
	"strconv"
	"strings"
)

// JSONString returns s as a quoted JSON string. Beyond the mandatory
// escapes it also escapes U+2028/U+2029 (RA L-12) and '<', '>', '&', so the
// output is safe to inline in HTML as well.
func JSONString(s string) string {
	const hexDigits = "0123456789abcdef"
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '<', '>', '&', 0x2028, 0x2029:
			b.WriteString(`\u`)
			b.WriteString(PadHex(int64(r), 4))
		default:
			if r < 0x20 || r == 0x7f {
				b.WriteString(`\u00`)
				b.WriteByte(hexDigits[(r>>4)&0xf])
				b.WriteByte(hexDigits[r&0xf])
				continue
			}
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// PadHex renders n in lowercase hex, zero-padded to width.
func PadHex(n int64, width int) string {
	s := strconv.FormatInt(n, 16)
	if len(s) >= width {
		return s
	}
	return strings.Repeat("0", width-len(s)) + s
}

// JSONWriter is the single JSON producer of every read API (design
// §2.5: reads return primitives or JSON, never positional text). It tracks
// commas itself, so callers only describe structure:
//
//	w := &safe.JSONWriter{}
//	w.BeginObject(); w.Key("id"); w.Str("1"); w.EndObject()
type JSONWriter struct {
	b        strings.Builder
	hasItems []bool // one entry per open container
	afterKey bool
}

func (w *JSONWriter) BeginObject() { w.open('{') }
func (w *JSONWriter) EndObject()   { w.close('}') }
func (w *JSONWriter) BeginArray()  { w.open('[') }
func (w *JSONWriter) EndArray()    { w.close(']') }

// Key starts an object member; the next value call writes its value.
func (w *JSONWriter) Key(k string) {
	w.separate()
	w.b.WriteString(JSONString(k))
	w.b.WriteByte(':')
	w.afterKey = true
}

func (w *JSONWriter) Str(v string) { w.value(JSONString(v)) }
func (w *JSONWriter) Int(v int64)  { w.value(strconv.FormatInt(v, 10)) }
func (w *JSONWriter) Bool(v bool)  { w.value(strconv.FormatBool(v)) }

// Raw writes v verbatim. Only for JSON produced by another JSONWriter.
func (w *JSONWriter) Raw(v string) { w.value(v) }

// StrField and IntField are Key+value shorthands.
func (w *JSONWriter) StrField(k, v string) { w.Key(k); w.Str(v) }
func (w *JSONWriter) IntField(k string, v int64) { w.Key(k); w.Int(v) }
func (w *JSONWriter) BoolField(k string, v bool) { w.Key(k); w.Bool(v) }

func (w *JSONWriter) String() string { return w.b.String() }

func (w *JSONWriter) open(c byte) {
	w.separate()
	w.b.WriteByte(c)
	w.hasItems = append(w.hasItems, false)
}

func (w *JSONWriter) close(c byte) {
	if len(w.hasItems) == 0 {
		panic("JSONWriter: close without open")
	}
	w.hasItems = w.hasItems[:len(w.hasItems)-1]
	w.b.WriteByte(c)
}

func (w *JSONWriter) value(v string) {
	w.separate()
	w.b.WriteString(v)
}

// separate writes the comma before an item, except right after a key.
func (w *JSONWriter) separate() {
	if w.afterKey {
		w.afterKey = false
		return
	}
	if n := len(w.hasItems); n > 0 {
		if w.hasItems[n-1] {
			w.b.WriteByte(',')
		}
		w.hasItems[n-1] = true
	}
}

package safe

import (
	"strconv"
	"strings"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// BpsDenominator is 100% in basis points (EIP-2981, royalty/v0).
const BpsDenominator = 10000

// BpsOf returns floor(amount * bps / 10000) without ever forming the full
// product, so it cannot overflow for any amount >= 0 and 0 <= bps <= 10000.
func BpsOf(amount, bps int64) int64 {
	if amount < 0 {
		panic("BpsOf: negative amount")
	}
	if bps < 0 || bps > BpsDenominator {
		panic("BpsOf: bps out of range")
	}
	return (amount/BpsDenominator)*bps + (amount%BpsDenominator)*bps/BpsDenominator
}

// AssertBps panics unless 0 <= bps <= cap.
func AssertBps(field string, bps, cap int64) {
	if bps < 0 || bps > cap {
		panic(field + ": must be between 0 and " + strconv.FormatInt(cap, 10) + " bps")
	}
}

// ParsePayees parses "g1…:7000,g1…:3000": 1..max distinct valid addresses,
// each with a positive share, shares summing to exactly 10000.
func ParsePayees(field, s string, max int) []types.Payee {
	if s == "" {
		panic(field + ": must not be empty")
	}
	parts := strings.Split(s, ",")
	if len(parts) > max {
		panic(field + ": at most " + strconv.Itoa(max) + " payees")
	}
	out := make([]types.Payee, 0, len(parts))
	var total int64
	for _, part := range parts {
		addrStr, bpsStr, ok := strings.Cut(part, ":")
		if !ok {
			panic(field + ": expected address:bps, got " + strconv.Quote(part))
		}
		addr := address(addrStr)
		if !addr.IsValid() {
			panic(field + ": invalid address " + strconv.Quote(addrStr))
		}
		bps, err := strconv.ParseInt(bpsStr, 10, 64)
		if err != nil || bps <= 0 || bps > BpsDenominator {
			panic(field + ": invalid share " + strconv.Quote(bpsStr))
		}
		for _, p := range out {
			if p.Addr == addr {
				panic(field + ": duplicate payee " + addrStr)
			}
		}
		total += bps
		out = append(out, types.Payee{Addr: addr, Bps: bps})
	}
	if total != BpsDenominator {
		panic(field + ": shares must sum to 10000 bps, got " + strconv.FormatInt(total, 10))
	}
	return out
}

// FormatPayees is the inverse of ParsePayees.
func FormatPayees(ps []types.Payee) string {
	parts := make([]string, len(ps))
	for i, p := range ps {
		parts[i] = p.Addr.String() + ":" + strconv.FormatInt(p.Bps, 10)
	}
	return strings.Join(parts, ",")
}

// SplitByBps divides amount by the payees' shares. The rounding remainder
// goes to the first payee, so the parts always sum to exactly amount — the
// property every "no balance left behind" invariant (I-3, I-4) relies on.
func SplitByBps(amount int64, ps []types.Payee) []int64 {
	if len(ps) == 0 {
		panic("SplitByBps: no payees")
	}
	out := make([]int64, len(ps))
	var given int64
	for i, p := range ps {
		out[i] = BpsOf(amount, p.Bps)
		given += out[i]
	}
	out[0] += amount - given
	return out
}

package safe

import (
	"errors"
	"strconv"
	"strings"
	"unicode/utf8"
)

// AssertSVG checks an engine's raw SVG output with a strict allowlist
// (SA-M3; it replaced a substring blacklist that namespace prefixes, URL
// whitespace and CSS escapes could slip past). The document is tokenized
// as XML and must be well formed:
//
//   - only the elements in svgElements, without a namespace prefix: no
//     script, style, foreignObject, image, a, animation (set, animate*) or
//     anything else that can run code, load a resource or redefine the page;
//   - only the attributes in svgAttributes, without a prefix except
//     xlink:href and the two fixed xmlns declarations; event handlers and
//     style= are therefore impossible;
//   - attribute values hold no control character, backslash, '<', ':' or
//     non-allowlisted entity, so no URL scheme (javascript:, data:, http:)
//     can be spelled, however it is split or escaped; url() must be
//     url(#id) and href must be #id;
//   - no comments, CDATA, doctype, entities or processing instructions.
//
// The frontend shows art only through <img>, which never runs scripts; this
// check is the defence in depth for every other place a data: URI ends up
// (wallets, explorers, indexers; RA M-7, design §5.4).
func AssertSVG(svg string, maxBytes int) error {
	if len(svg) == 0 {
		return errors.New("svg: empty")
	}
	if len(svg) > maxBytes {
		return errors.New("svg: larger than " + strconv.Itoa(maxBytes) + " bytes")
	}
	if !utf8.ValidString(svg) {
		return errors.New("svg: invalid UTF-8")
	}
	if !strings.HasPrefix(svg, "<svg") || !strings.HasSuffix(svg, "</svg>") {
		return errors.New("svg: must start with <svg and end with </svg>")
	}
	p := &svgParser{s: svg}
	return p.run()
}

const (
	svgNS   = "http://www.w3.org/2000/svg"
	xlinkNS = "http://www.w3.org/1999/xlink"
)

// svgElements are the drawing elements an engine may use.
var svgElements = map[string]bool{
	"svg": true, "g": true, "defs": true, "symbol": true, "use": true,
	"title": true, "desc": true,
	"path": true, "rect": true, "circle": true, "ellipse": true,
	"line": true, "polyline": true, "polygon": true,
	"text": true, "tspan": true,
	"linearGradient": true, "radialGradient": true, "stop": true,
	"clipPath": true, "mask": true, "pattern": true,
	"filter": true, "feGaussianBlur": true, "feOffset": true, "feBlend": true,
	"feColorMatrix": true, "feComposite": true, "feFlood": true, "feMerge": true,
	"feMergeNode": true, "feMorphology": true, "feTurbulence": true,
	"feDisplacementMap": true, "feComponentTransfer": true, "feFuncR": true,
	"feFuncG": true, "feFuncB": true, "feFuncA": true,
}

// svgAttributes are geometry, paint and filter attributes. Absent on
// purpose: style, on*, src, every animation attribute (attributeName, to,
// from, by, begin), and every prefixed name except xlink:href.
var svgAttributes = map[string]bool{
	"id": true, "class": true, "version": true, "viewBox": true, "preserveAspectRatio": true,
	"x": true, "y": true, "x1": true, "y1": true, "x2": true, "y2": true,
	"cx": true, "cy": true, "r": true, "rx": true, "ry": true, "fx": true, "fy": true, "fr": true,
	"width": true, "height": true, "d": true, "points": true, "pathLength": true,
	"transform": true, "href": true, "xlink:href": true,
	"fill": true, "fill-opacity": true, "fill-rule": true,
	"stroke": true, "stroke-width": true, "stroke-opacity": true, "stroke-linecap": true,
	"stroke-linejoin": true, "stroke-dasharray": true, "stroke-dashoffset": true, "stroke-miterlimit": true,
	"opacity": true, "color": true, "visibility": true, "display": true,
	"clip-path": true, "clip-rule": true, "mask": true, "filter": true,
	"shape-rendering": true, "vector-effect": true, "paint-order": true, "mix-blend-mode": true,
	"font-family": true, "font-size": true, "font-weight": true, "font-style": true,
	"text-anchor": true, "dominant-baseline": true, "letter-spacing": true,
	"textLength": true, "lengthAdjust": true, "dx": true, "dy": true, "rotate": true,
	"gradientUnits": true, "gradientTransform": true, "spreadMethod": true,
	"offset": true, "stop-color": true, "stop-opacity": true,
	"patternUnits": true, "patternContentUnits": true, "patternTransform": true,
	"clipPathUnits": true, "maskUnits": true, "maskContentUnits": true,
	"filterUnits": true, "primitiveUnits": true, "result": true, "in": true, "in2": true,
	"stdDeviation": true, "mode": true, "type": true, "values": true, "operator": true,
	"k1": true, "k2": true, "k3": true, "k4": true, "radius": true,
	"flood-color": true, "flood-opacity": true, "baseFrequency": true, "numOctaves": true,
	"seed": true, "stitchTiles": true, "scale": true, "xChannelSelector": true, "yChannelSelector": true,
	"tableValues": true, "slope": true, "intercept": true, "amplitude": true, "exponent": true,
	"xmlns": true, "xmlns:xlink": true,
}

type svgParser struct {
	s     string
	i     int
	stack []string
}

func svgErr(msg string) error { return errors.New("svg: " + msg) }

func (p *svgParser) run() error {
	rootDone := false
	for p.i < len(p.s) {
		if rootDone {
			return svgErr("content after the root element")
		}
		if p.s[p.i] != '<' {
			if err := p.text(); err != nil {
				return err
			}
			continue
		}
		if p.i+1 >= len(p.s) {
			return svgErr("unterminated tag")
		}
		c := p.s[p.i+1]
		switch {
		case c == '!':
			return svgErr("comments, CDATA, doctype and entity declarations are not allowed")
		case c == '?':
			return svgErr("processing instructions are not allowed")
		case c == '/':
			if err := p.closeTag(); err != nil {
				return err
			}
			if len(p.stack) == 0 {
				rootDone = true
			}
		default:
			first := len(p.stack) == 0
			name, selfClosed, err := p.openTag()
			if err != nil {
				return err
			}
			if first && name != "svg" {
				return svgErr("the root element must be <svg>")
			}
			if selfClosed && len(p.stack) == 0 {
				rootDone = true
			}
		}
	}
	if len(p.stack) != 0 {
		return svgErr("unclosed element <" + p.stack[len(p.stack)-1] + ">")
	}
	if !rootDone {
		return svgErr("no root element")
	}
	return nil
}

// text is character data: printable characters, whitespace and the five
// XML entities only.
func (p *svgParser) text() error {
	if len(p.stack) == 0 {
		return svgErr("text outside the root element")
	}
	start := p.i
	for p.i < len(p.s) && p.s[p.i] != '<' {
		p.i++
	}
	return checkChars(p.s[start:p.i], true)
}

func (p *svgParser) openTag() (string, bool, error) {
	p.i++ // '<'
	name := p.name()
	if name == "" {
		return "", false, svgErr("malformed tag")
	}
	if strings.Contains(name, ":") || !svgElements[name] {
		return "", false, svgErr("element <" + name + "> is not allowed")
	}
	seen := map[string]bool{}
	for {
		sp := p.spaces()
		if p.i >= len(p.s) {
			return "", false, svgErr("unterminated tag <" + name + ">")
		}
		switch p.s[p.i] {
		case '>':
			p.i++
			p.stack = append(p.stack, name)
			return name, false, nil
		case '/':
			if p.i+1 >= len(p.s) || p.s[p.i+1] != '>' {
				return "", false, svgErr("malformed tag <" + name + ">")
			}
			p.i += 2
			return name, true, nil
		}
		if !sp {
			return "", false, svgErr("attributes must be separated by whitespace in <" + name + ">")
		}
		attr := p.name()
		if attr == "" {
			return "", false, svgErr("malformed attribute in <" + name + ">")
		}
		if seen[attr] {
			return "", false, svgErr("duplicate attribute " + attr)
		}
		seen[attr] = true
		p.spaces()
		if p.i >= len(p.s) || p.s[p.i] != '=' {
			return "", false, svgErr("attribute " + attr + " needs a value")
		}
		p.i++
		p.spaces()
		if p.i >= len(p.s) || (p.s[p.i] != '"' && p.s[p.i] != '\'') {
			return "", false, svgErr("attribute " + attr + " must be quoted")
		}
		q := p.s[p.i]
		p.i++
		start := p.i
		for p.i < len(p.s) && p.s[p.i] != q {
			p.i++
		}
		if p.i >= len(p.s) {
			return "", false, svgErr("unterminated value of " + attr)
		}
		val := p.s[start:p.i]
		p.i++
		if err := checkAttr(name, attr, val); err != nil {
			return "", false, err
		}
	}
}

func (p *svgParser) closeTag() error {
	p.i += 2 // "</"
	name := p.name()
	p.spaces()
	if p.i >= len(p.s) || p.s[p.i] != '>' {
		return svgErr("malformed closing tag")
	}
	p.i++
	if len(p.stack) == 0 || p.stack[len(p.stack)-1] != name {
		return svgErr("mismatched closing tag </" + name + ">")
	}
	p.stack = p.stack[:len(p.stack)-1]
	return nil
}

// name reads an XML name made of ASCII letters, digits, '-', '_', '.', ':'.
func (p *svgParser) name() string {
	start := p.i
	for p.i < len(p.s) {
		c := p.s[p.i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == ':' ||
			(p.i > start && ((c >= '0' && c <= '9') || c == '-' || c == '.')) {
			p.i++
			continue
		}
		break
	}
	return p.s[start:p.i]
}

func (p *svgParser) spaces() bool {
	start := p.i
	for p.i < len(p.s) && isSpace(p.s[p.i]) {
		p.i++
	}
	return p.i > start
}

func checkAttr(elem, attr, val string) error {
	if !svgAttributes[attr] {
		return svgErr("attribute " + attr + " is not allowed")
	}
	switch attr {
	case "xmlns":
		if val != svgNS {
			return svgErr("xmlns must be " + svgNS)
		}
		return nil
	case "xmlns:xlink":
		if val != xlinkNS {
			return svgErr("xmlns:xlink must be " + xlinkNS)
		}
		return nil
	}
	if err := checkChars(val, false); err != nil {
		return svgErr("attribute " + attr + ": " + err.Error())
	}
	if strings.ContainsAny(val, ":\\<") {
		return svgErr("attribute " + attr + " contains a forbidden character (':', '\\' or '<')")
	}
	if attr == "href" || attr == "xlink:href" {
		if !isFragment(val) {
			return svgErr("references must stay inside the document (#id)")
		}
		return nil
	}
	low := strings.ToLower(val)
	for {
		k := strings.Index(low, "url")
		if k < 0 {
			return nil
		}
		rest := strings.TrimLeft(low[k+3:], " ")
		if !strings.HasPrefix(rest, "(") {
			low = low[k+3:]
			continue
		}
		rest = strings.TrimLeft(rest[1:], " ")
		end := strings.IndexByte(rest, ')')
		if end < 0 || !isFragment(strings.TrimRight(rest[:end], " ")) {
			return svgErr("references must stay inside the document (url(#id))")
		}
		low = rest[end:]
	}
}

// checkChars allows printable characters and the five XML entities; text
// (character data) may also hold whitespace, attribute values only spaces.
func checkChars(s string, isText bool) error {
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '&':
			ok := false
			for _, e := range []string{"&amp;", "&lt;", "&gt;", "&quot;", "&apos;"} {
				if strings.HasPrefix(s[i:], e) {
					ok = true
					break
				}
			}
			if !ok {
				return svgErr("only &amp; &lt; &gt; &quot; &apos; entities are allowed")
			}
		case c == 0x7f || (c < 0x20 && !(isText && isSpace(c))):
			return svgErr("control characters are not allowed")
		case c == '>' && !isText:
			return svgErr("'>' in an attribute value")
		}
	}
	for _, r := range s {
		if r >= 0x80 && r <= 0x9f {
			return svgErr("control characters are not allowed")
		}
	}
	return nil
}

func isFragment(v string) bool {
	if len(v) < 2 || v[0] != '#' {
		return false
	}
	for i := 1; i < len(v); i++ {
		c := v[i]
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.') {
			return false
		}
	}
	return true
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

// Package safe holds the pure checks and formulas every platform realm
// shares: text and SVG validation, basis-point math, payee splits, merkle
// proofs, provenance hashes and the one JSON writer. Nothing here has state.
package safe

import (
	"errors"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Domain separates every hash this platform commits to from hashes of the
// same bytes made for any other purpose. It equals the brand slug and
// changes with it (paths change anyway when the brand is chosen).
const Domain = "art"

// CheckText reports why s may not be stored as user-visible text.
//
// Rejected: invalid UTF-8; C0 and C1 control characters, which include tab,
// newline and carriage return (the record-injection vector of RA H-1); DEL;
// U+2028/U+2029, which end a line in older JavaScript parsers (RA L-12); and
// every bidi control or zero-width character that lets one string render as
// another.
func CheckText(s string, maxLen int) error {
	if len(s) > maxLen {
		return errors.New("too long (max " + strconv.Itoa(maxLen) + " bytes)")
	}
	if !utf8.ValidString(s) {
		return errors.New("invalid UTF-8")
	}
	for _, r := range s {
		if forbiddenRune(r) {
			return errors.New("forbidden character U+" + strings.ToUpper(strconv.FormatInt(int64(r), 16)))
		}
	}
	return nil
}

// AssertText panics with the field name when CheckText rejects s.
func AssertText(field, s string, maxLen int) {
	if err := CheckText(s, maxLen); err != nil {
		panic(field + ": " + err.Error())
	}
}

// AssertNonEmptyText is AssertText that also refuses "".
func AssertNonEmptyText(field, s string, maxLen int) {
	if s == "" {
		panic(field + ": must not be empty")
	}
	AssertText(field, s, maxLen)
}

func forbiddenRune(r rune) bool {
	switch {
	case r < 0x20, r == 0x7f, r >= 0x80 && r <= 0x9f:
		return true
	case r == 0x061c, r == 0xfeff: // Arabic letter mark, zero-width no-break space
		return true
	case r >= 0x200b && r <= 0x200f: // zero-width space/joiners, LRM, RLM
		return true
	case r == 0x2028, r == 0x2029:
		return true
	case r >= 0x202a && r <= 0x202e: // bidi embeddings and overrides
		return true
	case r >= 0x2066 && r <= 0x2069: // bidi isolates
		return true
	}
	return false
}

// AssertSymbol enforces the grc721 symbol alphabet ([A-Za-z0-9_-], 1..11
// bytes) up front, so the error names the field instead of surfacing from
// grc721.NewToken.
func AssertSymbol(field, s string) {
	if s == "" || len(s) > 11 {
		panic(field + ": must be 1-11 characters")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '-') {
			panic(field + ": only A-Z, a-z, 0-9, '_' and '-' are allowed")
		}
	}
}

// AssertHex checks that s is exactly nBytes of hex and returns it lowercased.
func AssertHex(field, s string, nBytes int) string {
	if len(s) != 2*nBytes {
		panic(field + ": must be " + strconv.Itoa(2*nBytes) + " hex characters")
	}
	low := strings.ToLower(s)
	for i := 0; i < len(low); i++ {
		c := low[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			panic(field + ": must be hex")
		}
	}
	return low
}

// ParseID parses a positive decimal id ("1", "42"). Leading zeros, signs
// and empty strings are refused so every id has exactly one spelling.
func ParseID(field, s string) int64 {
	if s == "" || len(s) > 18 || s[0] == '0' {
		panic(field + ": invalid id " + strconv.Quote(s))
	}
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			panic(field + ": invalid id " + strconv.Quote(s))
		}
		n = n*10 + int64(c-'0')
	}
	return n
}

// PadInt renders n with leading zeros to width digits, so decimal ids and
// prices sort correctly as avl keys. n must be >= 0.
func PadInt(n int64, width int) string {
	s := strconv.FormatInt(n, 10)
	if len(s) >= width {
		return s
	}
	return strings.Repeat("0", width-len(s)) + s
}

// XMLEscape makes s safe as SVG/XML character data or a quoted attribute.
func XMLEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&apos;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// Package engine is the "art as code" contract (design §5.2): what a
// generative engine implements, what core hands it, and the conformance
// rules both core and engine authors check against.
//
// An engine is registered from its own /r/ adapter realm. Because the
// adapter's methods are declared in that realm, core calling them runs the
// engine with the adapter's authority, never core's (interrealm v2 borrow
// rule #1). Methods receive and return plain values only: an engine never
// gets a reference into core state.
package engine

import (
	"errors"
	"strconv"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// Input is everything an engine may depend on. p/ packages are frozen once
// deployed, so the fields "living" engines will need later (phase 2) are
// here from day one.
type Input struct {
	Seed           string // 64-hex final seed (sample seeds in Studio)
	Params         string // collection params, in the engine's own format
	CollectionID   string
	TokenID        string
	MintHeight     int64
	LastMoveHeight int64 // patina: holding time = Height - LastMoveHeight
	Moves          int64 // transfers so far
	Height         int64 // height of the read (fixed by Verify)
}

type Trait struct {
	Type, Value string
}

type Manifest struct {
	Name, Version, Description, License string
	Author                              address // proven by core.ClaimEngine
	ParamsSchema                        string  // JSON Schema subset; Studio builds its form from it
	TraitTypes                          []string
	Living                              bool  // Render depends on LastMoveHeight/Moves/Height
	MaxSVGBytes                         int64 // <= MaxSVGBytes
	// FeeBps is the author's fee on every primary and secondary sale of a
	// collection that uses this engine, 0..MaxFeeBps. It is fixed at
	// registration; core snapshots it per collection at Launch, caps it by
	// the platform's engine-fee cap and waives it when the collection's
	// creator is the author.
	FeeBps int64
}

// Engine is implemented by a stateless value declared in the adapter realm.
//
// Contract: deterministic in Input; ValidateParams("") must accept the
// engine's defaults; Render returns raw SVG (core does the base64); Traits
// only uses types listed in the manifest, each at most once.
type Engine interface {
	Manifest() Manifest
	ValidateParams(params string) error
	Traits(in Input) []Trait
	Render(in Input) string
}

// Limits core enforces on every engine.
const (
	MaxSVGBytes      = 65536
	MaxTraits        = 32
	MaxTraitLen      = 64
	MaxNameLen       = 64
	MaxVersionLen    = 32
	MaxDescLen       = 1024
	MaxLicenseLen    = 64
	MaxParamsSchema  = 4096
	MaxFeeBps        = 500 // 5%: hard cap of an engine author's fee
)

// SampleInput is the fixed input of an engine's fingerprint: core renders it
// at registration and stores sha256(svg); anyone can recompute it later.
func SampleInput() Input {
	return Input{
		Seed:           safe.Sha256Hex(safe.Domain + "|engine-sample|v1"),
		CollectionID:   "0",
		TokenID:        "0",
		MintHeight:     1,
		LastMoveHeight: 1,
		Height:         1,
	}
}

// SampleSeed returns the i-th Studio/conformance sample seed.
func SampleSeed(i int) string {
	return safe.Sha256Hex(safe.Domain + "|sample|v1|" + strconv.Itoa(i))
}

// ValidateManifest checks sizes, text hygiene and the author address.
func ValidateManifest(m Manifest) error {
	fields := []struct {
		name, value string
		max         int
		required    bool
	}{
		{"name", m.Name, MaxNameLen, true},
		{"version", m.Version, MaxVersionLen, true},
		{"description", m.Description, MaxDescLen, false},
		{"license", m.License, MaxLicenseLen, false},
		{"paramsSchema", m.ParamsSchema, MaxParamsSchema, false},
	}
	for _, f := range fields {
		if f.required && f.value == "" {
			return errors.New("manifest " + f.name + ": must not be empty")
		}
		if err := safe.CheckText(f.value, f.max); err != nil {
			return errors.New("manifest " + f.name + ": " + err.Error())
		}
	}
	if !m.Author.IsValid() {
		return errors.New("manifest author: invalid address")
	}
	if len(m.TraitTypes) > MaxTraits {
		return errors.New("manifest: too many trait types")
	}
	for i, tt := range m.TraitTypes {
		if tt == "" {
			return errors.New("manifest: empty trait type")
		}
		if err := safe.CheckText(tt, MaxTraitLen); err != nil {
			return errors.New("manifest trait type: " + err.Error())
		}
		for _, prev := range m.TraitTypes[:i] {
			if prev == tt {
				return errors.New("manifest: duplicate trait type " + tt)
			}
		}
	}
	if m.FeeBps < 0 || m.FeeBps > MaxFeeBps {
		return errors.New("manifest feeBps: must be 0.." + strconv.Itoa(MaxFeeBps))
	}
	if m.MaxSVGBytes <= 0 || m.MaxSVGBytes > MaxSVGBytes {
		return errors.New("manifest maxSVGBytes: must be 1.." + strconv.Itoa(MaxSVGBytes))
	}
	return nil
}

// ValidateTraits checks one Traits() result against the manifest.
func ValidateTraits(m Manifest, ts []Trait) error {
	if len(ts) > len(m.TraitTypes) {
		return errors.New("traits: more traits than manifest trait types")
	}
	for i, t := range ts {
		if !contains(m.TraitTypes, t.Type) {
			return errors.New("traits: type not in manifest: " + t.Type)
		}
		for _, prev := range ts[:i] {
			if prev.Type == t.Type {
				return errors.New("traits: duplicate type " + t.Type)
			}
		}
		if err := safe.CheckText(t.Value, MaxTraitLen); err != nil {
			return errors.New("traits " + t.Type + ": " + err.Error())
		}
	}
	return nil
}

// CheckSVG is the output rule core applies to every render.
func CheckSVG(m Manifest, svg string) error {
	return safe.AssertSVG(svg, int(m.MaxSVGBytes))
}

// Conformance is the self-test engine authors run in their _test.gno
// before registering: manifest, default params, determinism, size, SVG
// hygiene, traits, and — for non-living engines — independence from the
// living fields.
func Conformance(e Engine, samples int) error {
	m := e.Manifest()
	if err := ValidateManifest(m); err != nil {
		return err
	}
	if err := e.ValidateParams(""); err != nil {
		return errors.New("default params rejected: " + err.Error())
	}
	inputs := []Input{SampleInput()}
	for i := 0; i < samples; i++ {
		in := SampleInput()
		in.Seed = SampleSeed(i)
		in.TokenID = strconv.Itoa(i + 1)
		inputs = append(inputs, in)
	}
	for _, in := range inputs {
		svg := e.Render(in)
		if svg != e.Render(in) {
			return errors.New("render is not deterministic for seed " + in.Seed)
		}
		if err := CheckSVG(m, svg); err != nil {
			return errors.New("seed " + in.Seed + ": " + err.Error())
		}
		if err := ValidateTraits(m, e.Traits(in)); err != nil {
			return errors.New("seed " + in.Seed + ": " + err.Error())
		}
		if !m.Living {
			moved := in
			moved.Height, moved.Moves, moved.LastMoveHeight = in.Height+1000, in.Moves+3, in.Height+500
			if e.Render(moved) != svg {
				return errors.New("non-living engine depends on Height/Moves/LastMoveHeight")
			}
		}
	}
	return nil
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

// Package genesis is the platform's first engine: a pure p/ port of
// the prototype's gen1 engine. The RNG stream, trait tables,
// draw order and SVG drawing are byte-for-byte nftgen1's, so a seed renders
// the same artwork here as there; genesis_test.gno pins trait vectors
// computed independently from the same algorithm.
//
// What changed is only the packaging (RA L-7): it is a stateless p/
// package implementing engine/v1, the seed comes from core's commit–reveal
// (so the salt/seed helpers and the gnoweb Render of nftgen1 are gone), and
// the engine takes no params.
package genesis

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
)

// TraitTypes in the order Traits returns them.
var traitTypes = []string{"Palette", "Shape", "Ground", "Frame", "Finish", "Aura", "Elements", "Symmetry", "Score", "Rarity"}

// MaxSVGBytes: 8 symmetry x 14 elements of the widest primitive plus the
// densest ground and frame stays well under this (gen1 tested < 32,000).
const MaxSVGBytes = 32768

// Manifest describes the engine. Author is left empty: the adapter realm
// that registers this engine sets the address that will ClaimEngine.
func Manifest() engine.Manifest {
	return engine.Manifest{
		Name:    "Genesis",
		Version: "1.0.0",
		Description: "Fully on-chain generative engine, nftgen1 lineage: FNV-1a + splitmix64 stream, " +
			"10 traits, 1,254,400 combinations, score-based rarity over every layer.",
		License:      "TBD",
		ParamsSchema: `{"const":""}`,
		TraitTypes:   append([]string{}, traitTypes...),
		Living:       false,
		MaxSVGBytes:  MaxSVGBytes,
	}
}

// ValidateParams: genesis has no parameters.
func ValidateParams(params string) error {
	if params != "" {
		return errors.New("genesis takes no params")
	}
	return nil
}

// Traits returns the ten traits of in.Seed in TraitTypes order.
func Traits(in engine.Input) []engine.Trait {
	t := TraitsOf(in.Seed)
	return []engine.Trait{
		{Type: "Palette", Value: t.Palette},
		{Type: "Shape", Value: t.Shape},
		{Type: "Ground", Value: t.Ground},
		{Type: "Frame", Value: t.Frame},
		{Type: "Finish", Value: t.Finish},
		{Type: "Aura", Value: t.Aura},
		{Type: "Elements", Value: strconv.Itoa(t.Elements)},
		{Type: "Symmetry", Value: strconv.Itoa(t.Symmetry)},
		{Type: "Score", Value: strconv.Itoa(t.Score)},
		{Type: "Rarity", Value: t.Rarity},
	}
}

// Render returns the raw SVG for in.Seed.
func Render(in engine.Input) string { return SVG(in.Seed) }

// ---------------------------------------------------------------------------
// Deterministic randomness — FNV-1a over the seed, then a splitmix64 mixer.
// Pure integer math: no floats, no time, no block data.
// ---------------------------------------------------------------------------

const (
	fnvOffset uint64 = 14695981039346656037
	fnvPrime  uint64 = 1099511628211
)

type rng struct {
	state uint64
}

func newRNG(seed string) *rng {
	h := fnvOffset
	for i := 0; i < len(seed); i++ {
		h ^= uint64(seed[i])
		h *= fnvPrime
	}
	if h == 0 {
		h = fnvPrime
	}
	return &rng{state: h}
}

func (r *rng) next() uint64 {
	r.state += 0x9E3779B97F4A7C15
	z := r.state
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

// intn returns a value in [0, n).
func (r *rng) intn(n int) int {
	if n <= 0 {
		return 0
	}
	return int(r.next() % uint64(n))
}

// ---------------------------------------------------------------------------
// Weighted trait tables (weights are explicit; one draw walks the sum).
// ---------------------------------------------------------------------------

type option struct {
	name   string
	weight int
	score  int // contribution to the rarity score
}

func pick(r *rng, table []option) option {
	total := 0
	for _, o := range table {
		total += o.weight
	}
	roll := r.intn(total)
	acc := 0
	for _, o := range table {
		acc += o.weight
		if roll < acc {
			return o
		}
	}
	return table[len(table)-1]
}

type palette struct {
	option
	bg  string
	ink string
	c1  string
	c2  string
	c3  string
}

// Palette weights sum to 100, so a weight reads directly as a percent.
var palettes = []palette{
	{option{"Emerald", 18, 0}, "#04140f", "#7cf2c4", "#10b981", "#34d399", "#065f46"},
	{option{"Amethyst", 18, 0}, "#0b0713", "#e9d5ff", "#8b5cf6", "#c084fc", "#4c1d95"},
	{option{"Abyss", 16, 0}, "#02101c", "#bae6fd", "#0ea5e9", "#38bdf8", "#0c4a6e"},
	{option{"Ember", 14, 0}, "#160806", "#fecaca", "#f97316", "#fb923c", "#7c2d12"},
	{option{"Bone", 12, 0}, "#f5f5f4", "#1c1917", "#78716c", "#a8a29e", "#292524"},
	{option{"Solar", 10, 0}, "#1a1403", "#fef08a", "#eab308", "#facc15", "#713f12"},
	{option{"Obsidian", 8, 2}, "#050505", "#e5e5e5", "#404040", "#737373", "#171717"},
	{option{"Prism", 4, 4}, "#0a0a12", "#fdf4ff", "#22d3ee", "#f472b6", "#a78bfa"},
}

var shapes = []option{
	{"Orbit", 20, 0},
	{"Lattice", 18, 0},
	{"Bloom", 18, 0},
	{"Shard", 16, 0},
	{"Spiral", 14, 0},
	{"Weave", 9, 2},
	{"Rift", 5, 4},
}

var grounds = []option{
	{"Flat", 30, 0},
	{"Halo", 25, 0},
	{"Grid", 22, 0},
	{"Rings", 14, 1},
	{"Scatter", 9, 2},
}

var frames = []option{
	{"None", 55, 0},
	{"Thin", 25, 1},
	{"Double", 14, 2},
	{"Ornate", 6, 4},
}

var finishes = []option{
	{"Matte", 50, 0},
	{"Gloss", 28, 1},
	{"Glow", 16, 2},
	{"Foil", 6, 4},
}

var auras = []option{
	{"None", 78, 0},
	{"Soft", 14, 2},
	{"Bright", 6, 4},
	{"Nova", 2, 7},
}

// TraitSet is the decoded properties of a seed. The SVG builder and the
// trait list both read this one struct, so picture and metadata cannot
// describe different artwork.
type TraitSet struct {
	Palette  string
	Shape    string
	Ground   string
	Frame    string
	Finish   string
	Aura     string
	Elements int
	Symmetry int
	Score    int
	Rarity   string
}

// Tier cut-offs, chosen on nftgen1's 1000-seed simulation: Common 21.4% /
// Uncommon 44.4% / Rare 25.2% / Legendary 7.6% / Mythic 1.4%.
const (
	scoreMythic    = 12
	scoreLegendary = 8
	scoreRare      = 5
	scoreUncommon  = 2
)

func derive(seed string) (TraitSet, palette) {
	r := newRNG(seed)

	// Draw order is part of the contract: changing it changes every token.
	p := palettes[0]
	{
		total := 0
		for _, q := range palettes {
			total += q.weight
		}
		roll := r.intn(total)
		acc := 0
		for _, q := range palettes {
			acc += q.weight
			if roll < acc {
				p = q
				break
			}
		}
	}
	shape := pick(r, shapes)
	ground := pick(r, grounds)
	frame := pick(r, frames)
	finish := pick(r, finishes)
	aura := pick(r, auras)

	t := TraitSet{
		Palette:  p.name,
		Shape:    shape.name,
		Ground:   ground.name,
		Frame:    frame.name,
		Finish:   finish.name,
		Aura:     aura.name,
		Elements: 5 + r.intn(10), // 5..14
		Symmetry: 2 + r.intn(7),  // 2..8
	}

	score := p.score + shape.score + ground.score + frame.score + finish.score + aura.score
	if t.Elements >= 13 {
		score++
	}
	if t.Symmetry >= 7 {
		score++
	}
	t.Score = score

	switch {
	case score >= scoreMythic:
		t.Rarity = "Mythic"
	case score >= scoreLegendary:
		t.Rarity = "Legendary"
	case score >= scoreRare:
		t.Rarity = "Rare"
	case score >= scoreUncommon:
		t.Rarity = "Uncommon"
	default:
		t.Rarity = "Common"
	}
	return t, p
}

// TraitsOf returns the decoded traits for a seed.
func TraitsOf(seed string) TraitSet {
	t, _ := derive(seed)
	return t
}

func finishStroke(finish string) int {
	switch finish {
	case "Gloss":
		return 4
	case "Glow":
		return 5
	case "Foil":
		return 6
	default: // Matte
		return 3
	}
}

func auraRing(aura string) (int, int) { // width, opacity percent
	switch aura {
	case "Soft":
		return 4, 22
	case "Bright":
		return 8, 38
	case "Nova":
		return 14, 60
	default:
		return 0, 0
	}
}

// SVG renders the artwork for a seed as a standalone SVG document.
func SVG(seed string) string {
	t, p := derive(seed)
	r := newRNG(seed + "|art") // separate stream: trait draws never shift the art

	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">`)
	b.WriteString(ufmt.Sprintf(`<rect width="512" height="512" fill="%s"/>`, p.bg))

	// --- ground layer ---
	switch t.Ground {
	case "Halo":
		b.WriteString(ufmt.Sprintf(
			`<circle cx="256" cy="256" r="200" fill="none" stroke="%s" stroke-width="1" opacity="0.35"/>`, p.c3))
	case "Grid":
		for i := 64; i < 512; i += 64 {
			b.WriteString(ufmt.Sprintf(
				`<line x1="%d" y1="0" x2="%d" y2="512" stroke="%s" stroke-width="1" opacity="0.18"/>`, i, i, p.c3))
			b.WriteString(ufmt.Sprintf(
				`<line x1="0" y1="%d" x2="512" y2="%d" stroke="%s" stroke-width="1" opacity="0.18"/>`, i, i, p.c3))
		}
	case "Rings":
		for rad := 60; rad <= 240; rad += 45 {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="256" cy="256" r="%d" fill="none" stroke="%s" stroke-width="1" opacity="0.22"/>`, rad, p.c3))
		}
	case "Scatter":
		for i := 0; i < 40; i++ {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="%d" cy="%d" r="2" fill="%s" opacity="0.30"/>`,
				16+r.intn(480), 16+r.intn(480), p.c3))
		}
	}

	// --- aura layer ---
	if w, op := auraRing(t.Aura); w > 0 {
		b.WriteString(ufmt.Sprintf(
			`<circle cx="256" cy="256" r="230" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
			p.ink, w, op))
	}

	// --- composition: one pass, mirrored Symmetry times ---
	stroke := finishStroke(t.Finish)
	step := 360 / t.Symmetry
	for s := 0; s < t.Symmetry; s++ {
		b.WriteString(ufmt.Sprintf(`<g transform="rotate(%d 256 256)">`, s*step))
		for e := 0; e < t.Elements; e++ {
			color := p.c1
			switch r.intn(3) {
			case 1:
				color = p.c2
			case 2:
				color = p.ink
			}
			x := 96 + r.intn(320)
			y := 96 + r.intn(320)
			size := 12 + r.intn(70)
			opacity := 40 + r.intn(55) // percent, integer only
			if t.Finish == "Glow" || t.Finish == "Foil" {
				opacity = 55 + r.intn(40)
			}

			switch t.Shape {
			case "Orbit":
				b.WriteString(ufmt.Sprintf(
					`<circle cx="%d" cy="%d" r="%d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, color, stroke, opacity))
			case "Lattice":
				b.WriteString(ufmt.Sprintf(
					`<rect x="%d" y="%d" width="%d" height="%d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, size, color, stroke-1, opacity))
			case "Bloom":
				b.WriteString(ufmt.Sprintf(
					`<circle cx="%d" cy="%d" r="%d" fill="%s" opacity="0.%d"/>`,
					x, y, size/2, color, opacity))
			case "Shard":
				b.WriteString(ufmt.Sprintf(
					`<polygon points="%d,%d %d,%d %d,%d" fill="%s" opacity="0.%d"/>`,
					x, y, x+size, y+size/2, x+size/3, y+size, color, opacity))
			case "Weave":
				b.WriteString(ufmt.Sprintf(
					`<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, x+size, y+size/3, color, stroke, opacity))
				b.WriteString(ufmt.Sprintf(
					`<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x+size, y, x, y+size/3, color, stroke, opacity))
			case "Rift":
				b.WriteString(ufmt.Sprintf(
					`<path d="M%d %d l %d %d l %d %d l %d %d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size/2, -size/3, size/3, size, size/2, -size/2,
					color, stroke, opacity))
			default: // Spiral
				b.WriteString(ufmt.Sprintf(
					`<path d="M%d %d q %d %d %d %d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, -size, size*2, 0, color, stroke, opacity))
			}
		}
		b.WriteString(`</g>`)
	}

	// --- frame layer, drawn last so it always sits on top ---
	switch t.Frame {
	case "Thin":
		b.WriteString(ufmt.Sprintf(
			`<rect x="12" y="12" width="488" height="488" fill="none" stroke="%s" stroke-width="2" opacity="0.55"/>`, p.ink))
	case "Double":
		b.WriteString(ufmt.Sprintf(
			`<rect x="10" y="10" width="492" height="492" fill="none" stroke="%s" stroke-width="3" opacity="0.60"/>`, p.ink))
		b.WriteString(ufmt.Sprintf(
			`<rect x="24" y="24" width="464" height="464" fill="none" stroke="%s" stroke-width="1" opacity="0.45"/>`, p.c2))
	case "Ornate":
		b.WriteString(ufmt.Sprintf(
			`<rect x="8" y="8" width="496" height="496" fill="none" stroke="%s" stroke-width="4" opacity="0.70"/>`, p.ink))
		b.WriteString(ufmt.Sprintf(
			`<rect x="22" y="22" width="468" height="468" fill="none" stroke="%s" stroke-width="2" opacity="0.55"/>`, p.c2))
		for _, c := range [][2]int{{8, 8}, {504, 8}, {8, 504}, {504, 504}} {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="%d" cy="%d" r="10" fill="none" stroke="%s" stroke-width="3" opacity="0.80"/>`,
				c[0], c[1], p.c1))
		}
	}

	b.WriteString(`</svg>`)
	return b.String()
}

package core

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Admin (design §2.5.2, §7.5). The admin can only change the parameters
// listed in validateOp, each inside a hard cap, after a public timelock;
// it can pause new activity for a bounded time. It can never move, approve
// or burn a token, touch a collection's configuration, or receive funds
// (I-1). With no collection yet there is nothing to protect, so ops execute
// without delay — that is how the platform is configured after deploy.
//
// TODO(mainnet): the initial admin and treasury must be the 2/3 multisig.
// SA-I6: CreateFee starts at 0 here so tests and bootstrap stay simple;
// scripts/deploy-onyx.sh sets a non-zero fee.create during bootstrap.
var (
	admin        = address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06")
	pendingAdmin address
	fees         = types.Fees{
		PrimaryBps: 250, SecondaryBps: 250, EngineCapBps: EngineFeeCapBps,
		Treasury: address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06"),
	}
	beacon       address
	minters      avl.Tree // minter pkgpath -> *minterRecord
	ops          avl.Tree // safe.PadInt(op id) -> *pendingOp
	opCount      int64
	pauses       avl.Tree // scope -> *pauseRecord
)

// pauseRecord is one scope's pause and its budget (SA-L2): within a window
// of PauseWindowBlocks a scope can be paused for at most MaxPauseBlocks in
// total; a pause cannot be renewed while it runs. Worst case two budgets
// meet at a window boundary (<= 2 x MaxPauseBlocks in a row), never more.
type pauseRecord struct {
	windowStart int64
	used        int64 // blocks of budget charged in this window
	until       int64 // exclusive
}

type minterRecord struct {
	deprecated bool
}

type pendingOp struct {
	id       int64
	op, arg  string
	proposed int64
}

// Ops and their argument formats.
const (
	OpFeeCreate       = "fee.create"       // ugnot, <= CreateFeeCap
	OpFeePrimary      = "fee.primary"      // bps, <= ProtocolFeeCapBps
	OpFeeSecondary    = "fee.secondary"    // bps, <= ProtocolFeeCapBps
	OpFeeEngine       = "fee.engine"       // bps, <= EngineFeeCapBps: platform cap on engine-author fees
	OpTreasury        = "treasury"         // address
	OpBeacon          = "beacon"           // address, or "" to disable new beacon launches
	OpMinterAdd       = "minter.add"       // realm pkgpath
	OpMinterDeprecate = "minter.deprecate" // realm pkgpath: no new collections
	OpEngineReview    = "engine.review"    // engine id: reviewed badge (UI only)
	OpAdminTransfer   = "admin.transfer"   // address; the new admin must AcceptAdmin
	OpRandomnessAdd   = "randomness.add"   // registered provider path: creators may launch with it
	OpRandomnessDepr  = "randomness.deprecate" // provider path: no new launches; running ones finish
)

var pauseScopes = []string{"create", "mint", "trade"}

func ProposeOp(cur realm, op, arg string) string {
	assertNoDeposit(cur)
	assertAdmin(cur)
	validateOp(op, arg)
	opCount++
	p := &pendingOp{id: opCount, op: op, arg: arg, proposed: height()}
	ops.Set(safe.PadInt(p.id, cidWidth), p)
	id := itoa(p.id)
	chain.Emit("OpProposed", "id", id, "op", op, "arg", arg, "earliest", itoa(earliestExecution(p)))
	return id
}

// ExecuteOp applies a proposed op once its timelock has passed. The delay is
// judged at execution, so an op proposed during bootstrap still waits the
// full timelock if a collection appeared in the meantime.
func ExecuteOp(cur realm, opID string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	p := mustOp(opID)
	if height() < earliestExecution(p) {
		panic("timelocked until height " + itoa(earliestExecution(p)))
	}
	validateOp(p.op, p.arg)
	applyOp(p.op, p.arg)
	ops.Remove(safe.PadInt(p.id, cidWidth))
	chain.Emit("OpExecuted", "id", opID, "op", p.op, "arg", p.arg)
}

func CancelOp(cur realm, opID string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	p := mustOp(opID)
	ops.Remove(safe.PadInt(p.id, cidWidth))
	chain.Emit("OpCancelled", "id", opID)
}

func AcceptAdmin(cur realm) {
	assertNoDeposit(cur)
	who := caller(cur)
	if pendingAdmin == "" || who != pendingAdmin {
		panic("no pending admin transfer to this address")
	}
	chain.Emit("AdminTransferred", "from", admin.String(), "to", who.String())
	admin = who
	pendingAdmin = ""
}

// Pause stops new activity in one scope for the rest of its budget (at
// most MaxPauseBlocks per PauseWindowBlocks). It never blocks exits (I-2)
// and cannot be renewed while it runs (SA-L2).
func Pause(cur realm, scope string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	assertScope(scope)
	h := height()
	r := pauseOf(scope)
	if h < r.until {
		panic("already paused until height " + itoa(r.until) + "; a pause cannot be renewed")
	}
	if h >= r.windowStart+PauseWindowBlocks {
		r.windowStart, r.used = h, 0
	}
	left := MaxPauseBlocks - r.used
	if left <= 0 {
		panic("pause budget of " + scope + " is spent until height " + itoa(r.windowStart+PauseWindowBlocks))
	}
	r.used += left
	r.until = h + left
	pauses.Set(scope, r)
	chain.Emit("Paused", "scope", scope, "until", itoa(r.until))
}

// Unpause ends a pause early and gives the unused blocks back to the budget.
func Unpause(cur realm, scope string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	assertScope(scope)
	h := height()
	r := pauseOf(scope)
	if h < r.until {
		r.used -= r.until - h
	}
	r.until = 0
	chain.Emit("Unpaused", "scope", scope)
}

func pauseOf(scope string) *pauseRecord {
	if v := pauses.Get(scope); v != nil {
		return v.(*pauseRecord)
	}
	return &pauseRecord{windowStart: -PauseWindowBlocks}
}

// Paused reports whether scope ("create", "mint", "trade") is paused now.
func Paused(scope string) bool {
	v := pauses.Get(scope)
	return v != nil && height() < v.(*pauseRecord).until
}

// PauseBudget is the scope's pause record as JSON: {until, used,
// windowStart, windowEnd, left}.
func PauseBudget(scope string) string {
	assertScope(scope)
	r := pauseOf(scope)
	used := r.used
	if height() >= r.windowStart+PauseWindowBlocks && height() >= r.until {
		used = 0
	}
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("until", r.until)
	w.IntField("used", used)
	w.IntField("windowStart", r.windowStart)
	w.IntField("windowEnd", r.windowStart+PauseWindowBlocks)
	w.IntField("left", MaxPauseBlocks-used)
	w.EndObject()
	return w.String()
}

func assertNotPaused(scope string) {
	if Paused(scope) {
		panic("paused: " + scope)
	}
}

func assertScope(scope string) {
	for _, s := range pauseScopes {
		if s == scope {
			return
		}
	}
	panic("pause scope must be one of " + strings.Join(pauseScopes, ", "))
}

func assertAdmin(cur realm) {
	if caller(cur) != admin {
		panic("admin only")
	}
}

func bootstrapping() bool { return collCount == 0 }

func earliestExecution(p *pendingOp) int64 {
	if bootstrapping() {
		return p.proposed
	}
	return p.proposed + TimelockBlocks
}

func mustOp(opID string) *pendingOp {
	v := ops.Get(safe.PadInt(safe.ParseID("opID", opID), cidWidth))
	if v == nil {
		panic("unknown op " + opID)
	}
	return v.(*pendingOp)
}

// validateOp is the closed list of admin powers (I-1).
func validateOp(op, arg string) {
	switch op {
	case OpFeeCreate:
		n := parseAmount(arg)
		if n > CreateFeeCap {
			panic("create fee above cap " + itoa(CreateFeeCap))
		}
	case OpFeePrimary, OpFeeSecondary:
		safe.AssertBps(op, parseAmount(arg), ProtocolFeeCapBps)
	case OpFeeEngine:
		safe.AssertBps(op, parseAmount(arg), EngineFeeCapBps)
	case OpTreasury, OpAdminTransfer:
		if !address(arg).IsValid() {
			panic(op + ": invalid address")
		}
		if op == OpTreasury {
			assertSpendable(op, address(arg), "", "") // SA-L5
		}
	case OpBeacon:
		if arg != "" && !address(arg).IsValid() {
			panic(op + ": invalid address")
		}
	case OpMinterAdd:
		safe.AssertText("minter", arg, 256)
		if !strings.HasPrefix(arg, runtime.ChainDomain()+"/r/") || strings.Contains(arg, "#") {
			panic("minter must be a realm path")
		}
		if minters.Has(arg) {
			panic("minter already added")
		}
	case OpMinterDeprecate:
		if !minters.Has(arg) {
			panic("unknown minter")
		}
	case OpEngineReview:
		mustEngine(arg)
	case OpRandomnessAdd:
		if mustProvider(arg).active {
			panic("randomness provider already approved")
		}
	case OpRandomnessDepr:
		if !mustProvider(arg).active {
			panic("randomness provider is not approved")
		}
	default:
		panic("unknown op " + strconv.Quote(op))
	}
}

func applyOp(op, arg string) {
	switch op {
	case OpFeeCreate:
		fees.CreateFee = parseAmount(arg)
	case OpFeePrimary:
		fees.PrimaryBps = parseAmount(arg)
	case OpFeeSecondary:
		fees.SecondaryBps = parseAmount(arg)
	case OpFeeEngine:
		fees.EngineCapBps = parseAmount(arg)
	case OpTreasury:
		fees.Treasury = address(arg)
	case OpBeacon:
		beacon = address(arg)
	case OpMinterAdd:
		minters.Set(arg, &minterRecord{})
	case OpMinterDeprecate:
		minters.Get(arg).(*minterRecord).deprecated = true
	case OpEngineReview:
		mustEngine(arg).reviewed = true
	case OpAdminTransfer:
		pendingAdmin = address(arg)
	case OpRandomnessAdd:
		mustProvider(arg).active = true
		activeProviders++
	case OpRandomnessDepr:
		mustProvider(arg).active = false
		activeProviders--
	}
}

func assertActiveMinter(path string) {
	v := minters.Get(path)
	if v == nil {
		panic("caller " + strconv.Quote(path) + " is not an approved minter")
	}
	if v.(*minterRecord).deprecated {
		panic("minter " + path + " is deprecated")
	}
}

func parseAmount(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 {
		panic("expected a non-negative integer, got " + strconv.Quote(s))
	}
	return n
}

package core

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/grc721/royalty/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/seqid/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// --- bound minter only -------------------------------------------------------
//
// A collection is created by an admin-approved minter realm and stays bound
// to it: only that realm can launch, abort, reserve and mint (I-5). The
// minter is trusted to pass the real creator; core trusts nothing else it
// is given and validates every field (I-13).

// CreateCollection stores a Draft collection and returns its id. Nobody can
// mint a Draft, so a creator can configure phases across several messages
// without a race (OA B2).
func CreateCollection(cur realm, creator address, spec types.CollectionSpec) string {
	minter := cur.Previous().PkgPath()
	assertActiveMinter(minter)
	assertNotPaused("create")
	if !creator.IsValid() {
		panic("invalid creator address")
	}
	safe.AssertNonEmptyText("name", spec.Name, MaxNameLen)
	safe.AssertSymbol("symbol", spec.Symbol)
	safe.AssertText("description", spec.Description, MaxDescriptionLen)
	safe.AssertText("params", spec.Params, MaxParamsLen)
	if spec.MaxSupply <= 0 || spec.MaxSupply > MaxSupplyCap {
		panic("maxSupply must be 1.." + itoa(MaxSupplyCap))
	}
	safe.AssertBps("royaltyBps", spec.RoyaltyBps, RoyaltyCapBps)
	primary := safe.ParsePayees("primaryPayees", spec.PrimaryPayees, MaxPayees)
	royal := safe.ParsePayees("royaltyPayees", spec.RoyaltyPayees, MaxPayees)
	next := itoa(collCount + 1)
	assertPayees("primaryPayees", primary, next, spec.EngineID)
	assertPayees("royaltyPayees", royal, next, spec.EngineID)

	rec := mustEngine(spec.EngineID)
	if !rec.claimed {
		panic("engine is not claimed by its author yet")
	}
	if rec.deprecated {
		panic("engine is deprecated")
	}
	// I-12 exception: the creator's own transaction runs the engine they chose.
	if err := rec.impl.ValidateParams(spec.Params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}

	collCount++
	cid := itoa(collCount)

	// Each collection gets its own sub-realm identity, so Token.ID() and every
	// grc721 event carry "…/core#c/<cid>" (design §2.3; verified by
	// spike/subtoken and core tests on gno v1.7.0).
	tok, led := grc721.NewToken(spec.Name, spec.Symbol, seqid.ID(uint64(collCount)), cur.Sub("c/"+cid))
	st := &tokenState{}
	led.RegisterExtension(&lockExt{cid: cid, st: st})
	roy, royLed := royalty.NewRoyalty(led, RoyaltyCapBps)
	if spec.RoyaltyBps > 0 {
		if err := royLed.SetDefaultRoyalty(royaltyAddress(cid), spec.RoyaltyBps); err != nil {
			panic(err)
		}
	}

	c := &collection{
		id:            cid,
		name:          spec.Name,
		symbol:        spec.Symbol,
		description:   spec.Description,
		creator:       creator,
		engineID:      spec.EngineID,
		params:        spec.Params,
		maxSupply:     spec.MaxSupply,
		nextTID:       1,
		royaltyBps:    spec.RoyaltyBps,
		primaryPayees: primary,
		royaltyPayees: royal,
		minter:        minter,
		state:         types.StateDraft,
		createdHeight: height(),
		token:         tok,
		ledger:        led,
		roy:           roy,
		st:            st,
	}
	collections.Set(collKey(cid), c)
	byCreator.Set(creator.String()+":"+collKey(cid), cid)

	chain.Emit("CollectionCreated",
		"cid", cid, "creator", creator.String(), "minter", minter,
		"engine", spec.EngineID, "token", tok.ID())
	return cid
}

// Launch freezes the configuration (I-6): sale window, reveal window and the
// creator's commitment. The sale must start in the future so a beacon can
// commit before the first mint.
func Launch(cur realm, cid string, l types.LaunchSpec) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	h := height()
	if c.state != types.StateDraft {
		panic("only a draft can be launched")
	}
	if l.StartHeight <= h {
		panic("startHeight must be in the future")
	}
	if l.EndHeight < l.StartHeight || l.EndHeight-l.StartHeight > MaxSaleBlocks {
		panic("sale window must be 0.." + itoa(MaxSaleBlocks) + " blocks")
	}
	if l.RevealWindow < RevealWindowMin || l.RevealWindow > RevealWindowMax {
		panic("revealWindow must be " + itoa(RevealWindowMin) + ".." + itoa(RevealWindowMax) + " blocks")
	}
	commit := safe.AssertHex("creatorCommit", l.CreatorCommit, 32)
	// Commitments are domain-separated by chain, collection and role
	// (safe.Commit), so only this collection's own history matters: a secret
	// that went public here is never accepted again (SA-L1, RA M-5).
	if isBurned(c, commit) {
		panic("this commitment's secret was already revealed; derive a new secret")
	}
	source := l.BeaconSource
	if l.UseBeacon {
		if source == "" {
			source = types.BeaconCommitted
		}
		if source == types.BeaconCommitted {
			if beacon == "" {
				panic("no beacon is configured; launch without useBeacon or with an approved randomness provider")
			}
		} else {
			assertActiveProvider(source)
		}
	} else {
		if source != "" {
			panic("beaconSource needs useBeacon")
		}
		// SA-M2: without the beacon the creator alone knows the only secret
		// and can grind the last mint for the map it wants. While the
		// platform has a beacon or an approved randomness provider, nobody
		// may opt out.
		if beaconAvailable() {
			panic("the platform beacon is configured; launch with useBeacon")
		}
	}

	c.prov = &provenance{creatorCommit: commit, acc: safe.InitialEntropy(runtime.ChainID(), cid)}
	c.startHeight, c.endHeight, c.revealWindow = l.StartHeight, l.EndHeight, l.RevealWindow
	c.useBeacon = l.UseBeacon
	c.beaconSource = source
	c.primaryBps = fees.PrimaryBps
	c.engineAuthor, c.engineBps = engineFeeQuote(c)
	c.state = types.StateScheduled

	chain.Emit("CollectionScheduled",
		"cid", cid, "start", itoa(c.startHeight), "end", itoa(c.endHeight),
		"revealWindow", itoa(c.revealWindow), "useBeacon", boolStr(c.useBeacon),
		"beaconSource", c.beaconSource, "creatorCommit", commit,
		"engineAuthor", c.engineAuthor.String(), "engineFeeBps", itoa(c.engineBps))
}

// AbortLaunch returns a launched collection to Draft while nothing has been
// minted — the way out when a beacon never commits. A commitment whose
// secret was revealed is burned for this collection; unrevealed ones (the
// beacon's deterministic one included) may be committed again (SA-L1).
func AbortLaunch(cur realm, cid string) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	refresh(c, height())
	if c.state == types.StateDraft || c.state == types.StateFinal {
		panic("only a launched, unfinished collection can be aborted")
	}
	if c.minted() > 0 {
		panic("tokens were minted; the launch can no longer be aborted")
	}
	if c.prov.creatorRevealed {
		c.burnedCommits = append(c.burnedCommits, c.prov.creatorCommit)
	}
	if c.prov.beaconRevealed {
		c.burnedCommits = append(c.burnedCommits, c.prov.beaconCommit)
	}
	c.prov = nil
	c.startHeight, c.endHeight, c.revealWindow, c.closeHeight = 0, 0, 0, 0
	c.useBeacon, c.beaconSource = false, ""
	c.engineBps, c.engineAuthor = 0, ""
	c.state = types.StateDraft
	chain.Emit("CollectionState", "cid", cid, "state", c.state.String())
}

// ReserveTo mints the creator's reserve before the sale starts. Reserve
// mints feed the entropy like any mint, appear in Provenance, and do not
// count toward wallet caps.
func ReserveTo(cur realm, cid string, to address, n int64) (first, last int64) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	assertNotPaused("mint")
	h := height()
	refresh(c, h)
	if c.state != types.StateScheduled {
		panic("reserve is only possible after launch and before the sale starts")
	}
	// SA-M2: a reserve is the creator's own allocation; it needs a map the
	// creator cannot steer, i.e. the beacon.
	if !c.useBeacon {
		panic("a creator reserve needs a beacon launch")
	}
	// A reserve is a mint, and the beacon may only commit while nothing is
	// minted: reserving first would leave the collection unmintable and
	// unabortable (found on Onyx, collection 1). A randomness provider has
	// nothing to commit: its value is drawn only after the reveal starts.
	if awaitingBeaconCommit(c) {
		panic("waiting for the beacon commitment; reserve after the beacon commits")
	}
	assertMintCount(c, n)
	if c.reserved+n > c.maxSupply*MaxReserveBps/safe.BpsDenominator {
		panic("reserve would exceed " + itoa(MaxReserveBps/100) + "% of supply")
	}
	first, last = mintBatchTo(c, to, n, h)
	c.reserved += n
	c.reservedTo.Set(to.String(), reservedTo(c, to)+n)
	emitBatch("Reserved", c, to, first, last)
	return first, last
}

// MintTo mints n tokens during the sale. The minter has already checked
// phase, price, allowlist and wallet cap; core re-checks only what it owns:
// state, supply and the beacon commitment (I-5). The lifetime counter of
// I-9 is the grc721 balance itself (mintedBy).
func MintTo(cur realm, cid string, to address, n int64) (first, last int64) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	assertNotPaused("mint")
	h := height()
	refresh(c, h)
	if c.state != types.StateMinting {
		panic("collection is not minting (state " + c.state.String() + ")")
	}
	if awaitingBeaconCommit(c) {
		panic("waiting for the beacon commitment; minting has not opened")
	}
	assertMintCount(c, n)
	first, last = mintBatchTo(c, to, n, h)
	if c.minted() == c.maxSupply {
		c.closeHeight = h
		c.state = types.StateClosed
		chain.Emit("CollectionState", "cid", cid, "state", c.state.String())
	}
	emitBatch("MintBatch", c, to, first, last)
	return first, last
}

func assertMintCount(c *collection, n int64) {
	if n <= 0 || n > MaxMintPerTx {
		panic("count must be 1.." + itoa(MaxMintPerTx))
	}
	if c.minted()+n > c.maxSupply {
		panic("only " + itoa(c.maxSupply-c.minted()) + " tokens left")
	}
}

// mintBatchTo is the only place tokens come into existence.
func mintBatchTo(c *collection, to address, n, h int64) (first, last int64) {
	first = c.nextTID
	last = first + n - 1
	for tid := first; tid <= last; tid++ {
		if err := c.ledger.Mint(to, grc721.TokenID(itoa(tid))); err != nil {
			panic(err)
		}
	}
	c.nextTID = last + 1
	c.st.appendTokens(first, last, h)
	c.prov.acc = safe.MixEntropy(c.prov.acc, to, h, first, last)
	return first, last
}

// mintedBy is addr's lifetime count of sale mints (I-9) while the
// collection is not Final: before Final no token can move or burn (I-11,
// lockExt) and tokens only come from mintBatchTo, so the grc721 balance is
// exactly sale mints + reserves received. This replaces a stored counter
// (~2 KB per new wallet, storage-cost-analysis P2). After Final the
// balance moves freely and no minter needs the count any more: -1.
func mintedBy(c *collection, addr address) int64 {
	if c.st.final {
		return -1
	}
	bal, err := c.token.BalanceOf(addr)
	if err != nil {
		return 0
	}
	return bal - reservedTo(c, addr)
}

func reservedTo(c *collection, addr address) int64 {
	if v := c.reservedTo.Get(addr.String()); v != nil {
		return v.(int64)
	}
	return 0
}

// awaitingBeaconCommit: a committed-beacon launch whose beacon has not
// committed yet; nothing may be minted (or reserved) before it does.
func awaitingBeaconCommit(c *collection) bool {
	return c.useBeacon && c.beaconSource == types.BeaconCommitted && c.prov.beaconCommit == ""
}

// CloseMint materializes Closed once the sale window has passed. Anyone may
// call it; reveals and Finalize work without it.
func CloseMint(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	refresh(c, height())
	if c.state != types.StateClosed {
		panic("the sale is not over (state " + c.state.String() + ")")
	}
}

// --- creator -----------------------------------------------------------------

// TransferCreator starts a two-step handover (RA M-11).
func TransferCreator(cur realm, cid string, to address) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	if !to.IsValid() {
		panic("invalid address")
	}
	c.pendingCreator = to
	chain.Emit("CreatorTransferStarted", "cid", cid, "from", c.creator.String(), "to", to.String())
}

func AcceptCreator(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	who := caller(cur)
	if c.pendingCreator == "" || who != c.pendingCreator {
		panic("no pending creator transfer to this address")
	}
	byCreator.Remove(c.creator.String() + ":" + collKey(cid))
	byCreator.Set(who.String()+":"+collKey(cid), cid)
	chain.Emit("CreatorTransferred", "cid", cid, "from", c.creator.String(), "to", who.String())
	c.creator = who
	c.pendingCreator = ""
}

// SetPayees changes the royalty split after Final. The primary-sale split is
// frozen with the sale (I-6); the royalty receiver stays the collection's
// sub-treasury, so third-party markets are unaffected. Royalties earned so
// far are first paid to the current payees (SA-I4).
func SetPayees(cur realm, cid, payees string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	if c.state != types.StateFinal {
		panic("royalty payees can change only after the collection is final")
	}
	ps := safe.ParsePayees("royaltyPayees", payees, MaxPayees)
	assertPayees("royaltyPayees", ps, cid, c.engineID)
	distribute(cur, c)
	c.royaltyPayees = ps
	chain.Emit("RoyaltyPayees", "cid", cid, "payees", payees)
}

// assertPayees refuses payees that can never spend what they receive
// (SA-L5): the platform's own realms and sub-addresses. cid is the
// collection being configured, engineID its engine adapter.
func assertPayees(field string, ps []types.Payee, cid, engineID string) {
	for _, p := range ps {
		assertSpendable(field, p.Addr, cid, engineID)
	}
}

// assertSpendable panics for core, core's sub-addresses of collection cid
// (token identity c/<cid>, royalty treasury roy/<cid>), every minter ever
// approved, the engine adapter, and the platform realms next to core
// (market, reader, gallery, the genesis adapter). None of them has a path
// that spends an incoming payment, so the coins would be stranded (I-3).
func assertSpendable(field string, addr address, cid, engineID string) {
	bad := []address{chain.PackageAddress(selfPath)}
	if cid != "" {
		bad = append(bad, chain.DerivePkgSubAddr(selfPath, "c/"+cid), royaltyAddress(cid))
	}
	if engineID != "" {
		bad = append(bad, chain.PackageAddress(engineID))
	}
	base := strings.TrimSuffix(selfPath, "/core")
	for _, sib := range platformRealms {
		bad = append(bad, chain.PackageAddress(base+"/"+sib))
	}
	for _, b := range bad {
		if addr == b {
			panic(field + ": " + addr.String() + " is a platform realm address that cannot spend; use a wallet")
		}
	}
	minters.Iterate("", "", func(path string, _ any) bool {
		if addr == chain.PackageAddress(path) {
			panic(field + ": " + addr.String() + " is the minter realm " + path + "; use a wallet")
		}
		return false
	})
}

// platformRealms are the realm paths next to core (README package map).
var platformRealms = []string{"mint/v1", "market/v1", "engines/genesis", "reader", "gallery"}

func assertCreator(cur realm, c *collection) {
	if caller(cur) != c.creator {
		panic("only the collection's creator can do this")
	}
}

func assertBoundMinter(cur realm, c *collection) {
	if cur.Previous().PkgPath() != c.minter {
		panic("only the collection's bound minter (" + c.minter + ") can do this")
	}
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

// Package core is the platform's immutable ledger (design §2.5.2): every
// collection, its official grc721 token and royalty, its provenance
// (commit–reveal v2), the engine registry, fees and the admin timelock.
//
// What core guarantees, whoever holds the admin key:
//
//   - I-1  admin cannot move, approve or burn a token, and holds no funds;
//     the op list is a closed set of parameters (admin.gno).
//   - I-2  pause only gates create, mint and trade. Transfer, burn,
//     finalize, distribute and every cancel stay open. A pause expires by
//     itself, cannot be renewed while it runs, and each scope has a budget
//     of MaxPauseBlocks per PauseWindowBlocks (SA-L2).
//   - I-5  supply only grows through the collection's bound minter, never
//     past maxSupply, and a token id is never minted twice.
//   - I-6  after Launch the engine, params, supply, payees, sale window,
//     commitments, randomness source and fee snapshots are frozen.
//   - I-9  MintedBy(addr) is exact while a collection is not Final:
//     grc721 balance minus the reserves sent to addr. It needs I-11 (no
//     token moves or burns before Final); if that lock is ever relaxed the
//     counter must be stored again (TestRegress_P2_*).
//   - I-10/11  a collection becomes Final at most once, only with both
//     reveals or after revealDeadline, and that deadline is bounded, so
//     the pre-reveal transfer lock always ends.
//   - I-12 engine code never runs on a state-changing path, except the
//     creator's own CreateCollection (ValidateParams) and the engine's own
//     RegisterEngine (one sample render). Every exported non-crossing
//     function is read-only, so an engine cannot call back into a mutator.
//     An admin-approved randomness provider (randomness.gno) runs only in
//     RequestRandomness/FulfillRandomness of collections launched with it.
//   - I-13 every stored string passed safe.AssertText.
//
// core imports no mutable realm: minters and engines are known only by
// package path and interface value.
package core

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/royalty/v0"
	"gno.land/p/nt/grc721/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Hard limits. They are constants on purpose: nobody, admin included, can
// raise them after deploy (block counts assume ~3.54 s blocks, RA M-1).
const (
	ProtocolFeeCapBps = 500           // 5% of any sale
	RoyaltyCapBps     = 1000          // 10% (RA M-3)
	CreateFeeCap      = 1_000_000_000 // 1,000 GNOT in ugnot
	MaxPayees         = 4
	MaxSupplyCap      = 10_000
	MaxMintPerTx      = 10    // hypothesis: measure n=10 gas/deposit on Onyx
	MaxReserveBps     = 1000  // creator reserve <= 10% of supply
	MaxSaleBlocks     = 732_000 // ~30 days
	RevealWindowMin   = 1_017   // ~1 hour
	RevealWindowMax   = 170_000 // ~7 days
	BeaconGraceBlocks = 254     // beacon may reveal first in the window's last ~15 min (< RevealWindowMin, so the creator always gets to go first)
	TimelockBlocks    = 48_800  // ~48 hours
	MaxPauseBlocks    = 195_000 // ~8 days: pause budget per scope and window
	PauseWindowBlocks = 732_000 // ~30 days (SA-L2)
	EngineFeeCapBps   = engine.MaxFeeBps // 5%: hard cap of an engine author's fee (platform cap <= this)
	RequestMargin     = 127              // a randomness request leaves >= this many blocks before revealDeadline

	MaxNameLen        = 64
	MaxDescriptionLen = 1024
	MaxParamsLen      = 1024
	MinSecretLen      = 32
	MaxSecretLen      = 256
	MaxPageSize       = 50
)

// Provenance badges (design §4.3).
const (
	BadgeBoth        = "2/2"
	BadgeCreatorOnly = "creator-only"
	BadgeBeaconOnly  = "beacon-only"
	BadgeFallback    = "fallback"
)

type collection struct {
	id, name, symbol, description string
	creator, pendingCreator       address
	engineID, params              string
	maxSupply                     int64
	nextTID                       int64 // next token id; minted so far = nextTID-1
	reserved                      int64
	royaltyBps                    int64
	primaryPayees, royaltyPayees  []types.Payee
	minter                        string
	state                         types.State
	startHeight, endHeight        int64
	revealWindow                  int64
	closeHeight                   int64 // sell-out height, or endHeight once time ran out
	useBeacon                     bool
	beaconSource                  string // with useBeacon: types.BeaconCommitted or a randomness provider path
	createdHeight                 int64
	primaryBps                    int64    // protocol fee snapshot at Launch (SA-I5)
	engineBps                     int64    // engine-author fee snapshot at Launch (0 when creator == author)
	engineAuthor                  address  // who receives engineBps
	burnedCommits                 []string // commitments whose secret went public; never accepted again here (SA-L1)
	approvals                     avl.Tree // "o:"+owner+":"+operator -> int64 nonce (SA-L3; token nonces are packed in st)
	prov                          *provenance
	token                         *grc721.Token
	ledger                        *grc721.PrivateLedger
	roy                           *royalty.Royalty
	st                            *tokenState
	reservedTo                    avl.Tree // address -> int64 reserve tokens received (MintedBy = balance - this, I-9)
}

func (c *collection) minted() int64 { return c.nextTID - 1 }

var (
	// selfPath is this realm's package path, captured once in init so read
	// functions can derive sub-addresses without a cur.
	selfPath string

	collections avl.Tree // safe.PadInt(cid) -> *collection
	byCreator   avl.Tree // creator + ":" + padded cid -> cid
	collCount   int64
)

func init(cur realm) {
	selfPath = cur.PkgPath()
}

const cidWidth = 10

func collKey(cid string) string {
	return safe.PadInt(safe.ParseID("cid", cid), cidWidth)
}

func mustCollection(cid string) *collection {
	v := collections.Get(collKey(cid))
	if v == nil {
		panic("unknown collection " + strconv.Quote(cid))
	}
	return v.(*collection)
}

// stateAt is the effective state at height h; the stored state lags until
// the next write materializes it (refresh).
func stateAt(c *collection, h int64) types.State {
	switch c.state {
	case types.StateScheduled:
		if h > c.endHeight {
			return types.StateClosed
		}
		if h >= c.startHeight {
			return types.StateMinting
		}
	case types.StateMinting:
		if h > c.endHeight {
			return types.StateClosed
		}
	}
	return c.state
}

func refresh(c *collection, h int64) {
	s := stateAt(c, h)
	if s == c.state {
		return
	}
	if s == types.StateClosed && c.closeHeight == 0 {
		c.closeHeight = c.endHeight
	}
	c.state = s
	chain.Emit("CollectionState", "cid", c.id, "state", s.String())
}

// revealDeadline is when anyone may finalize without the missing secrets.
// It is at most endHeight + RevealWindowMax, which bounds the transfer
// lock (I-11).
func revealDeadline(c *collection) int64 {
	closed := c.closeHeight
	if closed == 0 {
		closed = c.endHeight
	}
	return closed + c.revealWindow
}

func caller(cur realm) address {
	return cur.Previous().Address()
}

// assertNoDeposit refuses coins on functions that take none, so nothing can
// get stuck in core (RA L-1). The origin-send envelope belongs to the first
// realm of the call; it is only ours to judge when a wallet called us.
func assertNoDeposit(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func height() int64 { return runtime.ChainHeight() }

package core

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// Engine registry ("art as code", design §5).
//
// An engine registers itself from its own /r/ adapter realm; its id is that
// realm's package path, so nobody can register in someone else's name. The
// stored interface value's methods are declared in the adapter, so every
// call runs with the adapter's authority, not core's (interrealm v2 borrow
// rule #1): engine code cannot write core state. It also cannot call back
// into a core mutator: all of core's state-changing functions are crossing
// and need a live cur the engine never has.
//
// Honest limits, surfaced to users rather than hidden:
//   - an adapter realm with state could change its art later; the sample
//     fingerprint (VerifyEngine) detects a change of the sample, and review
//     means reading the adapter for statelessness;
//   - a private (re-deployable) adapter cannot register: the VM aborts the
//     registration when core's state would retain the private realm's type
//     (spike A9, observed in gno v1.7.0 test mode; confirm on Onyx).
type engineRecord struct {
	id               string
	impl             engine.Engine
	manifest         engine.Manifest // core-owned copy
	fingerprint      string          // sha256 of Render(SampleInput())
	claimed          bool
	deprecated       bool
	reviewed         bool
	registeredHeight int64
}

var (
	engines     avl.Tree // engine id -> *engineRecord
	engineOrder avl.Tree // safe.PadInt(seq) -> engine id
	engineCount int64
)

// RegisterEngine stores the calling realm's engine (I-12 exception: one
// sample render in the engine's own registration transaction). The record
// is immutable afterwards except for the claim/deprecate/review flags.
func RegisterEngine(cur realm, e engine.Engine) string {
	id := cur.Previous().PkgPath()
	if !strings.HasPrefix(id, runtime.ChainDomain()+"/r/") || strings.Contains(id, "#") {
		panic("an engine registers from its own realm (an /r/ package, not a sub-realm or wallet)")
	}
	if e == nil {
		panic("nil engine")
	}
	if engines.Has(id) {
		panic("engine already registered: " + id + " (publish a new version under a new path)")
	}
	m := copyManifest(e.Manifest())
	if err := engine.ValidateManifest(m); err != nil {
		panic(err)
	}
	if err := e.ValidateParams(""); err != nil {
		panic("engine must accept empty params (its defaults): " + err.Error())
	}
	sample := e.Render(engine.SampleInput())
	if err := engine.CheckSVG(m, sample); err != nil {
		panic("sample render: " + err.Error())
	}
	if err := engine.ValidateTraits(m, e.Traits(engine.SampleInput())); err != nil {
		panic("sample traits: " + err.Error())
	}

	rec := &engineRecord{
		id:               id,
		impl:             e,
		manifest:         m,
		fingerprint:      safe.Sha256Hex(sample),
		registeredHeight: height(),
	}
	engines.Set(id, rec)
	engineCount++
	engineOrder.Set(safe.PadInt(engineCount, cidWidth), id)
	chain.Emit("EngineRegistered", "id", id, "author", m.Author.String(), "feeBps", itoa(m.FeeBps),
		"fingerprint", rec.fingerprint)
	return id
}

// ClaimEngine proves the manifest author controls that address. Unclaimed
// engines cannot back a collection.
func ClaimEngine(cur realm, id string) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	if caller(cur) != rec.manifest.Author {
		panic("only the manifest author " + rec.manifest.Author.String() + " can claim this engine")
	}
	rec.claimed = true
	chain.Emit("EngineClaimed", "id", id)
}

// DeprecateEngine stops new collections; existing ones keep rendering.
func DeprecateEngine(cur realm, id string) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	if !rec.claimed || caller(cur) != rec.manifest.Author {
		panic("only the engine's author can deprecate it")
	}
	rec.deprecated = true
	chain.Emit("EngineDeprecated", "id", id)
}

// --- engine-author fee ---------------------------------------------------------
//
// An engine's author earns FeeBps (manifest, fixed at registration, <=
// EngineFeeCapBps) of every primary and secondary sale of a collection that
// uses the engine, capped by the platform's fees.EngineCapBps. A collection
// snapshots the fee at Launch (like the protocol fee, SA-I5) and later sales
// pay min(snapshot, current platform cap), so neither the author nor the
// admin can raise it on a running collection. No fee when the creator is
// the author: the creator's own payees already get the sale.

// engineFeeOf is the engine's fee under the current platform cap.
func engineFeeOf(rec *engineRecord) int64 {
	if rec.manifest.FeeBps < fees.EngineCapBps {
		return rec.manifest.FeeBps
	}
	return fees.EngineCapBps
}

// engineFeeQuote is what c would snapshot at a Launch now.
func engineFeeQuote(c *collection) (address, int64) {
	rec := mustEngine(c.engineID)
	author := rec.manifest.Author
	if author == c.creator {
		return author, 0
	}
	return author, engineFeeOf(rec)
}

// collectionEngineFee is the fee a sale of c pays now: the Launch snapshot
// bounded by the current cap; before Launch, the current quote.
func collectionEngineFee(c *collection) (address, int64) {
	if c.prov == nil {
		return engineFeeQuote(c)
	}
	if c.engineBps < fees.EngineCapBps {
		return c.engineAuthor, c.engineBps
	}
	return c.engineAuthor, fees.EngineCapBps
}

// EngineFee is the engine-author share of cid's sales: the author and the
// bps a sale pays now (0 when the creator is the author). mint/v1 and
// market/v1 pay safe.BpsOf(amount, bps) to author.
func EngineFee(cid string) (author address, bps int64) {
	return collectionEngineFee(mustCollection(cid))
}

func mustEngine(id string) *engineRecord {
	v := engines.Get(id)
	if v == nil {
		panic("unknown engine " + id)
	}
	return v.(*engineRecord)
}

// copyManifest gives core its own copy: the engine's slice was allocated in
// the engine realm.
func copyManifest(m engine.Manifest) engine.Manifest {
	out := m
	out.TraitTypes = append([]string{}, m.TraitTypes...)
	return out
}

// --- engine reads (Studio, Verify) -------------------------------------------

// RenderWith renders any registered engine for arbitrary params and seed as
// a data URI — Studio previews and the Verify button.
func RenderWith(id, params, seed string) string {
	rec := mustEngine(id)
	if err := rec.impl.ValidateParams(params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}
	svg := rec.impl.Render(studioInput(params, seed))
	if err := engine.CheckSVG(rec.manifest, svg); err != nil {
		return dataURI(placeholderSVG(rec.manifest.Name, "Engine output rejected"))
	}
	return dataURI(svg)
}

// EngineTraits returns a core-owned copy of the engine's traits for seed.
func EngineTraits(id, params, seed string) []engine.Trait {
	rec := mustEngine(id)
	if err := rec.impl.ValidateParams(params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}
	ts := rec.impl.Traits(studioInput(params, seed))
	if err := engine.ValidateTraits(rec.manifest, ts); err != nil {
		panic("engine traits rejected: " + err.Error())
	}
	return append([]engine.Trait{}, ts...)
}

func TraitsWith(id, params, seed string) string {
	w := &safe.JSONWriter{}
	writeTraits(w, EngineTraits(id, params, seed))
	return w.String()
}

// VerifyEngine re-renders the sample and compares it with the fingerprint
// stored at registration.
func VerifyEngine(id string) bool {
	rec := mustEngine(id)
	return safe.Sha256Hex(rec.impl.Render(engine.SampleInput())) == rec.fingerprint
}

// EngineManifest is the typed read for other realms (gallery).
func EngineManifest(id string) engine.Manifest { return copyManifest(mustEngine(id).manifest) }

// EngineStatus is "unclaimed", "unverified", "reviewed" or "deprecated".
func EngineStatus(id string) string { return engineStatus(mustEngine(id)) }

func engineStatus(rec *engineRecord) string {
	switch {
	case rec.deprecated:
		return "deprecated"
	case !rec.claimed:
		return "unclaimed"
	case rec.reviewed:
		return "reviewed"
	}
	return "unverified"
}

// Engine is the record as JSON.
func Engine(id string) string {
	w := &safe.JSONWriter{}
	writeEngine(w, mustEngine(id))
	return w.String()
}

func Engines(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	engineOrder.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		writeEngine(w, mustEngine(v.(string)))
		return false
	})
	w.EndArray()
	return w.String()
}

func writeEngine(w *safe.JSONWriter, rec *engineRecord) {
	m := rec.manifest
	w.BeginObject()
	w.StrField("id", rec.id)
	w.StrField("pkgPath", rec.id) // the adapter realm; read its source (and imports) with vm/qfile
	w.StrField("name", m.Name)
	w.StrField("version", m.Version)
	w.StrField("description", m.Description)
	w.StrField("license", m.License)
	w.StrField("author", m.Author.String())
	w.IntField("feeBps", m.FeeBps)
	w.IntField("effectiveFeeBps", engineFeeOf(rec))
	w.StrField("paramsSchema", m.ParamsSchema)
	w.Key("traitTypes")
	w.BeginArray()
	for _, t := range m.TraitTypes {
		w.Str(t)
	}
	w.EndArray()
	w.BoolField("living", m.Living)
	w.IntField("maxSvgBytes", m.MaxSVGBytes)
	w.StrField("fingerprint", rec.fingerprint)
	w.StrField("status", engineStatus(rec))
	w.IntField("registeredHeight", rec.registeredHeight)
	w.EndObject()
}

func studioInput(params, seed string) engine.Input {
	in := engine.SampleInput()
	in.Seed = seed
	in.Params = params
	in.Height = height()
	return in
}

package core

import (
	"chain"
	"chain/runtime"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Commit–reveal v2 (design §4.2–4.3, closes RA H-3, M-5, M-6).
//
// The map is fixed by three inputs: the creator's secret sc, the beacon's
// secret sb and the public mint-entropy accumulator acc. Neither committer
// knows the other's secret while minting is open, so neither can time the
// last mint for a good map. Order of reveals:
//
//  1. nothing is accepted before Closed (an early reveal informs the other
//     side);
//  2. the creator may reveal until revealDeadline - BeaconGraceBlocks; the
//     beacon follows at any time before the deadline;
//  3. inside the last BeaconGraceBlocks only the beacon may reveal. If the
//     creator stayed silent, the beacon's reveal finalizes at once
//     ("beacon-only"), so the creator never sees sb while it can still
//     choose (SA-M1; this also closes the mempool race of a creator
//     front-running the beacon's grace reveal);
//  4. after revealDeadline anyone finalizes with whatever was revealed.
//
// What stays open, by design: the beacon, as last revealer after the
// creator, can still choose between revealing and not (one bit). It runs
// public code and the badge shows the outcome. The transfer lock
// (tokens.gno) keeps anyone from trading on early knowledge until Final.
//
// A collection launched without the beacon (only possible while no beacon
// is configured, SA-M2) gives the creator the whole choice of the map; it
// can have no creator reserve and is never reported as a fair launch
// (FairLaunch, Provenance "fair").
type provenance struct {
	creatorCommit, beaconCommit string
	acc                         string
	creatorSecret, beaconSecret string
	creatorRevealed             bool
	beaconRevealed              bool
	salt, badge                 string
	finalHeight                 int64
	round                       int64 // randomness provider round bound by RequestRandomness (0 = none)
}

const (
	roleCreator = "creator"
	roleBeacon  = "beacon"
)

// BeaconCommit is the beacon's commitment, before any token exists.
func BeaconCommit(cur realm, cid, commitHex string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if beacon == "" || caller(cur) != beacon {
		panic("only the configured beacon can commit")
	}
	if c.state == types.StateDraft || c.prov == nil || !c.useBeacon || usesProvider(c) {
		panic("this collection is not waiting for a beacon")
	}
	if c.prov.beaconCommit != "" {
		panic("the beacon already committed")
	}
	if c.minted() > 0 {
		panic("too late: tokens were minted before the beacon committed")
	}
	commit := safe.AssertHex("commit", commitHex, 32)
	if isBurned(c, commit) {
		panic("this commitment's secret was already revealed for this collection")
	}
	c.prov.beaconCommit = commit
	chain.Emit("BeaconCommitted", "cid", cid, "commit", commit)
}

func RevealCreatorSecret(cur realm, cid, secret string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	h := height()
	assertRevealOpen(c, h)
	if c.prov.creatorRevealed {
		panic("the creator secret is already revealed")
	}
	if c.useBeacon {
		// SA-M1: once the grace period starts only the beacon may reveal, so
		// the creator can never reveal after seeing sb.
		if c.prov.beaconRevealed {
			panic("the beacon revealed first; the outcome is fixed")
		}
		if h >= revealDeadline(c)-BeaconGraceBlocks {
			panic("the creator's reveal window ended at height " + itoa(revealDeadline(c)-BeaconGraceBlocks-1) +
				"; only the beacon may reveal now")
		}
	}
	assertSecret(c, roleCreator, secret, c.prov.creatorCommit)
	c.prov.creatorSecret = secret
	c.prov.creatorRevealed = true
	chain.Emit("CreatorRevealed", "cid", cid, "secret", secret)
	if revealsComplete(c) {
		finalize(c, h)
	}
}

func RevealBeaconSecret(cur realm, cid, secret string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if beacon == "" || caller(cur) != beacon {
		panic("only the configured beacon can reveal")
	}
	h := height()
	assertRevealOpen(c, h)
	if !c.useBeacon || usesProvider(c) || c.prov.beaconCommit == "" {
		panic("this collection has no beacon commitment")
	}
	if c.prov.beaconRevealed {
		panic("the beacon secret is already revealed")
	}
	if !c.prov.creatorRevealed && h < revealDeadline(c)-BeaconGraceBlocks {
		panic("the beacon reveals after the creator, or in the window's last " + itoa(BeaconGraceBlocks) + " blocks")
	}
	assertSecret(c, roleBeacon, secret, c.prov.beaconCommit)
	c.prov.beaconSecret = secret
	c.prov.beaconRevealed = true
	chain.Emit("BeaconRevealed", "cid", cid, "secret", secret)
	// After the creator: both secrets are in (2/2). First, in the grace
	// period: the creator can no longer reveal, so the map is fixed now
	// (beacon-only) — nobody is left holding a choice (SA-M1).
	finalize(c, h)
}

// Finalize is permissionless and never paused (I-2): immediately once every
// expected secret is revealed, otherwise after revealDeadline (fallback).
func Finalize(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	refresh(c, h)
	if c.state != types.StateClosed {
		panic("only a closed collection can be finalized (state " + c.state.String() + ")")
	}
	if !revealsComplete(c) && h <= revealDeadline(c) {
		panic("the reveal window is open until height " + itoa(revealDeadline(c)))
	}
	// SA-I9: a sale that minted nothing stays Closed, so its creator can
	// still abort and relaunch; nobody else can lock it into Final.
	if c.minted() == 0 {
		panic("nothing was minted; the creator may abort and relaunch instead")
	}
	finalize(c, h)
}

func assertRevealOpen(c *collection, h int64) {
	refresh(c, h)
	if c.state != types.StateClosed {
		panic("secrets are accepted only after the sale closed (state " + c.state.String() + ")")
	}
	if h > revealDeadline(c) {
		panic("the reveal window closed; call Finalize")
	}
}

func assertSecret(c *collection, role, secret, commit string) {
	if len(secret) < MinSecretLen || len(secret) > MaxSecretLen {
		panic("secret must be " + itoa(MinSecretLen) + ".." + itoa(MaxSecretLen) + " bytes")
	}
	safe.AssertText("secret", secret, MaxSecretLen)
	if safe.Commit(runtime.ChainID(), c.id, role, secret) != commit {
		panic("secret does not match the " + role + " commitment")
	}
}

func revealsComplete(c *collection) bool {
	return c.prov.creatorRevealed && (!c.useBeacon || c.prov.beaconRevealed)
}

// finalize runs at most once per collection (I-10): every caller checks
// state Closed, and this sets Final.
func finalize(c *collection, h int64) {
	p := c.prov
	p.salt = safe.Salt(c.id, p.creatorSecret, p.beaconSecret, p.acc)
	switch {
	case p.creatorRevealed && p.beaconRevealed:
		p.badge = BadgeBoth
	case p.creatorRevealed:
		p.badge = BadgeCreatorOnly
	case p.beaconRevealed:
		p.badge = BadgeBeaconOnly
	default:
		p.badge = BadgeFallback
	}
	p.finalHeight = h
	c.state = types.StateFinal
	c.st.final = true
	chain.Emit("CollectionFinal", "cid", c.id, "salt", p.salt, "badge", p.badge)
}

// VerifyProvenance recomputes every commitment and the salt from public
// data. True only for a Final collection whose record is consistent.
func VerifyProvenance(cid string) bool {
	c := mustCollection(cid)
	if c.state != types.StateFinal {
		return false
	}
	p := c.prov
	chainID := runtime.ChainID()
	if p.creatorRevealed && safe.Commit(chainID, c.id, roleCreator, p.creatorSecret) != p.creatorCommit {
		return false
	}
	if p.beaconRevealed && !usesProvider(c) && safe.Commit(chainID, c.id, roleBeacon, p.beaconSecret) != p.beaconCommit {
		return false
	}
	// A provider's value was checked by FulfillRandomness against the
	// provider's verified round (p.round); it is recomputable off chain
	// from the provider's public source (e.g. the drand round).
	return p.salt == safe.Salt(c.id, p.creatorSecret, p.beaconSecret, p.acc)
}

// FairLaunch is true only for a Final, consistent collection whose map no
// single party could choose: launched with the beacon and finalized with
// both secrets or with the beacon's alone (after the creator stayed
// silent). Creator-only collections (no beacon: the creator alone knew the
// only secret and could steer the last mint, SA-M2) and fallbacks are not
// fair launches, even when VerifyProvenance is true.
func FairLaunch(cid string) bool {
	c := mustCollection(cid)
	if !VerifyProvenance(cid) || !c.useBeacon {
		return false
	}
	return c.prov.badge == BadgeBoth || c.prov.badge == BadgeBeaconOnly
}

func isBurned(c *collection, commit string) bool {
	for _, b := range c.burnedCommits {
		if b == commit {
			return true
		}
	}
	return false
}

// Provenance is the whole record as JSON; secrets and salt stay "" until
// revealed / final.
func Provenance(cid string) string {
	c := mustCollection(cid)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("cid", c.id)
	w.StrField("chainId", runtime.ChainID())
	w.StrField("state", stateAt(c, height()).String())
	w.IntField("minted", c.minted())
	w.IntField("reserved", c.reserved)
	if p := c.prov; p != nil {
		w.BoolField("useBeacon", c.useBeacon)
		w.StrField("beaconSource", c.beaconSource)
		w.IntField("round", p.round)
		w.StrField("creatorCommit", p.creatorCommit)
		w.StrField("beaconCommit", p.beaconCommit)
		w.StrField("entropy", p.acc)
		w.StrField("creatorSecret", p.creatorSecret)
		w.StrField("beaconSecret", p.beaconSecret)
		w.StrField("salt", p.salt)
		w.StrField("badge", p.badge)
		w.IntField("revealDeadline", revealDeadline(c))
		w.IntField("finalHeight", p.finalHeight)
		w.BoolField("verified", VerifyProvenance(cid))
		w.BoolField("fair", FairLaunch(cid))
	}
	w.EndObject()
	return w.String()
}

package core

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Pluggable randomness sources (beacon v2).
//
// A collection launched with useBeacon picks its second entropy source at
// Launch (LaunchSpec.BeaconSource, frozen by I-6):
//
//   - types.BeaconCommitted: the platform beacon's commit-reveal
//     (provenance.gno; BeaconCommit before the first mint,
//     RevealBeaconSecret after the creator).
//   - the package path of a randomness provider realm: a public random
//     value nobody can know in advance, e.g. a drand round relayed and
//     BLS-verified on chain (gnolang/gno#6268 p/drand + r/drand). Nothing
//     is committed before the sale; the round is fixed only once the
//     creator can no longer choose (RequestRandomness), then anyone pulls
//     its value (FulfillRandomness).
//
// A provider realm registers itself (its id is its package path, as for
// engines) and is usable only after the admin approves it through the
// timelocked op randomness.add; randomness.deprecate stops new launches,
// running collections finish with it. So a drand provider plugs in without
// a core redeploy. Its methods are declared in its own realm, so core
// calling them runs the provider with the provider's authority (interrealm
// v2 borrow rule #1): it cannot write core state, and with no cur it cannot
// call a core mutator.
//
// Order with a provider (same guarantees as the committed beacon, SA-M1):
//
//  1. the creator reveals until revealDeadline - BeaconGraceBlocks;
//  2. RequestRandomness (anyone) after the creator revealed, or inside the
//     grace period when it stayed silent, and no later than revealDeadline
//     - RequestMargin: binds the collection to provider.Target(), a round
//     whose value nobody knows yet — not the creator, whose secret is
//     public or whose window is closed, not the minters, whose sale is over;
//  3. FulfillRandomness (anyone) once the provider has that round: the
//     value becomes the beacon secret and the collection is Final at once
//     (2/2 after the creator, beacon-only in grace);
//  4. after revealDeadline Finalize works as before (creator-only /
//     fallback if the provider never delivered).
type RandomnessProvider interface {
	// Name is a short label for UIs, e.g. "drand quicknet".
	Name() string
	// Target is the round a request made in the current block is bound
	// to. Its value must be unknowable to anyone at this block (a round
	// published strictly in the future). Read-only.
	Target() int64
	// Randomness is round's verified value as 64 lowercase hex characters
	// (32 bytes), or "" while it is not available. Read-only.
	Randomness(round int64) string
}

type providerRecord struct {
	id               string
	name             string
	impl             RandomnessProvider
	active           bool // approved by the admin and not deprecated
	registeredHeight int64
}

var (
	providers       avl.Tree // provider pkgpath -> *providerRecord
	activeProviders int64
)

const MaxProviderNameLen = 64

// RegisterRandomnessProvider stores the calling realm's provider. It is
// inert until the admin approves it (randomness.add, timelocked).
func RegisterRandomnessProvider(cur realm, p RandomnessProvider) string {
	assertNoDeposit(cur)
	id := cur.Previous().PkgPath()
	if !strings.HasPrefix(id, runtime.ChainDomain()+"/r/") || strings.Contains(id, "#") {
		panic("a randomness provider registers from its own realm (an /r/ package, not a sub-realm or wallet)")
	}
	if p == nil {
		panic("nil provider")
	}
	if providers.Has(id) {
		panic("randomness provider already registered: " + id)
	}
	name := p.Name()
	safe.AssertNonEmptyText("provider name", name, MaxProviderNameLen)
	providers.Set(id, &providerRecord{id: id, name: name, impl: p, registeredHeight: height()})
	chain.Emit("RandomnessProviderRegistered", "id", id, "name", name)
	return id
}

func mustProvider(id string) *providerRecord {
	v := providers.Get(id)
	if v == nil {
		panic("unknown randomness provider " + id)
	}
	return v.(*providerRecord)
}

func assertActiveProvider(id string) {
	if !mustProvider(id).active {
		panic("randomness provider " + id + " is not approved")
	}
}

// beaconAvailable: some unpredictable second source exists, so no launch
// may opt out of it (SA-M2).
func beaconAvailable() bool { return beacon != "" || activeProviders > 0 }

func usesProvider(c *collection) bool {
	return c.useBeacon && c.beaconSource != types.BeaconCommitted
}

// RequestRandomness binds a provider-backed collection to the provider's
// next unknowable round. Permissionless and never paused (I-2).
func RequestRandomness(cur realm, cid string) int64 {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	assertRevealOpen(c, h)
	if !usesProvider(c) {
		panic("this collection does not use a randomness provider")
	}
	p := c.prov
	if p.round != 0 {
		panic("randomness already requested for round " + itoa(p.round))
	}
	dl := revealDeadline(c)
	if !p.creatorRevealed && h < dl-BeaconGraceBlocks {
		panic("randomness is requested after the creator reveals, or in the window's last " +
			itoa(BeaconGraceBlocks) + " blocks")
	}
	if h > dl-RequestMargin {
		panic("too late to request randomness (last height " + itoa(dl-RequestMargin) + "); call Finalize after the deadline")
	}
	round := mustProvider(c.beaconSource).impl.Target()
	if round <= 0 {
		panic("randomness provider returned an invalid round")
	}
	p.round = round
	chain.Emit("RandomnessRequested", "cid", cid, "provider", c.beaconSource, "round", itoa(round))
	return round
}

// FulfillRandomness takes the requested round's value from the provider as
// the beacon secret and finalizes (2/2 after the creator, beacon-only when
// it stayed silent). Permissionless and never paused (I-2).
func FulfillRandomness(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	assertRevealOpen(c, h)
	if !usesProvider(c) {
		panic("this collection does not use a randomness provider")
	}
	p := c.prov
	if p.round == 0 {
		panic("randomness was not requested yet")
	}
	v := mustProvider(c.beaconSource).impl.Randomness(p.round)
	if v == "" {
		panic("round " + itoa(p.round) + " is not available from the provider yet")
	}
	v = safe.AssertHex("randomness", v, 32)
	p.beaconSecret = v
	p.beaconRevealed = true
	chain.Emit("BeaconRevealed", "cid", cid, "provider", c.beaconSource, "round", itoa(p.round), "secret", v)
	finalize(c, h)
}

// RandomnessProviders lists registered providers (by path) as JSON:
// [{id, name, active, registeredHeight}]. Registration is open, so only
// "active" ones (admin-approved) can be chosen at Launch.
func RandomnessProviders(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	providers.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		r := v.(*providerRecord)
		w.BeginObject()
		w.StrField("id", r.id)
		w.StrField("name", r.name)
		w.BoolField("active", r.active)
		w.IntField("registeredHeight", r.registeredHeight)
		w.EndObject()
		return false
	})
	w.EndArray()
	return w.String()
}

package core

import (
	"chain"
	"strings"

	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Every function in this file is read-only (I-12: no exported non-crossing
// mutator). Lists are paginated with limit <= MaxPageSize (RA L-4).

// SelfAddress is core's package address, for the deploy-time cross-check
// against scripts/pkgaddr.py (RA H-5).
func SelfAddress() address { return chain.PackageAddress(selfPath) }

func CollectionCount() int64 { return collCount }

// MintedTotal counts every token ever minted, burned ones included (OA B4).
func MintedTotal(cid string) int64 { return mustCollection(cid).minted() }

// MintedBy is addr's lifetime count of sale mints in cid (OA B3, I-9),
// reserves excluded. Exact until the collection is Final, -1 afterwards
// (derived from the locked grc721 balance; see mintedBy).
func MintedBy(cid string, addr address) int64 { return mintedBy(mustCollection(cid), addr) }

// Info is the typed collection view for other realms.
func Info(cid string) types.CollectionInfo {
	c := mustCollection(cid)
	info := types.CollectionInfo{
		ID:          c.id,
		Name:        c.name,
		Symbol:      c.symbol,
		Description: c.description,
		Creator:     c.creator,
		Minter:      c.minter,
		EngineID:    c.engineID,
		Params:      c.params,
		State:       stateAt(c, height()),
		MaxSupply:   c.maxSupply,
		Minted:      c.minted(),
		Reserved:    c.reserved,
		StartHeight: c.startHeight,
		EndHeight:   c.endHeight,
		RoyaltyBps:  c.royaltyBps,
	}
	if c.prov != nil {
		info.RevealDeadline = revealDeadline(c)
		info.Badge = c.prov.badge
	}
	return info
}

// PrimaryPayees returns a copy of the frozen primary-sale split.
func PrimaryPayees(cid string) []types.Payee {
	return append([]types.Payee{}, mustCollection(cid).primaryPayees...)
}

// FeeConfig is the typed fee view minters and markets settle with.
func FeeConfig() types.Fees { return fees }

// PrimaryFeeBps is the protocol fee on cid's primary sale: the fee at
// Launch, or the current one if the admin lowered it since (SA-I5: a fee
// cannot rise during a sale).
func PrimaryFeeBps(cid string) int64 {
	c := mustCollection(cid)
	if c.prov != nil && c.primaryBps < fees.PrimaryBps {
		return c.primaryBps
	}
	return fees.PrimaryBps
}

func Beacon() address { return beacon }

func Admin() address { return admin }

func IsMinter(path string) bool {
	v := minters.Get(path)
	return v != nil && !v.(*minterRecord).deprecated
}

// Collection is the collection record as JSON.
func Collection(cid string) string {
	w := &safe.JSONWriter{}
	writeCollection(w, mustCollection(cid))
	return w.String()
}

func Collections(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	collections.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		writeCollection(w, v.(*collection))
		return false
	})
	w.EndArray()
	return w.String()
}

func CollectionsByCreator(creator address, offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	prefix := creator.String() + ":"
	skipped, written, want := int64(0), int64(0), clampLimit(limit)
	byCreator.Iterate(prefix, prefix+"\xff", func(_ string, v any) bool {
		if skipped < offset {
			skipped++
			return false
		}
		writeCollection(w, mustCollection(v.(string)))
		written++
		return written >= want
	})
	w.EndArray()
	return w.String()
}

// Fees is the fee configuration and its hard caps as JSON.
func Fees() string {
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("createFee", fees.CreateFee)
	w.IntField("primaryBps", fees.PrimaryBps)
	w.IntField("secondaryBps", fees.SecondaryBps)
	w.StrField("treasury", fees.Treasury.String())
	w.IntField("createFeeCap", CreateFeeCap)
	w.IntField("protocolFeeCapBps", ProtocolFeeCapBps)
	w.IntField("royaltyCapBps", RoyaltyCapBps)
	w.IntField("engineCapBps", fees.EngineCapBps)
	w.IntField("engineFeeCapBps", EngineFeeCapBps)
	w.EndObject()
	return w.String()
}

// PendingOps is the timelock queue as JSON.
func PendingOps() string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	ops.Iterate("", "", func(_ string, v any) bool {
		p := v.(*pendingOp)
		w.BeginObject()
		w.StrField("id", itoa(p.id))
		w.StrField("op", p.op)
		w.StrField("arg", p.arg)
		w.IntField("proposed", p.proposed)
		w.IntField("earliest", earliestExecution(p))
		w.EndObject()
		return false
	})
	w.EndArray()
	return w.String()
}

func writeCollection(w *safe.JSONWriter, c *collection) {
	h := height()
	w.BeginObject()
	w.StrField("cid", c.id)
	w.StrField("name", c.name)
	w.StrField("symbol", c.symbol)
	w.StrField("description", c.description)
	w.StrField("creator", c.creator.String())
	w.StrField("engine", c.engineID)
	w.StrField("params", c.params)
	w.StrField("minter", c.minter)
	w.StrField("state", stateAt(c, h).String())
	w.IntField("maxSupply", c.maxSupply)
	w.IntField("minted", c.minted())
	w.IntField("reserved", c.reserved)
	w.IntField("royaltyBps", c.royaltyBps)
	w.StrField("royaltyAddress", royaltyAddress(c.id).String())
	w.StrField("primaryPayees", safe.FormatPayees(c.primaryPayees))
	w.StrField("royaltyPayees", safe.FormatPayees(c.royaltyPayees))
	w.IntField("startHeight", c.startHeight)
	w.IntField("endHeight", c.endHeight)
	w.IntField("createdHeight", c.createdHeight)
	w.StrField("token", c.token.ID())
	author, bps := collectionEngineFee(c)
	w.StrField("engineAuthor", author.String())
	w.IntField("engineFeeBps", bps)
	if c.prov != nil {
		w.IntField("revealDeadline", revealDeadline(c))
		w.BoolField("useBeacon", c.useBeacon)
		w.StrField("beaconSource", c.beaconSource)
		w.StrField("badge", c.prov.badge)
		w.BoolField("fair", FairLaunch(c.id))
	}
	w.EndObject()
}

func clampLimit(limit int64) int64 {
	if limit <= 0 || limit > MaxPageSize {
		return MaxPageSize
	}
	return limit
}

// Render stays minimal in the immutable realm; the browsable gallery is the
// private, re-deployable gallery realm (design §2.5.7).
func Render(path string) string {
	gallery := strings.TrimPrefix(strings.TrimSuffix(selfPath, "/core")+"/gallery", "gno.land")
	return ufmt.Sprintf("# Collections ledger\n\n%d collections, %d engines. Browse them in the [gallery](%s).\n",
		collCount, engineCount, gallery)
}

package core

import (
	"chain"
	"chain/banker"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// Each collection's royalty receiver is its own sub-treasury
// DerivePkgSubAddr(core, "roy/<cid>"), written into the official royalty
// extension at creation. Any market can pay it through RoyaltyInfo; the
// creator can re-split it later (SetPayees) without touching the receiver.
// Only core can spend it: a banker for a sub-address needs core's live
// cur.Sub (interrealm v2 §5.5).

func royaltyAddress(cid string) address {
	return chain.DerivePkgSubAddr(selfPath, "roy/"+cid)
}

// RoyaltyAddress is the collection's royalty sub-treasury.
func RoyaltyAddress(cid string) address {
	mustCollection(cid)
	return royaltyAddress(cid)
}

// DistributeRoyalties pushes the whole sub-treasury balance to the royalty
// payees. Permissionless and never paused (I-2); market/v1 calls it after
// every sale. Returns the amount distributed. The sub-realm banker spend
// is verified by spike/subtoken, core and market tests on gno v1.7.0.
func DistributeRoyalties(cur realm, cid string) int64 {
	assertNoDeposit(cur)
	return distribute(cur, mustCollection(cid))
}

func distribute(cur realm, c *collection) int64 {
	cid := c.id
	sub := cur.Sub("roy/" + cid)
	bal := banker.NewReadonlyBanker().GetCoin(sub.Address(), "ugnot")
	if bal <= 0 {
		return 0
	}
	shares := safe.SplitByBps(bal, c.royaltyPayees)
	bk := banker.NewBanker(banker.BankerTypeRealmSend, sub)
	for i, p := range c.royaltyPayees {
		if shares[i] > 0 {
			bk.SendCoins(sub.Address(), p.Addr, chain.NewCoins(chain.NewCoin("ugnot", shares[i])))
		}
	}
	chain.Emit("RoyaltiesDistributed", "cid", cid, "amount", itoa(bal))
	return bal
}

package core

import (
	"chain"
	"encoding/base64"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/royalty/v0"
	"gno.land/p/nt/grc721/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// tokenState is the per-collection data the transfer hook needs. It is
// shared by the collection and its lockExt, so neither points at the other.
//
// Per-token state is packed (storage-cost-analysis P1+P3): one fixed-width
// entry of packEntry bytes per token, packSlots tokens per avl key. Entry =
// four big-endian uint32 fields: mint height, transfer count (H-2), height
// of the last transfer, and the token's approval nonce (SA-L3). A mint
// appends entries in tid order (a new key every packSlots tokens, ~2 KB the
// minter of that bucket's first token pays); a transfer or an Approve only
// rewrites bytes in place, so neither creates a storage object.
type tokenState struct {
	final bool
	pack  avl.Tree // safe.PadInt((tid-1)/packSlots, packKeyWidth) -> string of packed entries
}

const (
	packSlots    = 128
	packFields   = 4
	packEntry    = packFields * 4
	packKeyWidth = 3 // MaxSupplyCap/packSlots < 1000

	fieldMintHeight = 0
	fieldMoves      = 1
	fieldLastMove   = 2
	fieldNonce      = 3
)

func packKey(tid int64) string { return safe.PadInt((tid-1)/packSlots, packKeyWidth) }

// u32 encodes v as 4 big-endian bytes. Heights stay below 2^32 for ~470
// years of 3.5 s blocks; 2^32 transfers or approvals of one token cannot
// happen, so overflow is a hard error rather than a wrap.
func u32(v int64) string {
	if v < 0 || v > 0xFFFFFFFF {
		panic("token state: value out of uint32 range")
	}
	return string([]byte{byte(v >> 24), byte(v >> 16), byte(v >> 8), byte(v)})
}

// appendTokens adds zeroed entries (mint height h) for first..last, which
// must directly follow the last stored token.
func (st *tokenState) appendTokens(first, last, h int64) {
	entry := u32(h) + u32(0) + u32(0) + u32(0)
	for tid := first; tid <= last; {
		k := packKey(tid)
		v, _ := st.pack.Get(k).(string)
		if int64(len(v)) != ((tid-1)%packSlots)*packEntry {
			panic("token state: tokens must be appended in order")
		}
		for ; tid <= last && packKey(tid) == k; tid++ {
			v += entry
		}
		st.pack.Set(k, v)
	}
}

// field reads one field of token tid; 0 for a token that was never minted.
func (st *tokenState) field(tid int64, f int) int64 {
	if tid <= 0 {
		return 0
	}
	v, _ := st.pack.Get(packKey(tid)).(string)
	off := int((tid-1)%packSlots)*packEntry + f*4
	if off+4 > len(v) {
		return 0
	}
	return int64(v[off])<<24 | int64(v[off+1])<<16 | int64(v[off+2])<<8 | int64(v[off+3])
}

// setFields rewrites one or two fields of token tid in place (one avl
// update; f2 < 0 means none).
func (st *tokenState) setFields(tid int64, f1 int, v1 int64, f2 int, v2 int64) {
	k := packKey(tid)
	v, _ := st.pack.Get(k).(string)
	base := int((tid-1)%packSlots) * packEntry
	if tid <= 0 || base+packEntry > len(v) {
		panic("token state: unknown token")
	}
	o1 := base + f1*4
	v = v[:o1] + u32(v1) + v[o1+4:]
	if f2 >= 0 {
		o2 := base + f2*4
		v = v[:o2] + u32(v2) + v[o2+4:]
	}
	st.pack.Set(k, v)
}

func (st *tokenState) mintHeight(tid int64) int64 { return st.field(tid, fieldMintHeight) }

func (st *tokenState) moveOf(tid string) (moves, lastMove int64) {
	n := tidNum(tid)
	return st.field(n, fieldMoves), st.field(n, fieldLastMove)
}

// tidNum is the numeric token id, or 0 for anything that is not a
// canonical positive decimal (no such token exists).
func tidNum(tid string) int64 {
	if len(tid) == 0 || len(tid) > 12 || tid[0] == '0' {
		return 0
	}
	var n int64
	for i := 0; i < len(tid); i++ {
		c := tid[i]
		if c < '0' || c > '9' {
			return 0
		}
		n = n*10 + int64(c-'0')
	}
	return n
}

// lockExt is the grc721 Extension behind two invariants:
//
//   - I-11: before Final no token moves or burns (the reveal lock that
//     closes RA H-3's information-advantage branch). The veto is a panic,
//     which aborts the whole transaction — the documented Extension
//     semantics of p/nt/grc721/v0.
//   - H-2: every transfer bumps the token's move counter, so a market
//     listing taken at moves=N is dead after any transfer, even if the
//     token later comes back to the seller.
//
// It is declared in this realm, so the hooks write core state with core's
// authority even when another realm moves the token via RealmTeller.
type lockExt struct {
	cid string
	st  *tokenState
}

const lockKind = "art-lock"

func (e *lockExt) ExtensionKind() string { return lockKind }

// The hooks also emit the platform's per-token history events with the
// collection id ("Minted", "Transfer"); grc721's own Transfer event carries
// only the token's grc721 id.
func (e *lockExt) OnMint(to address, tid grc721.TokenID) {
	chain.Emit("Minted", "cid", e.cid, "tid", tid.String(), "to", to.String())
}

func (e *lockExt) OnTransfer(from, to address, tid grc721.TokenID) {
	if !e.st.final {
		panic("tokens are locked until the collection is final (reveal)")
	}
	key := tid.String()
	n := tidNum(key)
	e.st.setFields(n, fieldMoves, e.st.field(n, fieldMoves)+1, fieldLastMove, height())
	chain.Emit("Transfer", "cid", e.cid, "tid", key, "from", from.String(), "to", to.String())
}

func (e *lockExt) OnBurn(tid grc721.TokenID) {
	if !e.st.final {
		panic("tokens are locked until the collection is final (reveal)")
	}
	// the packed entry stays: a burned id is never minted again (I-5)
}

// --- owner actions (I-2: never paused) ---------------------------------------
//
// The acting account is always the immediate caller (cur.Previous()), the
// same rule as grc721's CallerTeller: a realm a user merely calls cannot act
// for that user. Another realm moves tokens only after an Approve, through
// Token(cid).RealmTeller (market/v1 does exactly that).

// Every Approve of a token and every SetApprovalForAll of an (owner,
// operator) pair bumps a nonce. A market pins the nonces at listing time,
// so revoking an approval kills a listing for good: approving again later
// starts a new nonce and never revives the old listing (SA-L3).
func Approve(cur realm, cid, tid string, to address) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if err := c.ledger.Approve(caller(cur), to, grc721.TokenID(tid)); err != nil {
		panic(err)
	}
	n := tidNum(tid)
	c.st.setFields(n, fieldNonce, c.st.field(n, fieldNonce)+1, -1, 0)
}

func SetApprovalForAll(cur realm, cid string, operator address, approved bool) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	owner := caller(cur)
	if err := c.ledger.SetApprovalForAll(owner, operator, approved); err != nil {
		panic(err)
	}
	bumpNonce(c, "o:"+owner.String()+":"+operator.String())
}

// ApprovalNonces returns the token's approval nonce and the (owner,
// operator) approval-for-all nonce. Approvals made directly through
// Token(cid).RealmTeller by a realm acting for itself do not bump them.
func ApprovalNonces(cid, tid string, owner, operator address) (tokenNonce, operatorNonce int64) {
	c := mustCollection(cid)
	return c.st.field(tidNum(tid), fieldNonce), nonceOf(c, "o:"+owner.String()+":"+operator.String())
}

func bumpNonce(c *collection, key string) {
	c.approvals.Set(key, nonceOf(c, key)+1)
}

func nonceOf(c *collection, key string) int64 {
	if v := c.approvals.Get(key); v != nil {
		return v.(int64)
	}
	return 0
}

func TransferFrom(cur realm, cid, tid string, from, to address) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if err := c.ledger.TransferFrom(caller(cur), from, to, grc721.TokenID(tid)); err != nil {
		panic(err)
	}
}

// Burn is owner-only. The supply gate uses nextTID, so a burn never reopens
// a slot (I-5).
func Burn(cur realm, cid, tid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	owner, err := c.token.OwnerOf(grc721.TokenID(tid))
	if err != nil {
		panic(err)
	}
	if owner != caller(cur) {
		panic("only the owner can burn a token")
	}
	if err := c.ledger.Burn(grc721.TokenID(tid)); err != nil {
		panic(err)
	}
}

// --- token reads ---------------------------------------------------------------

// Token publishes the collection's official *grc721.Token. Its exported
// methods are reads or teller factories that need the caller's live realm;
// the ledger itself is never published.
func Token(cid string) *grc721.Token { return mustCollection(cid).token }

// Royalty publishes the read-only royalty view (EIP-2981 RoyaltyInfo).
func Royalty(cid string) *royalty.Royalty { return mustCollection(cid).roy }

func OwnerOf(cid, tid string) (address, error) {
	return mustCollection(cid).token.OwnerOf(grc721.TokenID(tid))
}

func BalanceOf(cid string, owner address) (int64, error) {
	return mustCollection(cid).token.BalanceOf(owner)
}

// TokenMoves is the transfer counter market/v1 pins in a listing (H-2).
func TokenMoves(cid, tid string) int64 {
	n, _ := mustCollection(cid).st.moveOf(tid)
	return n
}

// TokenSeed is "" until the collection is Final: no read path can leak the
// rarity map early.
func TokenSeed(cid, tid string) string {
	c := mustCollection(cid)
	if !c.st.final || !exists(c, tid) {
		return ""
	}
	return safe.Seed(c.id, tid, c.prov.salt)
}

// TokenState is {mintHeight, lastMoveHeight, moves} as JSON.
func TokenState(cid, tid string) string {
	c := mustCollection(cid)
	if !exists(c, tid) {
		panic(grc721.ErrInvalidTokenId)
	}
	in := tokenInput(c, tid)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("mintHeight", in.MintHeight)
	w.IntField("lastMoveHeight", in.LastMoveHeight)
	w.IntField("moves", in.Moves)
	w.EndObject()
	return w.String()
}

// TokenURI is a base64 SVG data URI. Before Final every token shows core's
// neutral placeholder, never engine output (design §4.2).
func TokenURI(cid, tid string) (string, error) {
	c := mustCollection(cid)
	if _, err := c.token.OwnerOf(grc721.TokenID(tid)); err != nil {
		return "", err
	}
	if !c.st.final {
		return dataURI(placeholderSVG(c.name, "Unrevealed")), nil
	}
	return dataURI(renderToken(c, tid)), nil
}

// TokenTraits is [{"trait_type":…,"value":…}] JSON.
func TokenTraits(cid, tid string) string {
	c := mustCollection(cid)
	w := &safe.JSONWriter{}
	writeTraits(w, tokenTraits(c, tid))
	return w.String()
}

// TokenTraitList is the typed form of TokenTraits for other realms (a copy).
func TokenTraitList(cid, tid string) []engine.Trait {
	return append([]engine.Trait{}, tokenTraits(mustCollection(cid), tid)...)
}

// TokenMetadata is OpenSea-style metadata JSON.
func TokenMetadata(cid, tid string) string {
	c := mustCollection(cid)
	uri, err := TokenURI(cid, tid)
	if err != nil {
		panic(err)
	}
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("name", c.name+" #"+tid)
	w.StrField("description", c.description)
	w.StrField("image", uri)
	w.Key("attributes")
	writeTraits(w, tokenTraits(c, tid))
	w.EndObject()
	return w.String()
}

func exists(c *collection, tid string) bool {
	_, err := c.token.OwnerOf(grc721.TokenID(tid))
	return err == nil
}

func tokenInput(c *collection, tid string) engine.Input {
	n := safe.ParseID("tid", tid)
	moves, lastMove := c.st.moveOf(tid)
	mh := c.st.mintHeight(n)
	if lastMove == 0 {
		lastMove = mh
	}
	in := engine.Input{
		Params:         c.params,
		CollectionID:   c.id,
		TokenID:        tid,
		MintHeight:     mh,
		LastMoveHeight: lastMove,
		Moves:          moves,
		Height:         height(),
	}
	if c.st.final {
		in.Seed = safe.Seed(c.id, tid, c.prov.salt)
	}
	return in
}

// renderToken runs the collection's engine on a read path. A bad output
// degrades to a placeholder; a panicking engine only fails reads of its own
// collections (interrealm v2 §9: cross-realm panics abort the query).
func renderToken(c *collection, tid string) string {
	rec := mustEngine(c.engineID)
	svg := rec.impl.Render(tokenInput(c, tid))
	if err := engine.CheckSVG(rec.manifest, svg); err != nil {
		return placeholderSVG(c.name, "Engine output rejected")
	}
	return svg
}

func tokenTraits(c *collection, tid string) []engine.Trait {
	if !exists(c, tid) {
		panic(grc721.ErrInvalidTokenId)
	}
	if !c.st.final {
		return []engine.Trait{{Type: "Status", Value: "Unrevealed"}}
	}
	rec := mustEngine(c.engineID)
	ts := rec.impl.Traits(tokenInput(c, tid))
	if err := engine.ValidateTraits(rec.manifest, ts); err != nil {
		return []engine.Trait{{Type: "Status", Value: "Engine output rejected"}}
	}
	return ts
}

func writeTraits(w *safe.JSONWriter, ts []engine.Trait) {
	w.BeginArray()
	for _, t := range ts {
		w.BeginObject()
		w.StrField("trait_type", t.Type)
		w.StrField("value", t.Value)
		w.EndObject()
	}
	w.EndArray()
}

// placeholderSVG is core's own neutral art: identical for every token of a
// collection, so it carries no rarity signal.
func placeholderSVG(name, label string) string {
	return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">` +
		`<rect width="512" height="512" fill="#111"/>` +
		`<text x="256" y="236" fill="#ddd" font-family="monospace" font-size="24" text-anchor="middle">` +
		safe.XMLEscape(name) + `</text>` +
		`<text x="256" y="286" fill="#888" font-family="monospace" font-size="18" text-anchor="middle">` +
		safe.XMLEscape(label) + `</text></svg>`
}

func dataURI(svg string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg))
}

// emitBatch announces one MintTo ("MintBatch") or ReserveTo ("Reserved")
// call; each token also gets its own "Minted" event from lockExt.
func emitBatch(kind string, c *collection, to address, first, last int64) {
	chain.Emit(kind, "cid", c.id, "to", to.String(), "first", itoa(first), "last", itoa(last))
}

// Package genesis is the thin adapter that registers the genesis engine
// (p/…/art/art/genesis/v1) with core. It dogfoods the third-party path: core
// knows genesis only as this realm's package path plus an interface value.
//
// The adapter is stateless and has no admin: what it renders is fixed by
// the p/ package it imports, which can never change. Never mark this realm
// private (design §5.4: a re-deployable adapter could swap the art).
package genesis

import (
	art "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/art/genesis/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/core"
)

// author is the address that claims the engine in core (ClaimEngine).
// TODO(mainnet): the platform's engine-author key, not the deployer.
var author = address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06")

func Author() address { return author }

// AuthorFeeBps is the genesis author's fee on sales of collections by other
// creators (engine.Manifest.FeeBps; 0 for the author's own collections).
// TODO(mainnet): product decision; 1% here so Onyx exercises the path.
const AuthorFeeBps = 100

// impl is zero-size and declared here, so core runs it with this realm's
// authority (interrealm v2 borrow rule #1).
type impl struct{}

func (impl) Manifest() engine.Manifest {
	m := art.Manifest()
	m.Author = author
	m.FeeBps = AuthorFeeBps
	return m
}

func (impl) ValidateParams(params string) error { return art.ValidateParams(params) }

func (impl) Traits(in engine.Input) []engine.Trait { return art.Traits(in) }

func (impl) Render(in engine.Input) string { return art.Render(in) }

// Register is an explicit call, not init: under the inert package policy
// init runs inside the approver's transaction (RA B-1). Anyone may call it;
// it can only ever register this realm, once.
func Register(cur realm) string {
	return core.RegisterEngine(cross(cur), impl{})
}

// RenderSeed and TraitsSeed are the plan-B surface (design §5.6): if
// dynamic registration fails on chain, readers call the engine directly.
func RenderSeed(seed, params string) string {
	if err := art.ValidateParams(params); err != nil {
		panic(err)
	}
	return art.SVG(seed)
}

func TraitsSeed(seed, params string) []engine.Trait {
	in := engine.SampleInput()
	in.Seed, in.Params = seed, params
	if err := art.ValidateParams(params); err != nil {
		panic(err)
	}
	return art.Traits(in)
}

package mint

import (
	"strings"

	"gno.land/r/sys/users"
	validators "gno.land/r/sys/validators/v2"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/core"
)

// Allowlist sets (design §4.6). A phase's set is a comma-separated
// union of terms; an address is eligible if any term admits it:
//
//	users             registered in r/sys/users (live check)
//	validators        in the active validator set (live check)
//	holders:<cid>     holds a token of collection <cid>
//	merkle:<root>     in a sha256 merkle tree; the minter passes the proof
//
// A term may carry "|"-separated provenance notes for humans, e.g.
// "merkle:<root>|src:<git-sha>|data:<sha256>"; notes never affect logic.
const (
	MaxSetLen   = 512
	MaxSetTerms = 4
)

type setTerm struct {
	name, arg string
}

// parseSet validates a set and returns its terms; it panics on any error so
// AddPhase rejects a malformed set before it is ever frozen.
func parseSet(set string) []setTerm {
	safe.AssertText("set", set, MaxSetLen)
	parts := strings.Split(set, ",")
	if len(parts) > MaxSetTerms {
		panic("set: at most 4 terms")
	}
	terms := make([]setTerm, 0, len(parts))
	for _, part := range parts {
		body, _, _ := strings.Cut(part, "|")
		name, arg, _ := strings.Cut(body, ":")
		switch name {
		case "users", "validators":
			if arg != "" {
				panic("set: " + name + " takes no argument")
			}
		case "holders":
			core.Info(arg) // panics for an unknown collection
		case "merkle":
			arg = safe.AssertHex("set merkle root", arg, 32)
		default:
			panic("set: unknown term " + name)
		}
		terms = append(terms, setTerm{name: name, arg: arg})
	}
	return terms
}

// eligible reports whether addr may mint in a phase with this set, and why
// not. Live sets are evaluated at mint time, so a deleted user or a removed
// validator loses eligibility immediately.
func eligible(cid, set string, addr address, proof string) (bool, string) {
	if set == "" {
		return true, ""
	}
	for _, t := range parseSet(set) {
		switch t.name {
		case "users":
			if users.ResolveAddress(addr) != nil {
				return true, ""
			}
		case "validators":
			if validators.IsValidator(addr) {
				return true, ""
			}
		case "holders":
			if n, err := core.BalanceOf(t.arg, addr); err == nil && n > 0 {
				return true, ""
			}
		case "merkle":
			// an empty proof is valid for a one-address tree (root == leaf, SA-L4)
			if safe.MerkleVerify(t.arg, safe.AllowlistLeaf(cid, addr), proof) {
				return true, ""
			}
		}
	}
	return false, "address is not in this phase's allowlist (" + set + ")"
}

// Package mint is the platform's first minter (design §2.5.3): sale
// phases, fixed price or Dutch auction, live and merkle allowlists, lifetime
// wallet caps, and payment settlement. It is replaceable: core binds each
// collection to the minter that created it, so a future mint/v2 serves new
// collections without touching sales in progress.
//
// Creator flow (one multi-message transaction from the frontend; safety does
// not depend on atomicity because nobody can mint a Draft):
//
//	Create -> AddPhase x1..3 -> Launch
//
// Collector flow: Mint, with Price / Phases / Eligible as the read side.
package mint

import (
	"chain"
	"chain/runtime"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/core"
)

const MaxPhases = 3

// sale is this minter's per-collection state. Phases can change only while
// core says Draft; after Launch they are frozen with the rest (I-6).
type sale struct {
	phases []types.Phase
}

var sales avl.Tree // cid -> *sale

// Create opens a Draft collection for the calling wallet and pays the
// protocol's create fee from the attached ugnot (excess refunded).
// Empty payee strings default to "creator:10000". expectedCID, when set,
// makes the transaction fail instead of creating a different id than the
// frontend showed (OA B2).
func Create(cur realm, name, symbol, description, engineID, params string,
	maxSupply, royaltyBps int64, primaryPayees, royaltyPayees, expectedCID string,
) string {
	paid := received(cur)
	creator := cur.Previous().Address()
	fee := core.FeeConfig()
	if paid < fee.CreateFee {
		panic("create fee is " + itoa(fee.CreateFee) + "ugnot, sent " + itoa(paid))
	}
	self := creator.String() + ":10000"
	if primaryPayees == "" {
		primaryPayees = self
	}
	if royaltyPayees == "" {
		royaltyPayees = self
	}

	cid := core.CreateCollection(cross(cur), creator, types.CollectionSpec{
		Name: name, Symbol: symbol, Description: description,
		EngineID: engineID, Params: params,
		MaxSupply: maxSupply, RoyaltyBps: royaltyBps,
		PrimaryPayees: primaryPayees, RoyaltyPayees: royaltyPayees,
	})
	if expectedCID != "" && cid != expectedCID {
		panic("collection id would be " + cid + ", expected " + expectedCID + "; retry")
	}
	sales.Set(cid, &sale{})

	pay(cur, fee.Treasury, fee.CreateFee)
	pay(cur, creator, paid-fee.CreateFee)
	return cid
}

// AddPhase appends a sale phase. Phases are ordered and do not overlap.
// kind is "allow" (set required) or "public" (set empty); a fixed price has
// startPrice == floorPrice and zero steps; walletCap 0 means no cap.
func AddPhase(cur realm, cid, kind, set string,
	startHeight, endHeight, startPrice, floorPrice, stepBlocks, stepAmount, walletCap int64,
) {
	assertNoDeposit(cur)
	s := mustDraftSale(cur, cid)
	if len(s.phases) >= MaxPhases {
		panic("at most " + itoa(MaxPhases) + " phases")
	}
	p := types.Phase{
		Kind: kind, Set: set,
		StartHeight: startHeight, EndHeight: endHeight,
		StartPrice: startPrice, FloorPrice: floorPrice,
		StepBlocks: stepBlocks, StepAmount: stepAmount,
		WalletCap: walletCap,
	}
	if err := p.Validate(); err != nil {
		panic(err)
	}
	if set != "" {
		parseSet(set)
	}
	if n := len(s.phases); n > 0 && p.StartHeight <= s.phases[n-1].EndHeight {
		panic("phases must not overlap: start after height " + itoa(s.phases[n-1].EndHeight))
	}
	s.phases = append(s.phases, p)
	chain.Emit("PhaseAdded", "cid", cid, "index", itoa(int64(len(s.phases)-1)), "kind", kind, "set", set)
}

// ClearPhases removes every phase of a Draft.
func ClearPhases(cur realm, cid string) {
	assertNoDeposit(cur)
	s := mustDraftSale(cur, cid)
	s.phases = nil
	chain.Emit("PhasesCleared", "cid", cid)
}

// Launch freezes the sale. creatorCommit is safe.Commit(chainID, cid,
// "creator", secret), computed off-chain — never send the secret to a node
// before reveal. beaconSource (with useBeacon) is "" / "committed" for the
// platform beacon or an approved randomness provider's package path
// (core.RandomnessProviders). The engine-author fee is snapshotted here.
func Launch(cur realm, cid, creatorCommit string, revealWindow int64, useBeacon bool, beaconSource string) {
	assertNoDeposit(cur)
	s := mustDraftSale(cur, cid)
	if len(s.phases) == 0 {
		panic("add at least one phase before launching")
	}
	core.Launch(cross(cur), cid, types.LaunchSpec{
		StartHeight:   s.phases[0].StartHeight,
		EndHeight:     s.phases[len(s.phases)-1].EndHeight,
		RevealWindow:  revealWindow,
		CreatorCommit: creatorCommit,
		UseBeacon:     useBeacon,
		BeaconSource:  beaconSource,
	})
}

// Abort returns a launched collection with no mints to Draft (core rules).
func Abort(cur realm, cid string) {
	assertNoDeposit(cur)
	assertCreator(cur, cid)
	core.AbortLaunch(cross(cur), cid)
}

// Reserve mints the creator's reserve to the creator before the sale.
func Reserve(cur realm, cid string, count int64) string {
	assertNoDeposit(cur)
	creator := assertCreator(cur, cid)
	first, last := core.ReserveTo(cross(cur), cid, creator, count)
	return itoa(first) + "-" + itoa(last)
}

// Mint buys count tokens in the phase open at this block, at that block's
// unit price, never above maxUnitPrice (a Dutch step cannot surprise the
// buyer). proof is the merkle proof for merkle sets, otherwise "". Returns
// "first-last". Every attached unit is paid out or refunded (I-3, I-4).
func Mint(cur realm, cid string, count, maxUnitPrice int64, proof string) string {
	paid := received(cur)
	buyer := cur.Previous().Address()
	h := runtime.ChainHeight()
	p, ok := mustSale(cid).phaseAt(h)
	if !ok {
		panic("no sale phase is open at height " + itoa(h))
	}
	if count <= 0 || count > core.MaxMintPerTx {
		panic("count must be 1.." + itoa(core.MaxMintPerTx))
	}
	if ok, reason := eligible(cid, p.Set, buyer, proof); !ok {
		panic(reason)
	}
	if p.WalletCap > 0 && core.MintedBy(cid, buyer)+count > p.WalletCap {
		panic("wallet cap: " + itoa(p.WalletCap) + " per wallet, already minted " + itoa(core.MintedBy(cid, buyer)))
	}
	price := p.PriceAt(h)
	if price > maxUnitPrice {
		panic("unit price at this block is " + itoa(price) + "ugnot, above maxUnitPrice " + itoa(maxUnitPrice))
	}
	cost := price * count
	if paid < cost {
		panic("send " + itoa(cost) + "ugnot, sent " + itoa(paid))
	}

	first, last := core.MintTo(cross(cur), cid, buyer, count)

	fee := core.FeeConfig()
	sp := split(cid, cost)
	pay(cur, fee.Treasury, sp.protocol)
	pay(cur, sp.engineAuthor, sp.engine)
	for i, payee := range sp.payees {
		pay(cur, payee.Addr, sp.shares[i])
	}
	pay(cur, buyer, paid-cost)

	chain.Emit("Sale", "cid", cid, "buyer", buyer.String(), "first", itoa(first), "last", itoa(last),
		"unitPrice", itoa(price), "protocolFee", itoa(sp.protocol), "engineFee", itoa(sp.engine),
		"engineAuthor", sp.engineAuthor.String())
	return itoa(first) + "-" + itoa(last)
}

// primarySplit is how a primary sale of `amount` is paid (I-4: protocol +
// engine + sum(shares) == amount): the protocol fee frozen at Launch
// (SA-I5), the engine author's fee (snapshot at Launch, 0 when the creator
// is the author), the rest split over the frozen primary payees.
type primarySplit struct {
	protocol, engine int64
	engineAuthor     address
	payees           []types.Payee
	shares           []int64
}

func split(cid string, amount int64) primarySplit {
	sp := primarySplit{protocol: safe.BpsOf(amount, core.PrimaryFeeBps(cid))}
	author, bps := core.EngineFee(cid)
	sp.engineAuthor, sp.engine = author, safe.BpsOf(amount, bps)
	sp.payees = core.PrimaryPayees(cid)
	sp.shares = safe.SplitByBps(amount-sp.protocol-sp.engine, sp.payees)
	return sp
}

func (s *sale) phaseAt(h int64) (types.Phase, bool) {
	for _, p := range s.phases {
		if p.Covers(h) {
			return p, true
		}
	}
	return types.Phase{}, false
}

func mustSale(cid string) *sale {
	v := sales.Get(cid)
	if v == nil {
		panic("collection " + cid + " was not created by this minter")
	}
	return v.(*sale)
}

func mustDraftSale(cur realm, cid string) *sale {
	assertCreator(cur, cid)
	if core.Info(cid).State != types.StateDraft {
		panic("phases are frozen after launch")
	}
	return mustSale(cid)
}

func assertCreator(cur realm, cid string) address {
	who := cur.Previous().Address()
	if core.Info(cid).Creator != who {
		panic("only the collection's creator can do this")
	}
	return who
}

// --- reads -------------------------------------------------------------------

// Price is the unit price at height h, or -1 when no phase covers h.
func Price(cid string, h int64) int64 {
	p, ok := mustSale(cid).phaseAt(h)
	if !ok {
		return -1
	}
	return p.PriceAt(h)
}

// Phases is the phase list as JSON.
func Phases(cid string) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	for _, p := range mustSale(cid).phases {
		w.BeginObject()
		w.StrField("kind", p.Kind)
		w.StrField("set", p.Set)
		w.IntField("startHeight", p.StartHeight)
		w.IntField("endHeight", p.EndHeight)
		w.IntField("startPrice", p.StartPrice)
		w.IntField("floorPrice", p.FloorPrice)
		w.IntField("stepBlocks", p.StepBlocks)
		w.IntField("stepAmount", p.StepAmount)
		w.IntField("walletCap", p.WalletCap)
		w.EndObject()
	}
	w.EndArray()
	return w.String()
}

// Eligible answers "can addr mint now, and how many?" with the same checks
// Mint runs, so the UI never disagrees with the chain (OA B3). JSON:
// {phase, kind, eligible, reason, remainingCap (-1 = no cap), price}.
func Eligible(cid string, addr address, proof string) string {
	h := runtime.ChainHeight()
	w := &safe.JSONWriter{}
	w.BeginObject()
	idx, p := -1, types.Phase{}
	for i, q := range mustSale(cid).phases {
		if q.Covers(h) {
			idx, p = i, q
			break
		}
	}
	w.IntField("phase", int64(idx))
	if idx < 0 {
		w.BoolField("eligible", false)
		w.StrField("reason", "no sale phase is open at height "+itoa(h))
		w.EndObject()
		return w.String()
	}
	ok, reason := eligible(cid, p.Set, addr, proof)
	remaining := int64(-1)
	if p.WalletCap > 0 {
		minted := core.MintedBy(cid, addr) // -1 once Final: nothing left to mint anyway
		if minted < 0 {
			minted = p.WalletCap
		}
		remaining = p.WalletCap - minted
		if remaining < 0 {
			remaining = 0
		}
		if remaining == 0 && ok {
			ok, reason = false, "wallet cap reached"
		}
	}
	if ok && core.Info(cid).State != types.StateMinting {
		ok, reason = false, "collection is not minting"
	}
	w.StrField("kind", p.Kind)
	w.BoolField("eligible", ok)
	w.StrField("reason", reason)
	w.IntField("remainingCap", remaining)
	w.IntField("price", p.PriceAt(h))
	w.EndObject()
	return w.String()
}

// Quote is what Mint(cid, count, …) pays at height h, as JSON: {count,
// unitPrice, cost, protocolFee, protocolBps, engineFee, engineBps,
// engineAuthor, payees:[{address, amount}]}; unitPrice -1 outside phases.
func Quote(cid string, count, h int64) string {
	price := Price(cid, h)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("count", count)
	w.IntField("unitPrice", price)
	if price < 0 || count <= 0 || count > core.MaxMintPerTx {
		w.EndObject()
		return w.String()
	}
	cost := price * count
	sp := split(cid, cost)
	_, bps := core.EngineFee(cid)
	w.IntField("cost", cost)
	w.IntField("protocolFee", sp.protocol)
	w.IntField("protocolBps", core.PrimaryFeeBps(cid))
	w.IntField("engineFee", sp.engine)
	w.IntField("engineBps", bps)
	w.StrField("engineAuthor", sp.engineAuthor.String())
	w.Key("payees")
	w.BeginArray()
	for i, p := range sp.payees {
		w.BeginObject()
		w.StrField("address", p.Addr.String())
		w.IntField("amount", sp.shares[i])
		w.EndObject()
	}
	w.EndArray()
	w.EndObject()
	return w.String()
}

func Render(path string) string {
	if path == "" {
		return "# mint/v1\n\nSale phases of the platform's collections. Use `:<cid>` for one collection.\n"
	}
	s := mustSale(path) // only known collection ids get this far
	out := "# Sale of collection " + path + "\n\n"
	for i, p := range s.phases {
		out += ufmt.Sprintf("%d. %s phase, heights %d-%d, price %d -> %d ugnot, wallet cap %d\n",
			i+1, p.Kind, p.StartHeight, p.EndHeight, p.StartPrice, p.FloorPrice, p.WalletCap)
	}
	return out
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package mint

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// I-3: this realm holds no balance. Each paying function receives the
// attached ugnot and pushes every unit out before returning: protocol fee,
// creator payees, and the refund. Nothing is ever kept for later.

// received returns the ugnot attached to a direct wallet call. Payments are
// accepted only when a wallet called us: the origin-send envelope is shared
// by every realm on the path, so a realm in between could have consumed it
// (chain/runtime/unsafe.OriginSend).
func received(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payments must come directly from a wallet, not through another realm")
	}
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != "ugnot" && c.Amount != 0 {
			panic("only ugnot is accepted")
		}
	}
	return sent.AmountOf("ugnot")
}

// assertNoDeposit refuses coins on functions that take none (RA L-1).
func assertNoDeposit(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func pay(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if to == cur.Address() {
		panic("refusing to pay the minter itself: the coins would be stranded (SA-L5)")
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// Package market is the platform's immutable fixed-price market
// (design §2.5.4). It never holds a token: the seller approves this
// realm in core, the token stays in the seller's wallet, and Buy moves it
// through core's official grc721 RealmTeller in the same transaction that
// pays everyone. It never holds coins either (I-3).
//
// A token has at most one listing, addressed by (cid, tid). Stale listings
// (RA H-2) cannot be bought: a listing pins the token's move counter and
// core's approval nonces at listing time, and Buy requires owner == seller,
// the counter unchanged and the approval it was listed under still in
// place, unchanged (I-8). Once stale, a listing stays dead: approving the
// market again later never revives it (SA-L3). A stale listing never blocks
// the new owner: List overwrites it and anyone may CancelStale it.
//
// Storage (storage-cost-analysis M1-M3): a listing is one packed string in
// `listings` (key cid:tid) plus one key in the price index `byCollection`
// (floor, collection pages). Per-seller history comes from the indexer
// ("Listed"/"Cancelled" events), not from an on-chain index.
//
// Deposit return: gno refunds a freed storage deposit to the signer of the
// transaction that frees it, so a Buy hands the buyer the deposit the
// seller locked for the listing (and for a per-token Approve, which the
// transfer clears). Buy therefore charges the buyer that amount on top of
// the price and pays it to the seller: listing.deposit, fixed at List from
// the measured bytes (ListingDeposit, ApprovalDeposit). Net, the seller is
// whole and the buyer pays the price (the chain's refund cancels the
// extra) — up to the few bytes by which a real refund differs from the
// estimate.
//
// Pause ("trade" in core) stops List and Buy only. Cancel, CancelStale and
// UpdatePrice are never paused (I-2).
package market

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/core"
)

const (
	MaxPageSize = 50
	priceWidth  = 16 // types.MaxUnitPrice has 16 digits

	// Deposit-return estimate (ugnot), from the bytes measured in this
	// package's z_bytes_* filetests at gno.land's storage price of 100
	// ugnot/byte (vm param storage_price on Onyx and gnoland-1). Re-measure
	// before a deploy to a chain with another price.
	StoragePrice    = 100
	ListingBytes    = 4_090 // a listing while others are active (listings + byCollection keys)
	ApprovalBytes   = 2_044 // grc721 tokenApprovals entry of a per-token Approve, cleared by the transfer
	ListingDeposit  = ListingBytes * StoragePrice
	ApprovalDeposit = ApprovalBytes * StoragePrice
)

// listing is the decoded form of one packed `listings` value.
type listing struct {
	cid, tid string
	id       int64
	seller   address
	price    int64
	moves    int64 // core.TokenMoves at listing time
	height   int64
	feeBps   int64 // protocol fee at listing time; a sale never pays more (SA-I5)
	engBps   int64 // engine-author fee at listing time; a sale never pays more
	deposit  int64 // deposit return the buyer pays the seller (from the approval path, not stored)
	// approval the listing was made under (SA-L3): per-token and/or
	// approval-for-all, each pinned to core's nonce at listing time
	viaToken, viaAll          bool
	tokenNonce, operatorNonce int64
}

var (
	listings     avl.Tree // cid:tid -> packed listing (encode)
	byCollection avl.Tree // cid:paddedPrice:tid -> "" (floor = first key)
	nextID       int64
	selfPath     string // captured in init for read paths without a cur
)

func init(cur realm) {
	selfPath = cur.PkgPath()
}

// List offers a token of a Final collection at price (ugnot). The caller
// must own it and have approved this realm (Approve or SetApprovalForAll in
// core). A stale listing of the same token is replaced. Returns the
// listing's sequence id (events); the listing itself is addressed by
// (cid, tid).
func List(cur realm, cid, tid string, price int64) string {
	assertNoDeposit(cur)
	assertTradeOpen()
	assertPrice(price)
	seller := cur.Previous().Address()
	if core.Info(cid).State != types.StateFinal {
		panic("tokens of this collection are locked until it is final")
	}
	owner, err := core.OwnerOf(cid, tid)
	if err != nil {
		panic(err)
	}
	if owner != seller {
		panic("only the token owner can list it")
	}
	viaToken, viaAll := approvals(cid, tid, owner, cur.Address())
	if !viaToken && !viaAll {
		panic("approve the market for this token first: core.Approve(cid, tid, " + cur.Address().String() + ")")
	}
	if old, ok := lookup(cid, tid); ok {
		if live(old, cur.Address()) {
			panic("token is already listed as #" + itoa(old.id) + "; use UpdatePrice")
		}
		remove(old, "stale")
	}

	nextID++
	tn, on := core.ApprovalNonces(cid, tid, owner, cur.Address())
	_, engBps := core.EngineFee(cid)
	l := &listing{
		cid: cid, tid: tid, id: nextID, seller: seller, price: price,
		moves: core.TokenMoves(cid, tid), height: runtime.ChainHeight(),
		feeBps: core.FeeConfig().SecondaryBps, engBps: engBps,
		viaToken: viaToken, viaAll: viaAll, tokenNonce: tn, operatorNonce: on,
	}
	l.deposit = depositOf(l.viaToken)
	store(l)
	chain.Emit("Listed", "id", itoa(l.id), "cid", cid, "tid", tid, "seller", seller.String(), "price", itoa(price),
		"deposit", itoa(l.deposit))
	return itoa(l.id)
}

// UpdatePrice changes the price of a live listing; Buy's expectedPrice
// protects buyers from a change racing their purchase (RA M-10).
func UpdatePrice(cur realm, cid, tid string, price int64) {
	assertNoDeposit(cur)
	assertPrice(price)
	l := mustListing(cid, tid)
	assertSeller(cur, l)
	if !live(l, cur.Address()) {
		panic("listing is stale; cancel it and list again")
	}
	byCollection.Remove(collectionKey(l))
	l.price = price
	store(l)
	chain.Emit("PriceUpdated", "id", itoa(l.id), "cid", l.cid, "tid", l.tid, "price", itoa(price))
}

// Cancel removes the caller's listing (its storage deposit returns to the
// caller). Never paused.
func Cancel(cur realm, cid, tid string) {
	assertNoDeposit(cur)
	l := mustListing(cid, tid)
	assertSeller(cur, l)
	remove(l, "cancelled")
}

// CancelStale lets anyone remove a listing that can no longer be bought;
// the freed deposit goes to the caller (gno's rule), a cleanup bounty.
func CancelStale(cur realm, cid, tid string) {
	assertNoDeposit(cur)
	l := mustListing(cid, tid)
	if live(l, cur.Address()) {
		panic("listing is still valid")
	}
	remove(l, "stale")
}

// Buy pays exactly expectedPrice for the token's listing, plus the
// listing's deposit return (see the package doc); excess attached ugnot is
// refunded. Order: checks, remove the listing, move the token, then pay —
// protocol fee to the treasury, royalty to the collection's sub-treasury
// (then distributed to its payees), the engine author's fee, the rest plus
// the deposit return to the seller. I-4: protocol + royalty + engine +
// seller + refund == attached.
func Buy(cur realm, cid, tid string, expectedPrice int64) {
	paid := received(cur)
	assertTradeOpen()
	buyer := cur.Previous().Address()
	l := mustListing(cid, tid)
	if l.price != expectedPrice {
		panic("price is " + itoa(l.price) + "ugnot, expected " + itoa(expectedPrice))
	}
	if paid < l.price+l.deposit {
		panic("send " + itoa(l.price+l.deposit) + "ugnot (price " + itoa(l.price) + " + deposit return " +
			itoa(l.deposit) + "), sent " + itoa(paid))
	}
	if buyer == l.seller {
		panic("cannot buy your own listing")
	}
	if !live(l, cur.Address()) {
		panic("listing is stale: the token moved or approval was revoked since it was listed")
	}
	remove(l, "sold")

	tok := core.Token(l.cid)
	if err := tok.RealmTeller(0, cur).TransferFrom(0, cur, l.seller, buyer, grc721.TokenID(l.tid)); err != nil {
		panic(err)
	}

	s := settle(l)
	pay(cur, s.treasury, s.protocol)
	pay(cur, s.royaltyTo, s.royalty)
	pay(cur, s.engineAuthor, s.engine)
	pay(cur, l.seller, s.seller)
	pay(cur, buyer, paid-l.price-l.deposit)
	if s.royalty > 0 {
		core.DistributeRoyalties(cross(cur), l.cid)
	}
	chain.Emit("Bought", "id", itoa(l.id), "cid", l.cid, "tid", l.tid,
		"seller", l.seller.String(), "buyer", buyer.String(), "price", itoa(l.price),
		"protocolFee", itoa(s.protocol), "royalty", itoa(s.royalty), "engineFee", itoa(s.engine),
		"engineAuthor", s.engineAuthor.String(), "deposit", itoa(l.deposit))
}

// settlement is how a sale of l is paid now (I-4: protocol + royalty +
// engine + seller == price + deposit).
type settlement struct {
	treasury, royaltyTo, engineAuthor address
	protocol, royalty, engine, seller int64
}

func settle(l *listing) settlement {
	fee := core.FeeConfig()
	feeBps := fee.SecondaryBps
	if l.feeBps < feeBps {
		feeBps = l.feeBps
	}
	author, engBps := core.EngineFee(l.cid)
	if l.engBps < engBps {
		engBps = l.engBps
	}
	s := settlement{treasury: fee.Treasury, engineAuthor: author}
	s.protocol = safe.BpsOf(l.price, feeBps)
	s.engine = safe.BpsOf(l.price, engBps)
	royaltyTo, royalty, err := core.Royalty(l.cid).RoyaltyInfo(grc721.TokenID(l.tid), l.price)
	if err != nil {
		panic(err)
	}
	s.royaltyTo, s.royalty = royaltyTo, royalty
	s.seller = l.price - s.protocol - s.royalty - s.engine + l.deposit
	return s
}

// --- reads ---------------------------------------------------------------------

// Listing is the token's listing as JSON, stale ones included with
// "live":false, or "null".
func Listing(cid, tid string) string {
	l, ok := lookup(cid, tid)
	if !ok {
		return "null"
	}
	w := &safe.JSONWriter{}
	writeListingLive(w, l, live(l, selfAddress()))
	return w.String()
}

// ListingOf is the live listing of a token as JSON, or "null".
func ListingOf(cid, tid string) string {
	l, ok := lookup(cid, tid)
	if !ok || !live(l, selfAddress()) {
		return "null"
	}
	w := &safe.JSONWriter{}
	writeListingLive(w, l, true)
	return w.String()
}

// ActiveListing is the typed read for other realms: the live listing of a
// token, if any (id is the sequence id).
func ActiveListing(cid, tid string) (id string, price int64, ok bool) {
	l, found := lookup(cid, tid)
	if !found || !live(l, selfAddress()) {
		return "", 0, false
	}
	return itoa(l.id), l.price, true
}

// Quote is what Buy(cid, tid, price) costs and pays now, as JSON: {live,
// id, seller, price, deposit, total (attach this), protocolFee, royalty,
// royaltyTo, engineFee, engineAuthor, sellerProceeds}; "null" if unlisted.
func Quote(cid, tid string) string {
	l, ok := lookup(cid, tid)
	if !ok {
		return "null"
	}
	s := settle(l)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.BoolField("live", live(l, selfAddress()))
	w.StrField("id", itoa(l.id))
	w.StrField("seller", l.seller.String())
	w.IntField("price", l.price)
	w.IntField("deposit", l.deposit)
	w.IntField("total", l.price+l.deposit)
	w.IntField("protocolFee", s.protocol)
	w.IntField("royalty", s.royalty)
	w.StrField("royaltyTo", s.royaltyTo.String())
	w.IntField("engineFee", s.engine)
	w.StrField("engineAuthor", s.engineAuthor.String())
	w.IntField("sellerProceeds", s.seller)
	w.EndObject()
	return w.String()
}

// ListingsByCollection lists by ascending price. Stale listings are
// included with "live":false so pages stay stable; frontends hide them.
// Listings by seller: use the indexer (Listed / Cancelled events).
func ListingsByCollection(cid string, offset, limit int64) string {
	if limit <= 0 || limit > MaxPageSize {
		limit = MaxPageSize
	}
	prefix := cid + ":"
	self := selfAddress()
	w := &safe.JSONWriter{}
	w.BeginArray()
	var skipped, written int64
	byCollection.Iterate(prefix, prefixEnd(prefix), func(k string, _ any) bool {
		if skipped < offset {
			skipped++
			return false
		}
		l := mustListing(cid, tidOfKey(k))
		writeListingLive(w, l, live(l, self))
		written++
		return written >= limit
	})
	w.EndArray()
	return w.String()
}

// Floor is the lowest live price in cid, or -1. It inspects at most
// MaxPageSize listings from the cheapest, so spam cannot make it unbounded.
func Floor(cid string) int64 {
	floor := int64(-1)
	seen := 0
	prefix := cid + ":"
	self := selfAddress()
	byCollection.Iterate(prefix, prefixEnd(prefix), func(k string, _ any) bool {
		seen++
		l := mustListing(cid, tidOfKey(k))
		if live(l, self) {
			floor = l.price
			return true
		}
		return seen >= MaxPageSize
	})
	return floor
}

func Render(path string) string {
	return "# market/v1\n\n" + itoa(int64(listings.Size())) + " open listings. " +
		"Read them with `ListingsByCollection` or browse the gallery.\n"
}

// --- internals -------------------------------------------------------------------

// live: still owned by the seller, not moved since listing, and the
// approval it was listed under is still in place and untouched since: a
// per-token listing dies with any later Approve of that token, an
// approval-for-all listing with any later SetApprovalForAll of the market
// by the seller — even one that approves again (SA-L3).
func live(l *listing, market address) bool {
	owner, err := core.OwnerOf(l.cid, l.tid)
	if err != nil || owner != l.seller || core.TokenMoves(l.cid, l.tid) != l.moves {
		return false
	}
	viaToken, viaAll := approvals(l.cid, l.tid, owner, market)
	tn, on := core.ApprovalNonces(l.cid, l.tid, owner, market)
	return (l.viaToken && viaToken && tn == l.tokenNonce) || (l.viaAll && viaAll && on == l.operatorNonce)
}

// approvals reports whether market is approved for this token, and whether
// it is approved for all of owner's tokens.
func approvals(cid, tid string, owner, market address) (viaToken, viaAll bool) {
	tok := core.Token(cid)
	a, err := tok.GetApproved(grc721.TokenID(tid))
	return err == nil && a == market, tok.IsApprovedForAll(owner, market)
}

// store writes l and its price-index key.
func store(l *listing) {
	listings.Set(tokenKey(l.cid, l.tid), encode(l))
	byCollection.Set(collectionKey(l), "")
}

// remove deletes a listing and its index key; closed listings are not kept
// (RA L-6), the "Cancelled" event (reason sold/cancelled/stale) is the record.
func remove(l *listing, reason string) {
	listings.Remove(tokenKey(l.cid, l.tid))
	byCollection.Remove(collectionKey(l))
	chain.Emit("Cancelled", "id", itoa(l.id), "cid", l.cid, "tid", l.tid, "reason", reason)
}

// encode packs a listing as one comma-separated string (M1: an inline avl
// value instead of a *listing object, ~1.3 KB less per listing):
// id,seller,price,moves,height,feeBps,engBps,flags,tokenNonce,operatorNonce
// with flags = 1 (per-token) | 2 (for-all); the deposit return follows
// from the flags (depositOf).
func encode(l *listing) string {
	flags := int64(0)
	if l.viaToken {
		flags |= 1
	}
	if l.viaAll {
		flags |= 2
	}
	return itoa(l.id) + "," + l.seller.String() + "," + itoa(l.price) + "," + itoa(l.moves) + "," +
		itoa(l.height) + "," + itoa(l.feeBps) + "," + itoa(l.engBps) + "," +
		itoa(flags) + "," + itoa(l.tokenNonce) + "," + itoa(l.operatorNonce)
}

func decode(cid, tid, v string) *listing {
	f := strings.Split(v, ",")
	if len(f) != 10 {
		panic("market: corrupt listing " + cid + ":" + tid)
	}
	n := func(i int) int64 {
		x, err := strconv.ParseInt(f[i], 10, 64)
		if err != nil {
			panic("market: corrupt listing " + cid + ":" + tid)
		}
		return x
	}
	flags := n(7)
	return &listing{
		cid: cid, tid: tid, id: n(0), seller: address(f[1]), price: n(2), moves: n(3), height: n(4),
		feeBps: n(5), engBps: n(6), deposit: depositOf(flags&1 != 0), viaToken: flags&1 != 0, viaAll: flags&2 != 0,
		tokenNonce: n(8), operatorNonce: n(9),
	}
}

// depositOf is a listing's deposit return: its own storage, plus the
// per-token approval the sale's transfer clears (an approval-for-all
// stays, so the seller keeps that deposit).
func depositOf(viaToken bool) int64 {
	if viaToken {
		return ListingDeposit + ApprovalDeposit
	}
	return ListingDeposit
}

func lookup(cid, tid string) (*listing, bool) {
	v := listings.Get(tokenKey(cid, tid))
	if v == nil {
		return nil, false
	}
	return decode(cid, tid, v.(string)), true
}

func mustListing(cid, tid string) *listing {
	l, ok := lookup(cid, tid)
	if !ok {
		panic("token " + cid + ":" + tid + " is not listed")
	}
	return l
}

func writeListingLive(w *safe.JSONWriter, l *listing, isLive bool) {
	w.BeginObject()
	w.StrField("id", itoa(l.id))
	w.StrField("cid", l.cid)
	w.StrField("tid", l.tid)
	w.StrField("seller", l.seller.String())
	w.IntField("price", l.price)
	w.IntField("deposit", l.deposit)
	w.IntField("moves", l.moves)
	w.IntField("height", l.height)
	w.IntField("engineFeeBps", l.engBps)
	w.BoolField("live", isLive)
	w.EndObject()
}

func assertSeller(cur realm, l *listing) {
	if cur.Previous().Address() != l.seller {
		panic("only the seller can do this")
	}
}

func assertTradeOpen() {
	if core.Paused("trade") {
		panic("paused: trade")
	}
}

func assertPrice(price int64) {
	if price <= 0 || price > types.MaxUnitPrice {
		panic("price must be 1.." + itoa(types.MaxUnitPrice) + " ugnot")
	}
}

func received(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payments must come directly from a wallet, not through another realm")
	}
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != "ugnot" && c.Amount != 0 {
			panic("only ugnot is accepted")
		}
	}
	return sent.AmountOf("ugnot")
}

func assertNoDeposit(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func pay(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if to == cur.Address() {
		panic("refusing to pay the market itself: the coins would be stranded (SA-L5)")
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// tokenKey is the listing key. cid and tid are canonical ids (core
// accepted the token), so the key has one spelling per token.
func tokenKey(cid, tid string) string { return cid + ":" + tid }

// collectionKey orders a collection's listings by price; the tid is the
// part after the last ':'.
func collectionKey(l *listing) string {
	return l.cid + ":" + safe.PadInt(l.price, priceWidth) + ":" + l.tid
}

func tidOfKey(k string) string { return k[strings.LastIndex(k, ":")+1:] }

// prefixEnd is the smallest key greater than every key with this prefix
// (prefixes here end in ':', so bump it to ';').
func prefixEnd(prefix string) string {
	return prefix[:len(prefix)-1] + string(rune(prefix[len(prefix)-1]+1))
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// selfAddress is this realm's address for read paths that have no cur.
func selfAddress() address { return chain.PackageAddress(selfPath) }

// Package reader is the batch JSON read API for the frontend and the
// aggregator (design §2.5.6). It is private (re-deployable in place, no
// other realm may import it) and holds no state or money: everything comes
// from core, market and r/sys/users.
//
// Every string goes out through safe.JSONWriter, so stored text can never
// forge a record (RA H-1: the old TSV reader split on tabs and newlines).
// Art is never batched: one token per Art call, because SVG rendering is
// what exhausted the query gas in nftread1 (RA L-9).
package reader

import (
	"gno.land/r/sys/users"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/core"
	market "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/market/v1"
)

// Batch limits. Hypothesis (S-4): sized for the genesis engine under the
// public qeval gas cap; measure on Onyx and lower if a full page runs out.
const (
	MaxCards       = 50
	MaxTraitCounts = 500
	MaxStudio      = 200
)

// Cards is one gallery page: [{tid, owner, ownerName, traits, listing}] for
// tokens offset+1 … offset+limit. Burned tokens are skipped; listing is
// {id, price} or null.
func Cards(cid string, offset, limit int64) string {
	info := core.Info(cid)
	w := &safe.JSONWriter{}
	w.BeginArray()
	for _, tid := range tokenRange(info.Minted, offset, limit, MaxCards) {
		owner, err := core.OwnerOf(cid, tid)
		if err != nil {
			continue // burned
		}
		w.BeginObject()
		w.StrField("tid", tid)
		w.StrField("owner", owner.String())
		w.StrField("ownerName", nameOf(owner))
		w.Key("traits")
		writeTraits(w, core.TokenTraitList(cid, tid))
		w.Key("listing")
		if id, price, ok := market.ActiveListing(cid, tid); ok {
			w.BeginObject()
			w.StrField("id", id)
			w.IntField("price", price)
			w.EndObject()
		} else {
			w.Raw("null")
		}
		w.EndObject()
	}
	w.EndArray()
	return w.String()
}

// TraitCounts counts trait values over tokens offset+1 … offset+limit:
// {"n": tokens counted, "counts": {type: {value: count}}}. Rarity % for a
// 1000-token collection takes two calls. Before Final every token reports
// Status=Unrevealed.
func TraitCounts(cid string, offset, limit int64) string {
	info := core.Info(cid)
	c := newCounter()
	for _, tid := range tokenRange(info.Minted, offset, limit, MaxTraitCounts) {
		if _, err := core.OwnerOf(cid, tid); err != nil {
			continue
		}
		c.add(core.TokenTraitList(cid, tid))
	}
	return c.json()
}

// StudioTraits is TraitCounts for an engine and params over n sample seeds
// (engine.SampleSeed(from) …), for the Studio's rarity preview.
func StudioTraits(engineID, params string, from, n int64) string {
	if n <= 0 || n > MaxStudio {
		n = MaxStudio
	}
	if from < 0 {
		from = 0
	}
	c := newCounter()
	for i := from; i < from+n; i++ {
		c.add(core.EngineTraits(engineID, params, engine.SampleSeed(int(i))))
	}
	return c.json()
}

// Art is one token's data URI (placeholder before Final).
func Art(cid, tid string) string {
	uri, err := core.TokenURI(cid, tid)
	if err != nil {
		panic(err)
	}
	return uri
}

func Collections(offset, limit int64) string { return core.Collections(offset, limit) }

// Profile is {address, name, collections} for one address. A seller's
// listings come from the indexer (market "Listed"/"Cancelled" events):
// market/v1 keeps no per-seller index on chain (storage, M2).
func Profile(addr address) string {
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("address", addr.String())
	w.StrField("name", nameOf(addr))
	w.Key("collections")
	w.Raw(core.CollectionsByCreator(addr, 0, MaxCards))
	w.EndObject()
	return w.String()
}

// --- helpers -----------------------------------------------------------------

// nameOf is the r/sys/users name of addr, or "".
func nameOf(addr address) string {
	if u := users.ResolveAddress(addr); u != nil {
		return u.Name()
	}
	return ""
}

func tokenRange(minted, offset, limit, max int64) []string {
	if limit <= 0 || limit > max {
		limit = max
	}
	if offset < 0 {
		offset = 0
	}
	var out []string
	for n := offset + 1; n <= minted && n <= offset+limit; n++ {
		out = append(out, itoa(n))
	}
	return out
}

func writeTraits(w *safe.JSONWriter, ts []engine.Trait) {
	w.BeginArray()
	for _, t := range ts {
		w.BeginObject()
		w.StrField("trait_type", t.Type)
		w.StrField("value", t.Value)
		w.EndObject()
	}
	w.EndArray()
}

// counter keeps first-seen order so the JSON is deterministic.
type counter struct {
	n      int64
	types  []string
	values map[string][]string       // type -> values in first-seen order
	counts map[string]map[string]int64 // type -> value -> count
}

func newCounter() *counter {
	return &counter{values: map[string][]string{}, counts: map[string]map[string]int64{}}
}

func (c *counter) add(ts []engine.Trait) {
	c.n++
	for _, t := range ts {
		byValue, ok := c.counts[t.Type]
		if !ok {
			byValue = map[string]int64{}
			c.counts[t.Type] = byValue
			c.types = append(c.types, t.Type)
		}
		if _, seen := byValue[t.Value]; !seen {
			c.values[t.Type] = append(c.values[t.Type], t.Value)
		}
		byValue[t.Value]++
	}
}

func (c *counter) json() string {
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("n", c.n)
	w.Key("counts")
	w.BeginObject()
	for _, typ := range c.types {
		w.Key(typ)
		w.BeginObject()
		for _, v := range c.values[typ] {
			w.IntField(v, c.counts[typ][v])
		}
		w.EndObject()
	}
	w.EndObject()
	w.EndObject()
	return w.String()
}

func itoa(n int64) string { return safe.PadInt(n, 1) }

// Package gallery is the platform's gnoweb face (design §2.5.7): the
// product stays browsable on gno.land even without the website. It is
// private (re-deployable in place), read-only and holds nothing.
//
// Routes:
//
//	""                    latest collections
//	c/<cid>[?page=N]      one collection, 20 tokens per page
//	c/<cid>/t/<tid>       one token: art, traits, owner, listing, provenance
//	e/<engine pkgpath>    an engine's manifest and status
//	u/<name>              a registered user's collections and listings
//
// Every user-supplied string is rendered as plain text (plainText: RA M-9,
// SA-M4): no heading, link, image, HTML or autolink can come out of a name,
// description, trait or manifest field. Every list is paginated.
package gallery

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/sys/users"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/core"
	market "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/market/v1"
)

const (
	pageSize   = 20
	homeLimit  = 20
	maxPageNum = 500
)

func Render(path string) string {
	route, query, _ := strings.Cut(path, "?")
	parts := strings.Split(route, "/")
	switch {
	case route == "":
		return home()
	case len(parts) == 2 && parts[0] == "c":
		return collectionPage(parts[1], pageFrom(query))
	case len(parts) == 4 && parts[0] == "c" && parts[2] == "t":
		return tokenPage(parts[1], parts[3])
	case len(parts) > 1 && parts[0] == "e":
		return enginePage(strings.TrimPrefix(route, "e/"))
	case len(parts) == 2 && parts[0] == "u":
		return userPage(parts[1])
	}
	return "# Not found\n\n[Back to the gallery](" + base() + ")\n"
}

func home() string {
	n := core.CollectionCount()
	out := ufmt.Sprintf("# Gallery\n\n%d collections. Art is computed on chain from each collection's engine and revealed seed.\n\n", n)
	for id := n; id >= 1 && id > n-homeLimit; id-- {
		info := core.Info(itoa(id))
		out += ufmt.Sprintf("- [%s](%s) — %s, %d/%d minted\n",
			plainText(info.Name), link("c/"+info.ID), info.State.String(), info.Minted, info.MaxSupply)
	}
	return out
}

func collectionPage(cid string, page int64) string {
	info := core.Info(cid)
	out := "# " + plainText(info.Name) + " (" + plainText(info.Symbol) + ")\n\n"
	if info.Description != "" {
		out += plainText(info.Description) + "\n\n"
	}
	out += ufmt.Sprintf("- State: **%s**, %d/%d minted, royalty %d bps\n", info.State.String(), info.Minted, info.MaxSupply, info.RoyaltyBps)
	out += "- Creator: " + who(info.Creator) + "\n"
	out += "- Engine: [" + plainText(info.EngineID) + "](" + link("e/"+info.EngineID) + ")\n"
	if info.Badge != "" {
		out += "- Provenance: **" + info.Badge + "** — " + fairness(cid) + "\n"
	}
	if f := market.Floor(cid); f > 0 {
		out += ufmt.Sprintf("- Floor: %d ugnot\n", f)
	}
	out += "\n## Tokens\n\n"
	first := (page-1)*pageSize + 1
	for n := first; n < first+pageSize && n <= info.Minted; n++ {
		tid := itoa(n)
		owner, err := core.OwnerOf(cid, tid)
		if err != nil {
			continue
		}
		line := "- [#" + tid + "](" + link("c/"+cid+"/t/"+tid) + ") owned by " + who(owner)
		if _, price, ok := market.ActiveListing(cid, tid); ok {
			line += ufmt.Sprintf(", listed at %d ugnot", price)
		}
		out += line + "\n"
	}
	if first+pageSize <= info.Minted {
		out += "\n[Next page](" + link(ufmt.Sprintf("c/%s?page=%d", cid, page+1)) + ")\n"
	}
	return out
}

func tokenPage(cid, tid string) string {
	info := core.Info(cid)
	owner, err := core.OwnerOf(cid, tid)
	if err != nil {
		return "# Token not found\n"
	}
	uri, _ := core.TokenURI(cid, tid)
	out := "# " + plainText(info.Name) + " #" + tid + "\n\n"
	out += "![" + plainText(info.Name) + " #" + tid + "](" + sanitize.ImageURL(uri) + ")\n\n"
	out += "- Owner: " + who(owner) + "\n"
	if id, price, ok := market.ActiveListing(cid, tid); ok {
		out += ufmt.Sprintf("- Listed: %d ugnot (listing %s)\n", price, id)
	}
	out += "\n## Traits\n\n"
	for _, t := range core.TokenTraitList(cid, tid) {
		out += "- " + plainText(t.Type) + ": " + plainText(t.Value) + "\n"
	}
	out += "\n## How to verify\n\n"
	if info.State != types.StateFinal {
		out += "The collection is not revealed yet; every token shows the same placeholder.\n"
		return out
	}
	out += "1. Read `Provenance(\"" + cid + "\")` on core from another RPC and recompute the commitments and the salt.\n"
	out += "2. Seed: `TokenSeed(\"" + cid + "\", \"" + tid + "\")` = sha256(\"" + "art|seed|v1|" + cid + "|" + tid + "|\" + salt).\n"
	out += "3. Render it yourself: `RenderWith(engine, params, seed)` must return this image.\n\n"
	out += "Provenance badge **" + info.Badge + "**, on-chain check: " + strconv.FormatBool(core.VerifyProvenance(cid)) +
		"; " + fairness(cid) + "\n"
	return out
}

// fairness never calls a collection "verified" unless it is a fair launch
// (core.FairLaunch): a consistent record is not enough when one party could
// choose the map (SA-M2).
func fairness(cid string) string {
	if core.FairLaunch(cid) {
		return "fair launch, verified on chain"
	}
	if !core.VerifyProvenance(cid) {
		return "NOT verified: the provenance record does not check out"
	}
	return "not a fair launch: one party could choose the map (record consistent)"
}

// plainText renders user text as inert markdown: sanitize.InlineText escapes
// every inline-active character (\ * _ [ ] ( ) ~ > - + . ! ` # < &) and folds
// newlines, and escaping ':' breaks bare-URL autolinks ("https\://…"), which
// InlineText leaves alone (SA-M4).
func plainText(s string) string {
	return strings.ReplaceAll(sanitize.InlineText(s), ":", "\\:")
}

func enginePage(id string) string {
	m := core.EngineManifest(id)
	out := "# Engine " + plainText(m.Name) + " " + plainText(m.Version) + "\n\n"
	out += "- Realm: " + sanitize.InlineCode(id) + "\n"
	out += "- Author: " + who(m.Author) + "\n"
	out += "- Status: **" + core.EngineStatus(id) + "**, sample fingerprint intact: " + strconv.FormatBool(core.VerifyEngine(id)) + "\n"
	out += "- License: " + plainText(m.License) + "\n"
	out += "- Traits: " + plainText(strings.Join(m.TraitTypes, ", ")) + "\n\n"
	if m.Description != "" {
		out += plainText(m.Description) + "\n"
	}
	return out
}

func userPage(name string) string {
	u, _ := users.ResolveName(name)
	if u == nil {
		return "# Unknown user\n"
	}
	addr := u.Addr()
	return "# @" + sanitize.InlineText(u.Name()) + "\n\n`" + addr.String() + "`\n\n" +
		"Collections and listings of this address: reader realm, `Profile(" + addr.String() + ")`.\n"
}

// who renders an address as its r/sys/users name when it has one.
func who(addr address) string {
	if u := users.ResolveAddress(addr); u != nil {
		return "[@" + sanitize.InlineText(u.Name()) + "](/u/" + sanitize.InlineText(u.Name()) + ")"
	}
	return "`" + addr.String() + "`"
}

func pageFrom(query string) int64 {
	for _, kv := range strings.Split(query, "&") {
		if strings.HasPrefix(kv, "page=") {
			if n, err := strconv.ParseInt(strings.TrimPrefix(kv, "page="), 10, 64); err == nil && n >= 1 && n <= maxPageNum {
				return n
			}
		}
	}
	return 1
}

// selfPath is captured at deploy; links are gnoweb paths without the domain.
var selfPath string

func init(cur realm) {
	selfPath = cur.PkgPath()
}

func base() string {
	return strings.TrimPrefix(selfPath, "gno.land")
}

func link(route string) string { return base() + ":" + route }

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package core

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Admin (design §2.5.2, §7.5). The admin can only change the parameters
// listed in validateOp, each inside a hard cap, after a public timelock;
// it can pause new activity for a bounded time. It can never move, approve
// or burn a token, touch a collection's configuration, or receive funds
// (I-1). With no collection yet there is nothing to protect, so ops execute
// without delay — that is how the platform is configured after deploy.
//
// TODO(mainnet): the initial admin and treasury must be the 2/3 multisig.
// SA-I6: CreateFee starts at 0 here so tests and bootstrap stay simple;
// scripts/deploy-onyx.sh sets a non-zero fee.create during bootstrap.
var (
	admin        = address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06")
	pendingAdmin address
	fees         = types.Fees{
		PrimaryBps: 250, SecondaryBps: 250, EngineCapBps: EngineFeeCapBps,
		Treasury: address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06"),
	}
	beacon       address
	minters      avl.Tree // minter pkgpath -> *minterRecord
	ops          avl.Tree // safe.PadInt(op id) -> *pendingOp
	opCount      int64
	pauses       avl.Tree // scope -> *pauseRecord
)

// pauseRecord is one scope's pause and its budget (SA-L2): within a window
// of PauseWindowBlocks a scope can be paused for at most MaxPauseBlocks in
// total; a pause cannot be renewed while it runs. Worst case two budgets
// meet at a window boundary (<= 2 x MaxPauseBlocks in a row), never more.
type pauseRecord struct {
	windowStart int64
	used        int64 // blocks of budget charged in this window
	until       int64 // exclusive
}

type minterRecord struct {
	deprecated bool
}

type pendingOp struct {
	id       int64
	op, arg  string
	proposed int64
}

// Ops and their argument formats.
const (
	OpFeeCreate       = "fee.create"       // ugnot, <= CreateFeeCap
	OpFeePrimary      = "fee.primary"      // bps, <= ProtocolFeeCapBps
	OpFeeSecondary    = "fee.secondary"    // bps, <= ProtocolFeeCapBps
	OpFeeEngine       = "fee.engine"       // bps, <= EngineFeeCapBps: platform cap on engine-author fees
	OpTreasury        = "treasury"         // address
	OpBeacon          = "beacon"           // address, or "" to disable new beacon launches
	OpMinterAdd       = "minter.add"       // realm pkgpath
	OpMinterDeprecate = "minter.deprecate" // realm pkgpath: no new collections
	OpEngineReview    = "engine.review"    // engine id: reviewed badge (UI only)
	OpAdminTransfer   = "admin.transfer"   // address; the new admin must AcceptAdmin
	OpRandomnessAdd   = "randomness.add"   // registered provider path: creators may launch with it
	OpRandomnessDepr  = "randomness.deprecate" // provider path: no new launches; running ones finish
)

var pauseScopes = []string{"create", "mint", "trade"}

func ProposeOp(cur realm, op, arg string) string {
	assertNoDeposit(cur)
	assertAdmin(cur)
	validateOp(op, arg)
	opCount++
	p := &pendingOp{id: opCount, op: op, arg: arg, proposed: height()}
	ops.Set(safe.PadInt(p.id, cidWidth), p)
	id := itoa(p.id)
	chain.Emit("OpProposed", "id", id, "op", op, "arg", arg, "earliest", itoa(earliestExecution(p)))
	return id
}

// ExecuteOp applies a proposed op once its timelock has passed. The delay is
// judged at execution, so an op proposed during bootstrap still waits the
// full timelock if a collection appeared in the meantime.
func ExecuteOp(cur realm, opID string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	p := mustOp(opID)
	if height() < earliestExecution(p) {
		panic("timelocked until height " + itoa(earliestExecution(p)))
	}
	validateOp(p.op, p.arg)
	applyOp(p.op, p.arg)
	ops.Remove(safe.PadInt(p.id, cidWidth))
	chain.Emit("OpExecuted", "id", opID, "op", p.op, "arg", p.arg)
}

func CancelOp(cur realm, opID string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	p := mustOp(opID)
	ops.Remove(safe.PadInt(p.id, cidWidth))
	chain.Emit("OpCancelled", "id", opID)
}

func AcceptAdmin(cur realm) {
	assertNoDeposit(cur)
	who := caller(cur)
	if pendingAdmin == "" || who != pendingAdmin {
		panic("no pending admin transfer to this address")
	}
	chain.Emit("AdminTransferred", "from", admin.String(), "to", who.String())
	admin = who
	pendingAdmin = ""
}

// Pause stops new activity in one scope for the rest of its budget (at
// most MaxPauseBlocks per PauseWindowBlocks). It never blocks exits (I-2)
// and cannot be renewed while it runs (SA-L2).
func Pause(cur realm, scope string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	assertScope(scope)
	h := height()
	r := pauseOf(scope)
	if h < r.until {
		panic("already paused until height " + itoa(r.until) + "; a pause cannot be renewed")
	}
	if h >= r.windowStart+PauseWindowBlocks {
		r.windowStart, r.used = h, 0
	}
	left := MaxPauseBlocks - r.used
	if left <= 0 {
		panic("pause budget of " + scope + " is spent until height " + itoa(r.windowStart+PauseWindowBlocks))
	}
	r.used += left
	r.until = h + left
	pauses.Set(scope, r)
	chain.Emit("Paused", "scope", scope, "until", itoa(r.until))
}

// Unpause ends a pause early and gives the unused blocks back to the budget.
func Unpause(cur realm, scope string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	assertScope(scope)
	h := height()
	r := pauseOf(scope)
	if h < r.until {
		r.used -= r.until - h
	}
	r.until = 0
	chain.Emit("Unpaused", "scope", scope)
}

func pauseOf(scope string) *pauseRecord {
	if v := pauses.Get(scope); v != nil {
		return v.(*pauseRecord)
	}
	return &pauseRecord{windowStart: -PauseWindowBlocks}
}

// Paused reports whether scope ("create", "mint", "trade") is paused now.
func Paused(scope string) bool {
	v := pauses.Get(scope)
	return v != nil && height() < v.(*pauseRecord).until
}

// PauseBudget is the scope's pause record as JSON: {until, used,
// windowStart, windowEnd, left}.
func PauseBudget(scope string) string {
	assertScope(scope)
	r := pauseOf(scope)
	used := r.used
	if height() >= r.windowStart+PauseWindowBlocks && height() >= r.until {
		used = 0
	}
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("until", r.until)
	w.IntField("used", used)
	w.IntField("windowStart", r.windowStart)
	w.IntField("windowEnd", r.windowStart+PauseWindowBlocks)
	w.IntField("left", MaxPauseBlocks-used)
	w.EndObject()
	return w.String()
}

func assertNotPaused(scope string) {
	if Paused(scope) {
		panic("paused: " + scope)
	}
}

func assertScope(scope string) {
	for _, s := range pauseScopes {
		if s == scope {
			return
		}
	}
	panic("pause scope must be one of " + strings.Join(pauseScopes, ", "))
}

func assertAdmin(cur realm) {
	if caller(cur) != admin {
		panic("admin only")
	}
}

func bootstrapping() bool { return collCount == 0 }

func earliestExecution(p *pendingOp) int64 {
	if bootstrapping() {
		return p.proposed
	}
	return p.proposed + TimelockBlocks
}

func mustOp(opID string) *pendingOp {
	v := ops.Get(safe.PadInt(safe.ParseID("opID", opID), cidWidth))
	if v == nil {
		panic("unknown op " + opID)
	}
	return v.(*pendingOp)
}

// validateOp is the closed list of admin powers (I-1).
func validateOp(op, arg string) {
	switch op {
	case OpFeeCreate:
		n := parseAmount(arg)
		if n > CreateFeeCap {
			panic("create fee above cap " + itoa(CreateFeeCap))
		}
	case OpFeePrimary, OpFeeSecondary:
		safe.AssertBps(op, parseAmount(arg), ProtocolFeeCapBps)
	case OpFeeEngine:
		safe.AssertBps(op, parseAmount(arg), EngineFeeCapBps)
	case OpTreasury, OpAdminTransfer:
		if !address(arg).IsValid() {
			panic(op + ": invalid address")
		}
		if op == OpTreasury {
			assertSpendable(op, address(arg), "", "") // SA-L5
		}
	case OpBeacon:
		if arg != "" && !address(arg).IsValid() {
			panic(op + ": invalid address")
		}
	case OpMinterAdd:
		safe.AssertText("minter", arg, 256)
		if !strings.HasPrefix(arg, runtime.ChainDomain()+"/r/") || strings.Contains(arg, "#") {
			panic("minter must be a realm path")
		}
		if minters.Has(arg) {
			panic("minter already added")
		}
	case OpMinterDeprecate:
		if !minters.Has(arg) {
			panic("unknown minter")
		}
	case OpEngineReview:
		mustEngine(arg)
	case OpRandomnessAdd:
		if mustProvider(arg).active {
			panic("randomness provider already approved")
		}
	case OpRandomnessDepr:
		if !mustProvider(arg).active {
			panic("randomness provider is not approved")
		}
	default:
		panic("unknown op " + strconv.Quote(op))
	}
}

func applyOp(op, arg string) {
	switch op {
	case OpFeeCreate:
		fees.CreateFee = parseAmount(arg)
	case OpFeePrimary:
		fees.PrimaryBps = parseAmount(arg)
	case OpFeeSecondary:
		fees.SecondaryBps = parseAmount(arg)
	case OpFeeEngine:
		fees.EngineCapBps = parseAmount(arg)
	case OpTreasury:
		fees.Treasury = address(arg)
	case OpBeacon:
		beacon = address(arg)
	case OpMinterAdd:
		minters.Set(arg, &minterRecord{})
	case OpMinterDeprecate:
		minters.Get(arg).(*minterRecord).deprecated = true
	case OpEngineReview:
		mustEngine(arg).reviewed = true
	case OpAdminTransfer:
		pendingAdmin = address(arg)
	case OpRandomnessAdd:
		mustProvider(arg).active = true
		activeProviders++
	case OpRandomnessDepr:
		mustProvider(arg).active = false
		activeProviders--
	}
}

func assertActiveMinter(path string) {
	v := minters.Get(path)
	if v == nil {
		panic("caller " + strconv.Quote(path) + " is not an approved minter")
	}
	if v.(*minterRecord).deprecated {
		panic("minter " + path + " is deprecated")
	}
}

func parseAmount(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 {
		panic("expected a non-negative integer, got " + strconv.Quote(s))
	}
	return n
}

package core

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/grc721/royalty/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/seqid/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// --- bound minter only -------------------------------------------------------
//
// A collection is created by an admin-approved minter realm and stays bound
// to it: only that realm can launch, abort, reserve and mint (I-5). The
// minter is trusted to pass the real creator; core trusts nothing else it
// is given and validates every field (I-13).

// CreateCollection stores a Draft collection and returns its id. Nobody can
// mint a Draft, so a creator can configure phases across several messages
// without a race (OA B2).
func CreateCollection(cur realm, creator address, spec types.CollectionSpec) string {
	minter := cur.Previous().PkgPath()
	assertActiveMinter(minter)
	assertNotPaused("create")
	if !creator.IsValid() {
		panic("invalid creator address")
	}
	safe.AssertNonEmptyText("name", spec.Name, MaxNameLen)
	safe.AssertSymbol("symbol", spec.Symbol)
	safe.AssertText("description", spec.Description, MaxDescriptionLen)
	safe.AssertText("params", spec.Params, MaxParamsLen)
	if spec.MaxSupply <= 0 || spec.MaxSupply > MaxSupplyCap {
		panic("maxSupply must be 1.." + itoa(MaxSupplyCap))
	}
	safe.AssertBps("royaltyBps", spec.RoyaltyBps, RoyaltyCapBps)
	primary := safe.ParsePayees("primaryPayees", spec.PrimaryPayees, MaxPayees)
	royal := safe.ParsePayees("royaltyPayees", spec.RoyaltyPayees, MaxPayees)
	next := itoa(collCount + 1)
	assertPayees("primaryPayees", primary, next, spec.EngineID)
	assertPayees("royaltyPayees", royal, next, spec.EngineID)

	rec := mustEngine(spec.EngineID)
	if !rec.claimed {
		panic("engine is not claimed by its author yet")
	}
	if rec.deprecated {
		panic("engine is deprecated")
	}
	// I-12 exception: the creator's own transaction runs the engine they chose.
	if err := rec.impl.ValidateParams(spec.Params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}

	collCount++
	cid := itoa(collCount)

	// Each collection gets its own sub-realm identity, so Token.ID() and every
	// grc721 event carry "…/core#c/<cid>" (design §2.3; verified by
	// spike/subtoken and core tests on gno v1.7.0).
	tok, led := grc721.NewToken(spec.Name, spec.Symbol, seqid.ID(uint64(collCount)), cur.Sub("c/"+cid))
	st := &tokenState{}
	led.RegisterExtension(&lockExt{cid: cid, st: st})
	roy, royLed := royalty.NewRoyalty(led, RoyaltyCapBps)
	if spec.RoyaltyBps > 0 {
		if err := royLed.SetDefaultRoyalty(royaltyAddress(cid), spec.RoyaltyBps); err != nil {
			panic(err)
		}
	}

	c := &collection{
		id:            cid,
		name:          spec.Name,
		symbol:        spec.Symbol,
		description:   spec.Description,
		creator:       creator,
		engineID:      spec.EngineID,
		params:        spec.Params,
		maxSupply:     spec.MaxSupply,
		nextTID:       1,
		royaltyBps:    spec.RoyaltyBps,
		primaryPayees: primary,
		royaltyPayees: royal,
		minter:        minter,
		state:         types.StateDraft,
		createdHeight: height(),
		token:         tok,
		ledger:        led,
		roy:           roy,
		st:            st,
	}
	collections.Set(collKey(cid), c)
	byCreator.Set(creator.String()+":"+collKey(cid), cid)

	chain.Emit("CollectionCreated",
		"cid", cid, "creator", creator.String(), "minter", minter,
		"engine", spec.EngineID, "token", tok.ID())
	return cid
}

// Launch freezes the configuration (I-6): sale window, reveal window and the
// creator's commitment. The sale must start in the future so a beacon can
// commit before the first mint.
func Launch(cur realm, cid string, l types.LaunchSpec) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	h := height()
	if c.state != types.StateDraft {
		panic("only a draft can be launched")
	}
	if l.StartHeight <= h {
		panic("startHeight must be in the future")
	}
	if l.EndHeight < l.StartHeight || l.EndHeight-l.StartHeight > MaxSaleBlocks {
		panic("sale window must be 0.." + itoa(MaxSaleBlocks) + " blocks")
	}
	if l.RevealWindow < RevealWindowMin || l.RevealWindow > RevealWindowMax {
		panic("revealWindow must be " + itoa(RevealWindowMin) + ".." + itoa(RevealWindowMax) + " blocks")
	}
	commit := safe.AssertHex("creatorCommit", l.CreatorCommit, 32)
	// Commitments are domain-separated by chain, collection and role
	// (safe.Commit), so only this collection's own history matters: a secret
	// that went public here is never accepted again (SA-L1, RA M-5).
	if isBurned(c, commit) {
		panic("this commitment's secret was already revealed; derive a new secret")
	}
	source := l.BeaconSource
	if l.UseBeacon {
		if source == "" {
			source = types.BeaconCommitted
		}
		if source == types.BeaconCommitted {
			if beacon == "" {
				panic("no beacon is configured; launch without useBeacon or with an approved randomness provider")
			}
		} else {
			assertActiveProvider(source)
		}
	} else {
		if source != "" {
			panic("beaconSource needs useBeacon")
		}
		// SA-M2: without the beacon the creator alone knows the only secret
		// and can grind the last mint for the map it wants. While the
		// platform has a beacon or an approved randomness provider, nobody
		// may opt out.
		if beaconAvailable() {
			panic("the platform beacon is configured; launch with useBeacon")
		}
	}

	c.prov = &provenance{creatorCommit: commit, acc: safe.InitialEntropy(runtime.ChainID(), cid)}
	c.startHeight, c.endHeight, c.revealWindow = l.StartHeight, l.EndHeight, l.RevealWindow
	c.useBeacon = l.UseBeacon
	c.beaconSource = source
	c.primaryBps = fees.PrimaryBps
	c.engineAuthor, c.engineBps = engineFeeQuote(c)
	c.state = types.StateScheduled

	chain.Emit("CollectionScheduled",
		"cid", cid, "start", itoa(c.startHeight), "end", itoa(c.endHeight),
		"revealWindow", itoa(c.revealWindow), "useBeacon", boolStr(c.useBeacon),
		"beaconSource", c.beaconSource, "creatorCommit", commit,
		"engineAuthor", c.engineAuthor.String(), "engineFeeBps", itoa(c.engineBps))
}

// AbortLaunch returns a launched collection to Draft while nothing has been
// minted — the way out when a beacon never commits. A commitment whose
// secret was revealed is burned for this collection; unrevealed ones (the
// beacon's deterministic one included) may be committed again (SA-L1).
func AbortLaunch(cur realm, cid string) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	refresh(c, height())
	if c.state == types.StateDraft || c.state == types.StateFinal {
		panic("only a launched, unfinished collection can be aborted")
	}
	if c.minted() > 0 {
		panic("tokens were minted; the launch can no longer be aborted")
	}
	if c.prov.creatorRevealed {
		c.burnedCommits = append(c.burnedCommits, c.prov.creatorCommit)
	}
	if c.prov.beaconRevealed {
		c.burnedCommits = append(c.burnedCommits, c.prov.beaconCommit)
	}
	c.prov = nil
	c.startHeight, c.endHeight, c.revealWindow, c.closeHeight = 0, 0, 0, 0
	c.useBeacon, c.beaconSource = false, ""
	c.engineBps, c.engineAuthor = 0, ""
	c.state = types.StateDraft
	chain.Emit("CollectionState", "cid", cid, "state", c.state.String())
}

// ReserveTo mints the creator's reserve before the sale starts. Reserve
// mints feed the entropy like any mint, appear in Provenance, and do not
// count toward wallet caps.
func ReserveTo(cur realm, cid string, to address, n int64) (first, last int64) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	assertNotPaused("mint")
	h := height()
	refresh(c, h)
	if c.state != types.StateScheduled {
		panic("reserve is only possible after launch and before the sale starts")
	}
	// SA-M2: a reserve is the creator's own allocation; it needs a map the
	// creator cannot steer, i.e. the beacon.
	if !c.useBeacon {
		panic("a creator reserve needs a beacon launch")
	}
	// A reserve is a mint, and the beacon may only commit while nothing is
	// minted: reserving first would leave the collection unmintable and
	// unabortable (found on Onyx, collection 1). A randomness provider has
	// nothing to commit: its value is drawn only after the reveal starts.
	if awaitingBeaconCommit(c) {
		panic("waiting for the beacon commitment; reserve after the beacon commits")
	}
	assertMintCount(c, n)
	if c.reserved+n > c.maxSupply*MaxReserveBps/safe.BpsDenominator {
		panic("reserve would exceed " + itoa(MaxReserveBps/100) + "% of supply")
	}
	first, last = mintBatchTo(c, to, n, h)
	c.reserved += n
	c.reservedTo.Set(to.String(), reservedTo(c, to)+n)
	emitBatch("Reserved", c, to, first, last)
	return first, last
}

// MintTo mints n tokens during the sale. The minter has already checked
// phase, price, allowlist and wallet cap; core re-checks only what it owns:
// state, supply and the beacon commitment (I-5). The lifetime counter of
// I-9 is the grc721 balance itself (mintedBy).
func MintTo(cur realm, cid string, to address, n int64) (first, last int64) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	assertNotPaused("mint")
	h := height()
	refresh(c, h)
	if c.state != types.StateMinting {
		panic("collection is not minting (state " + c.state.String() + ")")
	}
	if awaitingBeaconCommit(c) {
		panic("waiting for the beacon commitment; minting has not opened")
	}
	assertMintCount(c, n)
	first, last = mintBatchTo(c, to, n, h)
	if c.minted() == c.maxSupply {
		c.closeHeight = h
		c.state = types.StateClosed
		chain.Emit("CollectionState", "cid", cid, "state", c.state.String())
	}
	emitBatch("MintBatch", c, to, first, last)
	return first, last
}

func assertMintCount(c *collection, n int64) {
	if n <= 0 || n > MaxMintPerTx {
		panic("count must be 1.." + itoa(MaxMintPerTx))
	}
	if c.minted()+n > c.maxSupply {
		panic("only " + itoa(c.maxSupply-c.minted()) + " tokens left")
	}
}

// mintBatchTo is the only place tokens come into existence.
func mintBatchTo(c *collection, to address, n, h int64) (first, last int64) {
	first = c.nextTID
	last = first + n - 1
	for tid := first; tid <= last; tid++ {
		if err := c.ledger.Mint(to, grc721.TokenID(itoa(tid))); err != nil {
			panic(err)
		}
	}
	c.nextTID = last + 1
	c.st.appendTokens(first, last, h)
	c.prov.acc = safe.MixEntropy(c.prov.acc, to, h, first, last)
	return first, last
}

// mintedBy is addr's lifetime count of sale mints (I-9) while the
// collection is not Final: before Final no token can move or burn (I-11,
// lockExt) and tokens only come from mintBatchTo, so the grc721 balance is
// exactly sale mints + reserves received. This replaces a stored counter
// (~2 KB per new wallet, storage-cost-analysis P2). After Final the
// balance moves freely and no minter needs the count any more: -1.
func mintedBy(c *collection, addr address) int64 {
	if c.st.final {
		return -1
	}
	bal, err := c.token.BalanceOf(addr)
	if err != nil {
		return 0
	}
	return bal - reservedTo(c, addr)
}

func reservedTo(c *collection, addr address) int64 {
	if v := c.reservedTo.Get(addr.String()); v != nil {
		return v.(int64)
	}
	return 0
}

// awaitingBeaconCommit: a committed-beacon launch whose beacon has not
// committed yet; nothing may be minted (or reserved) before it does.
func awaitingBeaconCommit(c *collection) bool {
	return c.useBeacon && c.beaconSource == types.BeaconCommitted && c.prov.beaconCommit == ""
}

// CloseMint materializes Closed once the sale window has passed. Anyone may
// call it; reveals and Finalize work without it.
func CloseMint(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	refresh(c, height())
	if c.state != types.StateClosed {
		panic("the sale is not over (state " + c.state.String() + ")")
	}
}

// --- creator -----------------------------------------------------------------

// TransferCreator starts a two-step handover (RA M-11).
func TransferCreator(cur realm, cid string, to address) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	if !to.IsValid() {
		panic("invalid address")
	}
	c.pendingCreator = to
	chain.Emit("CreatorTransferStarted", "cid", cid, "from", c.creator.String(), "to", to.String())
}

func AcceptCreator(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	who := caller(cur)
	if c.pendingCreator == "" || who != c.pendingCreator {
		panic("no pending creator transfer to this address")
	}
	byCreator.Remove(c.creator.String() + ":" + collKey(cid))
	byCreator.Set(who.String()+":"+collKey(cid), cid)
	chain.Emit("CreatorTransferred", "cid", cid, "from", c.creator.String(), "to", who.String())
	c.creator = who
	c.pendingCreator = ""
}

// SetPayees changes the royalty split after Final. The primary-sale split is
// frozen with the sale (I-6); the royalty receiver stays the collection's
// sub-treasury, so third-party markets are unaffected. Royalties earned so
// far are first paid to the current payees (SA-I4).
func SetPayees(cur realm, cid, payees string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	if c.state != types.StateFinal {
		panic("royalty payees can change only after the collection is final")
	}
	ps := safe.ParsePayees("royaltyPayees", payees, MaxPayees)
	assertPayees("royaltyPayees", ps, cid, c.engineID)
	distribute(cur, c)
	c.royaltyPayees = ps
	chain.Emit("RoyaltyPayees", "cid", cid, "payees", payees)
}

// assertPayees refuses payees that can never spend what they receive
// (SA-L5): the platform's own realms and sub-addresses. cid is the
// collection being configured, engineID its engine adapter.
func assertPayees(field string, ps []types.Payee, cid, engineID string) {
	for _, p := range ps {
		assertSpendable(field, p.Addr, cid, engineID)
	}
}

// assertSpendable panics for core, core's sub-addresses of collection cid
// (token identity c/<cid>, royalty treasury roy/<cid>), every minter ever
// approved, the engine adapter, and the platform realms next to core
// (market, reader, gallery, the genesis adapter). None of them has a path
// that spends an incoming payment, so the coins would be stranded (I-3).
func assertSpendable(field string, addr address, cid, engineID string) {
	bad := []address{chain.PackageAddress(selfPath)}
	if cid != "" {
		bad = append(bad, chain.DerivePkgSubAddr(selfPath, "c/"+cid), royaltyAddress(cid))
	}
	if engineID != "" {
		bad = append(bad, chain.PackageAddress(engineID))
	}
	base := strings.TrimSuffix(selfPath, "/core")
	for _, sib := range platformRealms {
		bad = append(bad, chain.PackageAddress(base+"/"+sib))
	}
	for _, b := range bad {
		if addr == b {
			panic(field + ": " + addr.String() + " is a platform realm address that cannot spend; use a wallet")
		}
	}
	minters.Iterate("", "", func(path string, _ any) bool {
		if addr == chain.PackageAddress(path) {
			panic(field + ": " + addr.String() + " is the minter realm " + path + "; use a wallet")
		}
		return false
	})
}

// platformRealms are the realm paths next to core (README package map).
var platformRealms = []string{"mint/v1", "market/v1", "engines/genesis", "reader", "gallery"}

func assertCreator(cur realm, c *collection) {
	if caller(cur) != c.creator {
		panic("only the collection's creator can do this")
	}
}

func assertBoundMinter(cur realm, c *collection) {
	if cur.Previous().PkgPath() != c.minter {
		panic("only the collection's bound minter (" + c.minter + ") can do this")
	}
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

// Package core is the platform's immutable ledger (design §2.5.2): every
// collection, its official grc721 token and royalty, its provenance
// (commit–reveal v2), the engine registry, fees and the admin timelock.
//
// What core guarantees, whoever holds the admin key:
//
//   - I-1  admin cannot move, approve or burn a token, and holds no funds;
//     the op list is a closed set of parameters (admin.gno).
//   - I-2  pause only gates create, mint and trade. Transfer, burn,
//     finalize, distribute and every cancel stay open. A pause expires by
//     itself, cannot be renewed while it runs, and each scope has a budget
//     of MaxPauseBlocks per PauseWindowBlocks (SA-L2).
//   - I-5  supply only grows through the collection's bound minter, never
//     past maxSupply, and a token id is never minted twice.
//   - I-6  after Launch the engine, params, supply, payees, sale window,
//     commitments, randomness source and fee snapshots are frozen.
//   - I-9  MintedBy(addr) is exact while a collection is not Final:
//     grc721 balance minus the reserves sent to addr. It needs I-11 (no
//     token moves or burns before Final); if that lock is ever relaxed the
//     counter must be stored again (TestRegress_P2_*).
//   - I-10/11  a collection becomes Final at most once, only with both
//     reveals or after revealDeadline, and that deadline is bounded, so
//     the pre-reveal transfer lock always ends.
//   - I-12 engine code never runs on a state-changing path, except the
//     creator's own CreateCollection (ValidateParams) and the engine's own
//     RegisterEngine (one sample render). Every exported non-crossing
//     function is read-only, so an engine cannot call back into a mutator.
//     An admin-approved randomness provider (randomness.gno) runs only in
//     RequestRandomness/FulfillRandomness of collections launched with it.
//   - I-13 every stored string passed safe.AssertText.
//
// core imports no mutable realm: minters and engines are known only by
// package path and interface value.
package core

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/royalty/v0"
	"gno.land/p/nt/grc721/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Hard limits. They are constants on purpose: nobody, admin included, can
// raise them after deploy (block counts assume ~3.54 s blocks, RA M-1).
const (
	ProtocolFeeCapBps = 500           // 5% of any sale
	RoyaltyCapBps     = 1000          // 10% (RA M-3)
	CreateFeeCap      = 1_000_000_000 // 1,000 GNOT in ugnot
	MaxPayees         = 4
	MaxSupplyCap      = 10_000
	MaxMintPerTx      = 10    // hypothesis: measure n=10 gas/deposit on Onyx
	MaxReserveBps     = 1000  // creator reserve <= 10% of supply
	MaxSaleBlocks     = 732_000 // ~30 days
	RevealWindowMin   = 1_017   // ~1 hour
	RevealWindowMax   = 170_000 // ~7 days
	BeaconGraceBlocks = 254     // beacon may reveal first in the window's last ~15 min (< RevealWindowMin, so the creator always gets to go first)
	TimelockBlocks    = 48_800  // ~48 hours
	MaxPauseBlocks    = 195_000 // ~8 days: pause budget per scope and window
	PauseWindowBlocks = 732_000 // ~30 days (SA-L2)
	EngineFeeCapBps   = engine.MaxFeeBps // 5%: hard cap of an engine author's fee (platform cap <= this)
	RequestMargin     = 127              // a randomness request leaves >= this many blocks before revealDeadline

	MaxNameLen        = 64
	MaxDescriptionLen = 1024
	MaxParamsLen      = 1024
	MinSecretLen      = 32
	MaxSecretLen      = 256
	MaxPageSize       = 50
)

// Provenance badges (design §4.3).
const (
	BadgeBoth        = "2/2"
	BadgeCreatorOnly = "creator-only"
	BadgeBeaconOnly  = "beacon-only"
	BadgeFallback    = "fallback"
)

type collection struct {
	id, name, symbol, description string
	creator, pendingCreator       address
	engineID, params              string
	maxSupply                     int64
	nextTID                       int64 // next token id; minted so far = nextTID-1
	reserved                      int64
	royaltyBps                    int64
	primaryPayees, royaltyPayees  []types.Payee
	minter                        string
	state                         types.State
	startHeight, endHeight        int64
	revealWindow                  int64
	closeHeight                   int64 // sell-out height, or endHeight once time ran out
	useBeacon                     bool
	beaconSource                  string // with useBeacon: types.BeaconCommitted or a randomness provider path
	createdHeight                 int64
	primaryBps                    int64    // protocol fee snapshot at Launch (SA-I5)
	engineBps                     int64    // engine-author fee snapshot at Launch (0 when creator == author)
	engineAuthor                  address  // who receives engineBps
	burnedCommits                 []string // commitments whose secret went public; never accepted again here (SA-L1)
	approvals                     avl.Tree // "o:"+owner+":"+operator -> int64 nonce (SA-L3; token nonces are packed in st)
	prov                          *provenance
	token                         *grc721.Token
	ledger                        *grc721.PrivateLedger
	roy                           *royalty.Royalty
	st                            *tokenState
	reservedTo                    avl.Tree // address -> int64 reserve tokens received (MintedBy = balance - this, I-9)
}

func (c *collection) minted() int64 { return c.nextTID - 1 }

var (
	// selfPath is this realm's package path, captured once in init so read
	// functions can derive sub-addresses without a cur.
	selfPath string

	collections avl.Tree // safe.PadInt(cid) -> *collection
	byCreator   avl.Tree // creator + ":" + padded cid -> cid
	collCount   int64
)

func init(cur realm) {
	selfPath = cur.PkgPath()
}

const cidWidth = 10

func collKey(cid string) string {
	return safe.PadInt(safe.ParseID("cid", cid), cidWidth)
}

func mustCollection(cid string) *collection {
	v := collections.Get(collKey(cid))
	if v == nil {
		panic("unknown collection " + strconv.Quote(cid))
	}
	return v.(*collection)
}

// stateAt is the effective state at height h; the stored state lags until
// the next write materializes it (refresh).
func stateAt(c *collection, h int64) types.State {
	switch c.state {
	case types.StateScheduled:
		if h > c.endHeight {
			return types.StateClosed
		}
		if h >= c.startHeight {
			return types.StateMinting
		}
	case types.StateMinting:
		if h > c.endHeight {
			return types.StateClosed
		}
	}
	return c.state
}

func refresh(c *collection, h int64) {
	s := stateAt(c, h)
	if s == c.state {
		return
	}
	if s == types.StateClosed && c.closeHeight == 0 {
		c.closeHeight = c.endHeight
	}
	c.state = s
	chain.Emit("CollectionState", "cid", c.id, "state", s.String())
}

// revealDeadline is when anyone may finalize without the missing secrets.
// It is at most endHeight + RevealWindowMax, which bounds the transfer
// lock (I-11).
func revealDeadline(c *collection) int64 {
	closed := c.closeHeight
	if closed == 0 {
		closed = c.endHeight
	}
	return closed + c.revealWindow
}

func caller(cur realm) address {
	return cur.Previous().Address()
}

// assertNoDeposit refuses coins on functions that take none, so nothing can
// get stuck in core (RA L-1). The origin-send envelope belongs to the first
// realm of the call; it is only ours to judge when a wallet called us.
func assertNoDeposit(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func height() int64 { return runtime.ChainHeight() }

package core

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// Engine registry ("art as code", design §5).
//
// An engine registers itself from its own /r/ adapter realm; its id is that
// realm's package path, so nobody can register in someone else's name. The
// stored interface value's methods are declared in the adapter, so every
// call runs with the adapter's authority, not core's (interrealm v2 borrow
// rule #1): engine code cannot write core state. It also cannot call back
// into a core mutator: all of core's state-changing functions are crossing
// and need a live cur the engine never has.
//
// Honest limits, surfaced to users rather than hidden:
//   - an adapter realm with state could change its art later; the sample
//     fingerprint (VerifyEngine) detects a change of the sample, and review
//     means reading the adapter for statelessness;
//   - a private (re-deployable) adapter cannot register: the VM aborts the
//     registration when core's state would retain the private realm's type
//     (spike A9, observed in gno v1.7.0 test mode; confirm on Onyx).
type engineRecord struct {
	id               string
	impl             engine.Engine
	manifest         engine.Manifest // core-owned copy
	fingerprint      string          // sha256 of Render(SampleInput())
	claimed          bool
	deprecated       bool
	reviewed         bool
	registeredHeight int64
}

var (
	engines     avl.Tree // engine id -> *engineRecord
	engineOrder avl.Tree // safe.PadInt(seq) -> engine id
	engineCount int64
)

// RegisterEngine stores the calling realm's engine (I-12 exception: one
// sample render in the engine's own registration transaction). The record
// is immutable afterwards except for the claim/deprecate/review flags.
func RegisterEngine(cur realm, e engine.Engine) string {
	id := cur.Previous().PkgPath()
	if !strings.HasPrefix(id, runtime.ChainDomain()+"/r/") || strings.Contains(id, "#") {
		panic("an engine registers from its own realm (an /r/ package, not a sub-realm or wallet)")
	}
	if e == nil {
		panic("nil engine")
	}
	if engines.Has(id) {
		panic("engine already registered: " + id + " (publish a new version under a new path)")
	}
	m := copyManifest(e.Manifest())
	if err := engine.ValidateManifest(m); err != nil {
		panic(err)
	}
	if err := e.ValidateParams(""); err != nil {
		panic("engine must accept empty params (its defaults): " + err.Error())
	}
	sample := e.Render(engine.SampleInput())
	if err := engine.CheckSVG(m, sample); err != nil {
		panic("sample render: " + err.Error())
	}
	if err := engine.ValidateTraits(m, e.Traits(engine.SampleInput())); err != nil {
		panic("sample traits: " + err.Error())
	}

	rec := &engineRecord{
		id:               id,
		impl:             e,
		manifest:         m,
		fingerprint:      safe.Sha256Hex(sample),
		registeredHeight: height(),
	}
	engines.Set(id, rec)
	engineCount++
	engineOrder.Set(safe.PadInt(engineCount, cidWidth), id)
	chain.Emit("EngineRegistered", "id", id, "author", m.Author.String(), "feeBps", itoa(m.FeeBps),
		"fingerprint", rec.fingerprint)
	return id
}

// ClaimEngine proves the manifest author controls that address. Unclaimed
// engines cannot back a collection.
func ClaimEngine(cur realm, id string) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	if caller(cur) != rec.manifest.Author {
		panic("only the manifest author " + rec.manifest.Author.String() + " can claim this engine")
	}
	rec.claimed = true
	chain.Emit("EngineClaimed", "id", id)
}

// DeprecateEngine stops new collections; existing ones keep rendering.
func DeprecateEngine(cur realm, id string) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	if !rec.claimed || caller(cur) != rec.manifest.Author {
		panic("only the engine's author can deprecate it")
	}
	rec.deprecated = true
	chain.Emit("EngineDeprecated", "id", id)
}

// --- engine-author fee ---------------------------------------------------------
//
// An engine's author earns FeeBps (manifest, fixed at registration, <=
// EngineFeeCapBps) of every primary and secondary sale of a collection that
// uses the engine, capped by the platform's fees.EngineCapBps. A collection
// snapshots the fee at Launch (like the protocol fee, SA-I5) and later sales
// pay min(snapshot, current platform cap), so neither the author nor the
// admin can raise it on a running collection. No fee when the creator is
// the author: the creator's own payees already get the sale.

// engineFeeOf is the engine's fee under the current platform cap.
func engineFeeOf(rec *engineRecord) int64 {
	if rec.manifest.FeeBps < fees.EngineCapBps {
		return rec.manifest.FeeBps
	}
	return fees.EngineCapBps
}

// engineFeeQuote is what c would snapshot at a Launch now.
func engineFeeQuote(c *collection) (address, int64) {
	rec := mustEngine(c.engineID)
	author := rec.manifest.Author
	if author == c.creator {
		return author, 0
	}
	return author, engineFeeOf(rec)
}

// collectionEngineFee is the fee a sale of c pays now: the Launch snapshot
// bounded by the current cap; before Launch, the current quote.
func collectionEngineFee(c *collection) (address, int64) {
	if c.prov == nil {
		return engineFeeQuote(c)
	}
	if c.engineBps < fees.EngineCapBps {
		return c.engineAuthor, c.engineBps
	}
	return c.engineAuthor, fees.EngineCapBps
}

// EngineFee is the engine-author share of cid's sales: the author and the
// bps a sale pays now (0 when the creator is the author). mint/v1 and
// market/v1 pay safe.BpsOf(amount, bps) to author.
func EngineFee(cid string) (author address, bps int64) {
	return collectionEngineFee(mustCollection(cid))
}

func mustEngine(id string) *engineRecord {
	v := engines.Get(id)
	if v == nil {
		panic("unknown engine " + id)
	}
	return v.(*engineRecord)
}

// copyManifest gives core its own copy: the engine's slice was allocated in
// the engine realm.
func copyManifest(m engine.Manifest) engine.Manifest {
	out := m
	out.TraitTypes = append([]string{}, m.TraitTypes...)
	return out
}

// --- engine reads (Studio, Verify) -------------------------------------------

// RenderWith renders any registered engine for arbitrary params and seed as
// a data URI — Studio previews and the Verify button.
func RenderWith(id, params, seed string) string {
	rec := mustEngine(id)
	if err := rec.impl.ValidateParams(params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}
	svg := rec.impl.Render(studioInput(params, seed))
	if err := engine.CheckSVG(rec.manifest, svg); err != nil {
		return dataURI(placeholderSVG(rec.manifest.Name, "Engine output rejected"))
	}
	return dataURI(svg)
}

// EngineTraits returns a core-owned copy of the engine's traits for seed.
func EngineTraits(id, params, seed string) []engine.Trait {
	rec := mustEngine(id)
	if err := rec.impl.ValidateParams(params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}
	ts := rec.impl.Traits(studioInput(params, seed))
	if err := engine.ValidateTraits(rec.manifest, ts); err != nil {
		panic("engine traits rejected: " + err.Error())
	}
	return append([]engine.Trait{}, ts...)
}

func TraitsWith(id, params, seed string) string {
	w := &safe.JSONWriter{}
	writeTraits(w, EngineTraits(id, params, seed))
	return w.String()
}

// VerifyEngine re-renders the sample and compares it with the fingerprint
// stored at registration.
func VerifyEngine(id string) bool {
	rec := mustEngine(id)
	return safe.Sha256Hex(rec.impl.Render(engine.SampleInput())) == rec.fingerprint
}

// EngineManifest is the typed read for other realms (gallery).
func EngineManifest(id string) engine.Manifest { return copyManifest(mustEngine(id).manifest) }

// EngineStatus is "unclaimed", "unverified", "reviewed" or "deprecated".
func EngineStatus(id string) string { return engineStatus(mustEngine(id)) }

func engineStatus(rec *engineRecord) string {
	switch {
	case rec.deprecated:
		return "deprecated"
	case !rec.claimed:
		return "unclaimed"
	case rec.reviewed:
		return "reviewed"
	}
	return "unverified"
}

// Engine is the record as JSON.
func Engine(id string) string {
	w := &safe.JSONWriter{}
	writeEngine(w, mustEngine(id))
	return w.String()
}

func Engines(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	engineOrder.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		writeEngine(w, mustEngine(v.(string)))
		return false
	})
	w.EndArray()
	return w.String()
}

func writeEngine(w *safe.JSONWriter, rec *engineRecord) {
	m := rec.manifest
	w.BeginObject()
	w.StrField("id", rec.id)
	w.StrField("pkgPath", rec.id) // the adapter realm; read its source (and imports) with vm/qfile
	w.StrField("name", m.Name)
	w.StrField("version", m.Version)
	w.StrField("description", m.Description)
	w.StrField("license", m.License)
	w.StrField("author", m.Author.String())
	w.IntField("feeBps", m.FeeBps)
	w.IntField("effectiveFeeBps", engineFeeOf(rec))
	w.StrField("paramsSchema", m.ParamsSchema)
	w.Key("traitTypes")
	w.BeginArray()
	for _, t := range m.TraitTypes {
		w.Str(t)
	}
	w.EndArray()
	w.BoolField("living", m.Living)
	w.IntField("maxSvgBytes", m.MaxSVGBytes)
	w.StrField("fingerprint", rec.fingerprint)
	w.StrField("status", engineStatus(rec))
	w.IntField("registeredHeight", rec.registeredHeight)
	w.EndObject()
}

func studioInput(params, seed string) engine.Input {
	in := engine.SampleInput()
	in.Seed = seed
	in.Params = params
	in.Height = height()
	return in
}

package core

import (
	"chain"
	"chain/runtime"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Commit–reveal v2 (design §4.2–4.3, closes RA H-3, M-5, M-6).
//
// The map is fixed by three inputs: the creator's secret sc, the beacon's
// secret sb and the public mint-entropy accumulator acc. Neither committer
// knows the other's secret while minting is open, so neither can time the
// last mint for a good map. Order of reveals:
//
//  1. nothing is accepted before Closed (an early reveal informs the other
//     side);
//  2. the creator may reveal until revealDeadline - BeaconGraceBlocks; the
//     beacon follows at any time before the deadline;
//  3. inside the last BeaconGraceBlocks only the beacon may reveal. If the
//     creator stayed silent, the beacon's reveal finalizes at once
//     ("beacon-only"), so the creator never sees sb while it can still
//     choose (SA-M1; this also closes the mempool race of a creator
//     front-running the beacon's grace reveal);
//  4. after revealDeadline anyone finalizes with whatever was revealed.
//
// What stays open, by design: the beacon, as last revealer after the
// creator, can still choose between revealing and not (one bit). It runs
// public code and the badge shows the outcome. The transfer lock
// (tokens.gno) keeps anyone from trading on early knowledge until Final.
//
// A collection launched without the beacon (only possible while no beacon
// is configured, SA-M2) gives the creator the whole choice of the map; it
// can have no creator reserve and is never reported as a fair launch
// (FairLaunch, Provenance "fair").
type provenance struct {
	creatorCommit, beaconCommit string
	acc                         string
	creatorSecret, beaconSecret string
	creatorRevealed             bool
	beaconRevealed              bool
	salt, badge                 string
	finalHeight                 int64
	round                       int64 // randomness provider round bound by RequestRandomness (0 = none)
}

const (
	roleCreator = "creator"
	roleBeacon  = "beacon"
)

// BeaconCommit is the beacon's commitment, before any token exists.
func BeaconCommit(cur realm, cid, commitHex string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if beacon == "" || caller(cur) != beacon {
		panic("only the configured beacon can commit")
	}
	if c.state == types.StateDraft || c.prov == nil || !c.useBeacon || usesProvider(c) {
		panic("this collection is not waiting for a beacon")
	}
	if c.prov.beaconCommit != "" {
		panic("the beacon already committed")
	}
	if c.minted() > 0 {
		panic("too late: tokens were minted before the beacon committed")
	}
	commit := safe.AssertHex("commit", commitHex, 32)
	if isBurned(c, commit) {
		panic("this commitment's secret was already revealed for this collection")
	}
	c.prov.beaconCommit = commit
	chain.Emit("BeaconCommitted", "cid", cid, "commit", commit)
}

func RevealCreatorSecret(cur realm, cid, secret string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	h := height()
	assertRevealOpen(c, h)
	if c.prov.creatorRevealed {
		panic("the creator secret is already revealed")
	}
	if c.useBeacon {
		// SA-M1: once the grace period starts only the beacon may reveal, so
		// the creator can never reveal after seeing sb.
		if c.prov.beaconRevealed {
			panic("the beacon revealed first; the outcome is fixed")
		}
		if h >= revealDeadline(c)-BeaconGraceBlocks {
			panic("the creator's reveal window ended at height " + itoa(revealDeadline(c)-BeaconGraceBlocks-1) +
				"; only the beacon may reveal now")
		}
	}
	assertSecret(c, roleCreator, secret, c.prov.creatorCommit)
	c.prov.creatorSecret = secret
	c.prov.creatorRevealed = true
	chain.Emit("CreatorRevealed", "cid", cid, "secret", secret)
	if revealsComplete(c) {
		finalize(c, h)
	}
}

func RevealBeaconSecret(cur realm, cid, secret string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if beacon == "" || caller(cur) != beacon {
		panic("only the configured beacon can reveal")
	}
	h := height()
	assertRevealOpen(c, h)
	if !c.useBeacon || usesProvider(c) || c.prov.beaconCommit == "" {
		panic("this collection has no beacon commitment")
	}
	if c.prov.beaconRevealed {
		panic("the beacon secret is already revealed")
	}
	if !c.prov.creatorRevealed && h < revealDeadline(c)-BeaconGraceBlocks {
		panic("the beacon reveals after the creator, or in the window's last " + itoa(BeaconGraceBlocks) + " blocks")
	}
	assertSecret(c, roleBeacon, secret, c.prov.beaconCommit)
	c.prov.beaconSecret = secret
	c.prov.beaconRevealed = true
	chain.Emit("BeaconRevealed", "cid", cid, "secret", secret)
	// After the creator: both secrets are in (2/2). First, in the grace
	// period: the creator can no longer reveal, so the map is fixed now
	// (beacon-only) — nobody is left holding a choice (SA-M1).
	finalize(c, h)
}

// Finalize is permissionless and never paused (I-2): immediately once every
// expected secret is revealed, otherwise after revealDeadline (fallback).
func Finalize(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	refresh(c, h)
	if c.state != types.StateClosed {
		panic("only a closed collection can be finalized (state " + c.state.String() + ")")
	}
	if !revealsComplete(c) && h <= revealDeadline(c) {
		panic("the reveal window is open until height " + itoa(revealDeadline(c)))
	}
	// SA-I9: a sale that minted nothing stays Closed, so its creator can
	// still abort and relaunch; nobody else can lock it into Final.
	if c.minted() == 0 {
		panic("nothing was minted; the creator may abort and relaunch instead")
	}
	finalize(c, h)
}

func assertRevealOpen(c *collection, h int64) {
	refresh(c, h)
	if c.state != types.StateClosed {
		panic("secrets are accepted only after the sale closed (state " + c.state.String() + ")")
	}
	if h > revealDeadline(c) {
		panic("the reveal window closed; call Finalize")
	}
}

func assertSecret(c *collection, role, secret, commit string) {
	if len(secret) < MinSecretLen || len(secret) > MaxSecretLen {
		panic("secret must be " + itoa(MinSecretLen) + ".." + itoa(MaxSecretLen) + " bytes")
	}
	safe.AssertText("secret", secret, MaxSecretLen)
	if safe.Commit(runtime.ChainID(), c.id, role, secret) != commit {
		panic("secret does not match the " + role + " commitment")
	}
}

func revealsComplete(c *collection) bool {
	return c.prov.creatorRevealed && (!c.useBeacon || c.prov.beaconRevealed)
}

// finalize runs at most once per collection (I-10): every caller checks
// state Closed, and this sets Final.
func finalize(c *collection, h int64) {
	p := c.prov
	p.salt = safe.Salt(c.id, p.creatorSecret, p.beaconSecret, p.acc)
	switch {
	case p.creatorRevealed && p.beaconRevealed:
		p.badge = BadgeBoth
	case p.creatorRevealed:
		p.badge = BadgeCreatorOnly
	case p.beaconRevealed:
		p.badge = BadgeBeaconOnly
	default:
		p.badge = BadgeFallback
	}
	p.finalHeight = h
	c.state = types.StateFinal
	c.st.final = true
	chain.Emit("CollectionFinal", "cid", c.id, "salt", p.salt, "badge", p.badge)
}

// VerifyProvenance recomputes every commitment and the salt from public
// data. True only for a Final collection whose record is consistent.
func VerifyProvenance(cid string) bool {
	c := mustCollection(cid)
	if c.state != types.StateFinal {
		return false
	}
	p := c.prov
	chainID := runtime.ChainID()
	if p.creatorRevealed && safe.Commit(chainID, c.id, roleCreator, p.creatorSecret) != p.creatorCommit {
		return false
	}
	if p.beaconRevealed && !usesProvider(c) && safe.Commit(chainID, c.id, roleBeacon, p.beaconSecret) != p.beaconCommit {
		return false
	}
	// A provider's value was checked by FulfillRandomness against the
	// provider's verified round (p.round); it is recomputable off chain
	// from the provider's public source (e.g. the drand round).
	return p.salt == safe.Salt(c.id, p.creatorSecret, p.beaconSecret, p.acc)
}

// FairLaunch is true only for a Final, consistent collection whose map no
// single party could choose: launched with the beacon and finalized with
// both secrets or with the beacon's alone (after the creator stayed
// silent). Creator-only collections (no beacon: the creator alone knew the
// only secret and could steer the last mint, SA-M2) and fallbacks are not
// fair launches, even when VerifyProvenance is true.
func FairLaunch(cid string) bool {
	c := mustCollection(cid)
	if !VerifyProvenance(cid) || !c.useBeacon {
		return false
	}
	return c.prov.badge == BadgeBoth || c.prov.badge == BadgeBeaconOnly
}

func isBurned(c *collection, commit string) bool {
	for _, b := range c.burnedCommits {
		if b == commit {
			return true
		}
	}
	return false
}

// Provenance is the whole record as JSON; secrets and salt stay "" until
// revealed / final.
func Provenance(cid string) string {
	c := mustCollection(cid)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("cid", c.id)
	w.StrField("chainId", runtime.ChainID())
	w.StrField("state", stateAt(c, height()).String())
	w.IntField("minted", c.minted())
	w.IntField("reserved", c.reserved)
	if p := c.prov; p != nil {
		w.BoolField("useBeacon", c.useBeacon)
		w.StrField("beaconSource", c.beaconSource)
		w.IntField("round", p.round)
		w.StrField("creatorCommit", p.creatorCommit)
		w.StrField("beaconCommit", p.beaconCommit)
		w.StrField("entropy", p.acc)
		w.StrField("creatorSecret", p.creatorSecret)
		w.StrField("beaconSecret", p.beaconSecret)
		w.StrField("salt", p.salt)
		w.StrField("badge", p.badge)
		w.IntField("revealDeadline", revealDeadline(c))
		w.IntField("finalHeight", p.finalHeight)
		w.BoolField("verified", VerifyProvenance(cid))
		w.BoolField("fair", FairLaunch(cid))
	}
	w.EndObject()
	return w.String()
}

package core

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Pluggable randomness sources (beacon v2).
//
// A collection launched with useBeacon picks its second entropy source at
// Launch (LaunchSpec.BeaconSource, frozen by I-6):
//
//   - types.BeaconCommitted: the platform beacon's commit-reveal
//     (provenance.gno; BeaconCommit before the first mint,
//     RevealBeaconSecret after the creator).
//   - the package path of a randomness provider realm: a public random
//     value nobody can know in advance, e.g. a drand round relayed and
//     BLS-verified on chain (gnolang/gno#6268 p/drand + r/drand). Nothing
//     is committed before the sale; the round is fixed only once the
//     creator can no longer choose (RequestRandomness), then anyone pulls
//     its value (FulfillRandomness).
//
// A provider realm registers itself (its id is its package path, as for
// engines) and is usable only after the admin approves it through the
// timelocked op randomness.add; randomness.deprecate stops new launches,
// running collections finish with it. So a drand provider plugs in without
// a core redeploy. Its methods are declared in its own realm, so core
// calling them runs the provider with the provider's authority (interrealm
// v2 borrow rule #1): it cannot write core state, and with no cur it cannot
// call a core mutator.
//
// Order with a provider (same guarantees as the committed beacon, SA-M1):
//
//  1. the creator reveals until revealDeadline - BeaconGraceBlocks;
//  2. RequestRandomness (anyone) after the creator revealed, or inside the
//     grace period when it stayed silent, and no later than revealDeadline
//     - RequestMargin: binds the collection to provider.Target(), a round
//     whose value nobody knows yet — not the creator, whose secret is
//     public or whose window is closed, not the minters, whose sale is over;
//  3. FulfillRandomness (anyone) once the provider has that round: the
//     value becomes the beacon secret and the collection is Final at once
//     (2/2 after the creator, beacon-only in grace);
//  4. after revealDeadline Finalize works as before (creator-only /
//     fallback if the provider never delivered).
type RandomnessProvider interface {
	// Name is a short label for UIs, e.g. "drand quicknet".
	Name() string
	// Target is the round a request made in the current block is bound
	// to. Its value must be unknowable to anyone at this block (a round
	// published strictly in the future). Read-only.
	Target() int64
	// Randomness is round's verified value as 64 lowercase hex characters
	// (32 bytes), or "" while it is not available. Read-only.
	Randomness(round int64) string
}

type providerRecord struct {
	id               string
	name             string
	impl             RandomnessProvider
	active           bool // approved by the admin and not deprecated
	registeredHeight int64
}

var (
	providers       avl.Tree // provider pkgpath -> *providerRecord
	activeProviders int64
)

const MaxProviderNameLen = 64

// RegisterRandomnessProvider stores the calling realm's provider. It is
// inert until the admin approves it (randomness.add, timelocked).
func RegisterRandomnessProvider(cur realm, p RandomnessProvider) string {
	assertNoDeposit(cur)
	id := cur.Previous().PkgPath()
	if !strings.HasPrefix(id, runtime.ChainDomain()+"/r/") || strings.Contains(id, "#") {
		panic("a randomness provider registers from its own realm (an /r/ package, not a sub-realm or wallet)")
	}
	if p == nil {
		panic("nil provider")
	}
	if providers.Has(id) {
		panic("randomness provider already registered: " + id)
	}
	name := p.Name()
	safe.AssertNonEmptyText("provider name", name, MaxProviderNameLen)
	providers.Set(id, &providerRecord{id: id, name: name, impl: p, registeredHeight: height()})
	chain.Emit("RandomnessProviderRegistered", "id", id, "name", name)
	return id
}

func mustProvider(id string) *providerRecord {
	v := providers.Get(id)
	if v == nil {
		panic("unknown randomness provider " + id)
	}
	return v.(*providerRecord)
}

func assertActiveProvider(id string) {
	if !mustProvider(id).active {
		panic("randomness provider " + id + " is not approved")
	}
}

// beaconAvailable: some unpredictable second source exists, so no launch
// may opt out of it (SA-M2).
func beaconAvailable() bool { return beacon != "" || activeProviders > 0 }

func usesProvider(c *collection) bool {
	return c.useBeacon && c.beaconSource != types.BeaconCommitted
}

// RequestRandomness binds a provider-backed collection to the provider's
// next unknowable round. Permissionless and never paused (I-2).
func RequestRandomness(cur realm, cid string) int64 {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	assertRevealOpen(c, h)
	if !usesProvider(c) {
		panic("this collection does not use a randomness provider")
	}
	p := c.prov
	if p.round != 0 {
		panic("randomness already requested for round " + itoa(p.round))
	}
	dl := revealDeadline(c)
	if !p.creatorRevealed && h < dl-BeaconGraceBlocks {
		panic("randomness is requested after the creator reveals, or in the window's last " +
			itoa(BeaconGraceBlocks) + " blocks")
	}
	if h > dl-RequestMargin {
		panic("too late to request randomness (last height " + itoa(dl-RequestMargin) + "); call Finalize after the deadline")
	}
	round := mustProvider(c.beaconSource).impl.Target()
	if round <= 0 {
		panic("randomness provider returned an invalid round")
	}
	p.round = round
	chain.Emit("RandomnessRequested", "cid", cid, "provider", c.beaconSource, "round", itoa(round))
	return round
}

// FulfillRandomness takes the requested round's value from the provider as
// the beacon secret and finalizes (2/2 after the creator, beacon-only when
// it stayed silent). Permissionless and never paused (I-2).
func FulfillRandomness(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	assertRevealOpen(c, h)
	if !usesProvider(c) {
		panic("this collection does not use a randomness provider")
	}
	p := c.prov
	if p.round == 0 {
		panic("randomness was not requested yet")
	}
	v := mustProvider(c.beaconSource).impl.Randomness(p.round)
	if v == "" {
		panic("round " + itoa(p.round) + " is not available from the provider yet")
	}
	v = safe.AssertHex("randomness", v, 32)
	p.beaconSecret = v
	p.beaconRevealed = true
	chain.Emit("BeaconRevealed", "cid", cid, "provider", c.beaconSource, "round", itoa(p.round), "secret", v)
	finalize(c, h)
}

// RandomnessProviders lists registered providers (by path) as JSON:
// [{id, name, active, registeredHeight}]. Registration is open, so only
// "active" ones (admin-approved) can be chosen at Launch.
func RandomnessProviders(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	providers.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		r := v.(*providerRecord)
		w.BeginObject()
		w.StrField("id", r.id)
		w.StrField("name", r.name)
		w.BoolField("active", r.active)
		w.IntField("registeredHeight", r.registeredHeight)
		w.EndObject()
		return false
	})
	w.EndArray()
	return w.String()
}

package core

import (
	"chain"
	"strings"

	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
)

// Every function in this file is read-only (I-12: no exported non-crossing
// mutator). Lists are paginated with limit <= MaxPageSize (RA L-4).

// SelfAddress is core's package address, for the deploy-time cross-check
// against scripts/pkgaddr.py (RA H-5).
func SelfAddress() address { return chain.PackageAddress(selfPath) }

func CollectionCount() int64 { return collCount }

// MintedTotal counts every token ever minted, burned ones included (OA B4).
func MintedTotal(cid string) int64 { return mustCollection(cid).minted() }

// MintedBy is addr's lifetime count of sale mints in cid (OA B3, I-9),
// reserves excluded. Exact until the collection is Final, -1 afterwards
// (derived from the locked grc721 balance; see mintedBy).
func MintedBy(cid string, addr address) int64 { return mintedBy(mustCollection(cid), addr) }

// Info is the typed collection view for other realms.
func Info(cid string) types.CollectionInfo {
	c := mustCollection(cid)
	info := types.CollectionInfo{
		ID:          c.id,
		Name:        c.name,
		Symbol:      c.symbol,
		Description: c.description,
		Creator:     c.creator,
		Minter:      c.minter,
		EngineID:    c.engineID,
		Params:      c.params,
		State:       stateAt(c, height()),
		MaxSupply:   c.maxSupply,
		Minted:      c.minted(),
		Reserved:    c.reserved,
		StartHeight: c.startHeight,
		EndHeight:   c.endHeight,
		RoyaltyBps:  c.royaltyBps,
	}
	if c.prov != nil {
		info.RevealDeadline = revealDeadline(c)
		info.Badge = c.prov.badge
	}
	return info
}

// PrimaryPayees returns a copy of the frozen primary-sale split.
func PrimaryPayees(cid string) []types.Payee {
	return append([]types.Payee{}, mustCollection(cid).primaryPayees...)
}

// FeeConfig is the typed fee view minters and markets settle with.
func FeeConfig() types.Fees { return fees }

// PrimaryFeeBps is the protocol fee on cid's primary sale: the fee at
// Launch, or the current one if the admin lowered it since (SA-I5: a fee
// cannot rise during a sale).
func PrimaryFeeBps(cid string) int64 {
	c := mustCollection(cid)
	if c.prov != nil && c.primaryBps < fees.PrimaryBps {
		return c.primaryBps
	}
	return fees.PrimaryBps
}

func Beacon() address { return beacon }

func Admin() address { return admin }

func IsMinter(path string) bool {
	v := minters.Get(path)
	return v != nil && !v.(*minterRecord).deprecated
}

// Collection is the collection record as JSON.
func Collection(cid string) string {
	w := &safe.JSONWriter{}
	writeCollection(w, mustCollection(cid))
	return w.String()
}

func Collections(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	collections.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		writeCollection(w, v.(*collection))
		return false
	})
	w.EndArray()
	return w.String()
}

func CollectionsByCreator(creator address, offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	prefix := creator.String() + ":"
	skipped, written, want := int64(0), int64(0), clampLimit(limit)
	byCreator.Iterate(prefix, prefix+"\xff", func(_ string, v any) bool {
		if skipped < offset {
			skipped++
			return false
		}
		writeCollection(w, mustCollection(v.(string)))
		written++
		return written >= want
	})
	w.EndArray()
	return w.String()
}

// Fees is the fee configuration and its hard caps as JSON.
func Fees() string {
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("createFee", fees.CreateFee)
	w.IntField("primaryBps", fees.PrimaryBps)
	w.IntField("secondaryBps", fees.SecondaryBps)
	w.StrField("treasury", fees.Treasury.String())
	w.IntField("createFeeCap", CreateFeeCap)
	w.IntField("protocolFeeCapBps", ProtocolFeeCapBps)
	w.IntField("royaltyCapBps", RoyaltyCapBps)
	w.IntField("engineCapBps", fees.EngineCapBps)
	w.IntField("engineFeeCapBps", EngineFeeCapBps)
	w.EndObject()
	return w.String()
}

// PendingOps is the timelock queue as JSON.
func PendingOps() string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	ops.Iterate("", "", func(_ string, v any) bool {
		p := v.(*pendingOp)
		w.BeginObject()
		w.StrField("id", itoa(p.id))
		w.StrField("op", p.op)
		w.StrField("arg", p.arg)
		w.IntField("proposed", p.proposed)
		w.IntField("earliest", earliestExecution(p))
		w.EndObject()
		return false
	})
	w.EndArray()
	return w.String()
}

func writeCollection(w *safe.JSONWriter, c *collection) {
	h := height()
	w.BeginObject()
	w.StrField("cid", c.id)
	w.StrField("name", c.name)
	w.StrField("symbol", c.symbol)
	w.StrField("description", c.description)
	w.StrField("creator", c.creator.String())
	w.StrField("engine", c.engineID)
	w.StrField("params", c.params)
	w.StrField("minter", c.minter)
	w.StrField("state", stateAt(c, h).String())
	w.IntField("maxSupply", c.maxSupply)
	w.IntField("minted", c.minted())
	w.IntField("reserved", c.reserved)
	w.IntField("royaltyBps", c.royaltyBps)
	w.StrField("royaltyAddress", royaltyAddress(c.id).String())
	w.StrField("primaryPayees", safe.FormatPayees(c.primaryPayees))
	w.StrField("royaltyPayees", safe.FormatPayees(c.royaltyPayees))
	w.IntField("startHeight", c.startHeight)
	w.IntField("endHeight", c.endHeight)
	w.IntField("createdHeight", c.createdHeight)
	w.StrField("token", c.token.ID())
	author, bps := collectionEngineFee(c)
	w.StrField("engineAuthor", author.String())
	w.IntField("engineFeeBps", bps)
	if c.prov != nil {
		w.IntField("revealDeadline", revealDeadline(c))
		w.BoolField("useBeacon", c.useBeacon)
		w.StrField("beaconSource", c.beaconSource)
		w.StrField("badge", c.prov.badge)
		w.BoolField("fair", FairLaunch(c.id))
	}
	w.EndObject()
}

func clampLimit(limit int64) int64 {
	if limit <= 0 || limit > MaxPageSize {
		return MaxPageSize
	}
	return limit
}

// Render stays minimal in the immutable realm; the browsable gallery is the
// private, re-deployable gallery realm (design §2.5.7).
func Render(path string) string {
	gallery := strings.TrimPrefix(strings.TrimSuffix(selfPath, "/core")+"/gallery", "gno.land")
	return ufmt.Sprintf("# Collections ledger\n\n%d collections, %d engines. Browse them in the [gallery](%s).\n",
		collCount, engineCount, gallery)
}

package core

import (
	"chain"
	"chain/banker"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// Each collection's royalty receiver is its own sub-treasury
// DerivePkgSubAddr(core, "roy/<cid>"), written into the official royalty
// extension at creation. Any market can pay it through RoyaltyInfo; the
// creator can re-split it later (SetPayees) without touching the receiver.
// Only core can spend it: a banker for a sub-address needs core's live
// cur.Sub (interrealm v2 §5.5).

func royaltyAddress(cid string) address {
	return chain.DerivePkgSubAddr(selfPath, "roy/"+cid)
}

// RoyaltyAddress is the collection's royalty sub-treasury.
func RoyaltyAddress(cid string) address {
	mustCollection(cid)
	return royaltyAddress(cid)
}

// DistributeRoyalties pushes the whole sub-treasury balance to the royalty
// payees. Permissionless and never paused (I-2); market/v1 calls it after
// every sale. Returns the amount distributed. The sub-realm banker spend
// is verified by spike/subtoken, core and market tests on gno v1.7.0.
func DistributeRoyalties(cur realm, cid string) int64 {
	assertNoDeposit(cur)
	return distribute(cur, mustCollection(cid))
}

func distribute(cur realm, c *collection) int64 {
	cid := c.id
	sub := cur.Sub("roy/" + cid)
	bal := banker.NewReadonlyBanker().GetCoin(sub.Address(), "ugnot")
	if bal <= 0 {
		return 0
	}
	shares := safe.SplitByBps(bal, c.royaltyPayees)
	bk := banker.NewBanker(banker.BankerTypeRealmSend, sub)
	for i, p := range c.royaltyPayees {
		if shares[i] > 0 {
			bk.SendCoins(sub.Address(), p.Addr, chain.NewCoins(chain.NewCoin("ugnot", shares[i])))
		}
	}
	chain.Emit("RoyaltiesDistributed", "cid", cid, "amount", itoa(bal))
	return bal
}

package core

import (
	"chain"
	"encoding/base64"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/royalty/v0"
	"gno.land/p/nt/grc721/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// tokenState is the per-collection data the transfer hook needs. It is
// shared by the collection and its lockExt, so neither points at the other.
//
// Per-token state is packed (storage-cost-analysis P1+P3): one fixed-width
// entry of packEntry bytes per token, packSlots tokens per avl key. Entry =
// four big-endian uint32 fields: mint height, transfer count (H-2), height
// of the last transfer, and the token's approval nonce (SA-L3). A mint
// appends entries in tid order (a new key every packSlots tokens, ~2 KB the
// minter of that bucket's first token pays); a transfer or an Approve only
// rewrites bytes in place, so neither creates a storage object.
type tokenState struct {
	final bool
	pack  avl.Tree // safe.PadInt((tid-1)/packSlots, packKeyWidth) -> string of packed entries
}

const (
	packSlots    = 128
	packFields   = 4
	packEntry    = packFields * 4
	packKeyWidth = 3 // MaxSupplyCap/packSlots < 1000

	fieldMintHeight = 0
	fieldMoves      = 1
	fieldLastMove   = 2
	fieldNonce      = 3
)

func packKey(tid int64) string { return safe.PadInt((tid-1)/packSlots, packKeyWidth) }

// u32 encodes v as 4 big-endian bytes. Heights stay below 2^32 for ~470
// years of 3.5 s blocks; 2^32 transfers or approvals of one token cannot
// happen, so overflow is a hard error rather than a wrap.
func u32(v int64) string {
	if v < 0 || v > 0xFFFFFFFF {
		panic("token state: value out of uint32 range")
	}
	return string([]byte{byte(v >> 24), byte(v >> 16), byte(v >> 8), byte(v)})
}

// appendTokens adds zeroed entries (mint height h) for first..last, which
// must directly follow the last stored token.
func (st *tokenState) appendTokens(first, last, h int64) {
	entry := u32(h) + u32(0) + u32(0) + u32(0)
	for tid := first; tid <= last; {
		k := packKey(tid)
		v, _ := st.pack.Get(k).(string)
		if int64(len(v)) != ((tid-1)%packSlots)*packEntry {
			panic("token state: tokens must be appended in order")
		}
		for ; tid <= last && packKey(tid) == k; tid++ {
			v += entry
		}
		st.pack.Set(k, v)
	}
}

// field reads one field of token tid; 0 for a token that was never minted.
func (st *tokenState) field(tid int64, f int) int64 {
	if tid <= 0 {
		return 0
	}
	v, _ := st.pack.Get(packKey(tid)).(string)
	off := int((tid-1)%packSlots)*packEntry + f*4
	if off+4 > len(v) {
		return 0
	}
	return int64(v[off])<<24 | int64(v[off+1])<<16 | int64(v[off+2])<<8 | int64(v[off+3])
}

// setFields rewrites one or two fields of token tid in place (one avl
// update; f2 < 0 means none).
func (st *tokenState) setFields(tid int64, f1 int, v1 int64, f2 int, v2 int64) {
	k := packKey(tid)
	v, _ := st.pack.Get(k).(string)
	base := int((tid-1)%packSlots) * packEntry
	if tid <= 0 || base+packEntry > len(v) {
		panic("token state: unknown token")
	}
	o1 := base + f1*4
	v = v[:o1] + u32(v1) + v[o1+4:]
	if f2 >= 0 {
		o2 := base + f2*4
		v = v[:o2] + u32(v2) + v[o2+4:]
	}
	st.pack.Set(k, v)
}

func (st *tokenState) mintHeight(tid int64) int64 { return st.field(tid, fieldMintHeight) }

func (st *tokenState) moveOf(tid string) (moves, lastMove int64) {
	n := tidNum(tid)
	return st.field(n, fieldMoves), st.field(n, fieldLastMove)
}

// tidNum is the numeric token id, or 0 for anything that is not a
// canonical positive decimal (no such token exists).
func tidNum(tid string) int64 {
	if len(tid) == 0 || len(tid) > 12 || tid[0] == '0' {
		return 0
	}
	var n int64
	for i := 0; i < len(tid); i++ {
		c := tid[i]
		if c < '0' || c > '9' {
			return 0
		}
		n = n*10 + int64(c-'0')
	}
	return n
}

// lockExt is the grc721 Extension behind two invariants:
//
//   - I-11: before Final no token moves or burns (the reveal lock that
//     closes RA H-3's information-advantage branch). The veto is a panic,
//     which aborts the whole transaction — the documented Extension
//     semantics of p/nt/grc721/v0.
//   - H-2: every transfer bumps the token's move counter, so a market
//     listing taken at moves=N is dead after any transfer, even if the
//     token later comes back to the seller.
//
// It is declared in this realm, so the hooks write core state with core's
// authority even when another realm moves the token via RealmTeller.
type lockExt struct {
	cid string
	st  *tokenState
}

const lockKind = "art-lock"

func (e *lockExt) ExtensionKind() string { return lockKind }

// The hooks also emit the platform's per-token history events with the
// collection id ("Minted", "Transfer"); grc721's own Transfer event carries
// only the token's grc721 id.
func (e *lockExt) OnMint(to address, tid grc721.TokenID) {
	chain.Emit("Minted", "cid", e.cid, "tid", tid.String(), "to", to.String())
}

func (e *lockExt) OnTransfer(from, to address, tid grc721.TokenID) {
	if !e.st.final {
		panic("tokens are locked until the collection is final (reveal)")
	}
	key := tid.String()
	n := tidNum(key)
	e.st.setFields(n, fieldMoves, e.st.field(n, fieldMoves)+1, fieldLastMove, height())
	chain.Emit("Transfer", "cid", e.cid, "tid", key, "from", from.String(), "to", to.String())
}

func (e *lockExt) OnBurn(tid grc721.TokenID) {
	if !e.st.final {
		panic("tokens are locked until the collection is final (reveal)")
	}
	// the packed entry stays: a burned id is never minted again (I-5)
}

// --- owner actions (I-2: never paused) ---------------------------------------
//
// The acting account is always the immediate caller (cur.Previous()), the
// same rule as grc721's CallerTeller: a realm a user merely calls cannot act
// for that user. Another realm moves tokens only after an Approve, through
// Token(cid).RealmTeller (market/v1 does exactly that).

// Every Approve of a token and every SetApprovalForAll of an (owner,
// operator) pair bumps a nonce. A market pins the nonces at listing time,
// so revoking an approval kills a listing for good: approving again later
// starts a new nonce and never revives the old listing (SA-L3).
func Approve(cur realm, cid, tid string, to address) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if err := c.ledger.Approve(caller(cur), to, grc721.TokenID(tid)); err != nil {
		panic(err)
	}
	n := tidNum(tid)
	c.st.setFields(n, fieldNonce, c.st.field(n, fieldNonce)+1, -1, 0)
}

func SetApprovalForAll(cur realm, cid string, operator address, approved bool) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	owner := caller(cur)
	if err := c.ledger.SetApprovalForAll(owner, operator, approved); err != nil {
		panic(err)
	}
	bumpNonce(c, "o:"+owner.String()+":"+operator.String())
}

// ApprovalNonces returns the token's approval nonce and the (owner,
// operator) approval-for-all nonce. Approvals made directly through
// Token(cid).RealmTeller by a realm acting for itself do not bump them.
func ApprovalNonces(cid, tid string, owner, operator address) (tokenNonce, operatorNonce int64) {
	c := mustCollection(cid)
	return c.st.field(tidNum(tid), fieldNonce), nonceOf(c, "o:"+owner.String()+":"+operator.String())
}

func bumpNonce(c *collection, key string) {
	c.approvals.Set(key, nonceOf(c, key)+1)
}

func nonceOf(c *collection, key string) int64 {
	if v := c.approvals.Get(key); v != nil {
		return v.(int64)
	}
	return 0
}

func TransferFrom(cur realm, cid, tid string, from, to address) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if err := c.ledger.TransferFrom(caller(cur), from, to, grc721.TokenID(tid)); err != nil {
		panic(err)
	}
}

// Burn is owner-only. The supply gate uses nextTID, so a burn never reopens
// a slot (I-5).
func Burn(cur realm, cid, tid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	owner, err := c.token.OwnerOf(grc721.TokenID(tid))
	if err != nil {
		panic(err)
	}
	if owner != caller(cur) {
		panic("only the owner can burn a token")
	}
	if err := c.ledger.Burn(grc721.TokenID(tid)); err != nil {
		panic(err)
	}
}

// --- token reads ---------------------------------------------------------------

// Token publishes the collection's official *grc721.Token. Its exported
// methods are reads or teller factories that need the caller's live realm;
// the ledger itself is never published.
func Token(cid string) *grc721.Token { return mustCollection(cid).token }

// Royalty publishes the read-only royalty view (EIP-2981 RoyaltyInfo).
func Royalty(cid string) *royalty.Royalty { return mustCollection(cid).roy }

func OwnerOf(cid, tid string) (address, error) {
	return mustCollection(cid).token.OwnerOf(grc721.TokenID(tid))
}

func BalanceOf(cid string, owner address) (int64, error) {
	return mustCollection(cid).token.BalanceOf(owner)
}

// TokenMoves is the transfer counter market/v1 pins in a listing (H-2).
func TokenMoves(cid, tid string) int64 {
	n, _ := mustCollection(cid).st.moveOf(tid)
	return n
}

// TokenSeed is "" until the collection is Final: no read path can leak the
// rarity map early.
func TokenSeed(cid, tid string) string {
	c := mustCollection(cid)
	if !c.st.final || !exists(c, tid) {
		return ""
	}
	return safe.Seed(c.id, tid, c.prov.salt)
}

// TokenState is {mintHeight, lastMoveHeight, moves} as JSON.
func TokenState(cid, tid string) string {
	c := mustCollection(cid)
	if !exists(c, tid) {
		panic(grc721.ErrInvalidTokenId)
	}
	in := tokenInput(c, tid)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("mintHeight", in.MintHeight)
	w.IntField("lastMoveHeight", in.LastMoveHeight)
	w.IntField("moves", in.Moves)
	w.EndObject()
	return w.String()
}

// TokenURI is a base64 SVG data URI. Before Final every token shows core's
// neutral placeholder, never engine output (design §4.2).
func TokenURI(cid, tid string) (string, error) {
	c := mustCollection(cid)
	if _, err := c.token.OwnerOf(grc721.TokenID(tid)); err != nil {
		return "", err
	}
	if !c.st.final {
		return dataURI(placeholderSVG(c.name, "Unrevealed")), nil
	}
	return dataURI(renderToken(c, tid)), nil
}

// TokenTraits is [{"trait_type":…,"value":…}] JSON.
func TokenTraits(cid, tid string) string {
	c := mustCollection(cid)
	w := &safe.JSONWriter{}
	writeTraits(w, tokenTraits(c, tid))
	return w.String()
}

// TokenTraitList is the typed form of TokenTraits for other realms (a copy).
func TokenTraitList(cid, tid string) []engine.Trait {
	return append([]engine.Trait{}, tokenTraits(mustCollection(cid), tid)...)
}

// TokenMetadata is OpenSea-style metadata JSON.
func TokenMetadata(cid, tid string) string {
	c := mustCollection(cid)
	uri, err := TokenURI(cid, tid)
	if err != nil {
		panic(err)
	}
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("name", c.name+" #"+tid)
	w.StrField("description", c.description)
	w.StrField("image", uri)
	w.Key("attributes")
	writeTraits(w, tokenTraits(c, tid))
	w.EndObject()
	return w.String()
}

func exists(c *collection, tid string) bool {
	_, err := c.token.OwnerOf(grc721.TokenID(tid))
	return err == nil
}

func tokenInput(c *collection, tid string) engine.Input {
	n := safe.ParseID("tid", tid)
	moves, lastMove := c.st.moveOf(tid)
	mh := c.st.mintHeight(n)
	if lastMove == 0 {
		lastMove = mh
	}
	in := engine.Input{
		Params:         c.params,
		CollectionID:   c.id,
		TokenID:        tid,
		MintHeight:     mh,
		LastMoveHeight: lastMove,
		Moves:          moves,
		Height:         height(),
	}
	if c.st.final {
		in.Seed = safe.Seed(c.id, tid, c.prov.salt)
	}
	return in
}

// renderToken runs the collection's engine on a read path. A bad output
// degrades to a placeholder; a panicking engine only fails reads of its own
// collections (interrealm v2 §9: cross-realm panics abort the query).
func renderToken(c *collection, tid string) string {
	rec := mustEngine(c.engineID)
	svg := rec.impl.Render(tokenInput(c, tid))
	if err := engine.CheckSVG(rec.manifest, svg); err != nil {
		return placeholderSVG(c.name, "Engine output rejected")
	}
	return svg
}

func tokenTraits(c *collection, tid string) []engine.Trait {
	if !exists(c, tid) {
		panic(grc721.ErrInvalidTokenId)
	}
	if !c.st.final {
		return []engine.Trait{{Type: "Status", Value: "Unrevealed"}}
	}
	rec := mustEngine(c.engineID)
	ts := rec.impl.Traits(tokenInput(c, tid))
	if err := engine.ValidateTraits(rec.manifest, ts); err != nil {
		return []engine.Trait{{Type: "Status", Value: "Engine output rejected"}}
	}
	return ts
}

func writeTraits(w *safe.JSONWriter, ts []engine.Trait) {
	w.BeginArray()
	for _, t := range ts {
		w.BeginObject()
		w.StrField("trait_type", t.Type)
		w.StrField("value", t.Value)
		w.EndObject()
	}
	w.EndArray()
}

// placeholderSVG is core's own neutral art: identical for every token of a
// collection, so it carries no rarity signal.
func placeholderSVG(name, label string) string {
	return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">` +
		`<rect width="512" height="512" fill="#111"/>` +
		`<text x="256" y="236" fill="#ddd" font-family="monospace" font-size="24" text-anchor="middle">` +
		safe.XMLEscape(name) + `</text>` +
		`<text x="256" y="286" fill="#888" font-family="monospace" font-size="18" text-anchor="middle">` +
		safe.XMLEscape(label) + `</text></svg>`
}

func dataURI(svg string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg))
}

// emitBatch announces one MintTo ("MintBatch") or ReserveTo ("Reserved")
// call; each token also gets its own "Minted" event from lockExt.
func emitBatch(kind string, c *collection, to address, first, last int64) {
	chain.Emit(kind, "cid", c.id, "to", to.String(), "first", itoa(first), "last", itoa(last))
}

// Package genesis is the thin adapter that registers the genesis engine
// (p/…/art/art/genesis/v1) with core. It dogfoods the third-party path: core
// knows genesis only as this realm's package path plus an interface value.
//
// The adapter is stateless and has no admin: what it renders is fixed by
// the p/ package it imports, which can never change. Never mark this realm
// private (design §5.4: a re-deployable adapter could swap the art).
package genesis

import (
	art "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/art/genesis/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia2/core"
)

// author is the address that claims the engine in core (ClaimEngine).
// TODO(mainnet): the platform's engine-author key, not the deployer.
var author = address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06")

func Author() address { return author }

// AuthorFeeBps is the genesis author's fee on sales of collections by other
// creators (engine.Manifest.FeeBps; 0 for the author's own collections).
// TODO(mainnet): product decision; 1% here so Onyx exercises the path.
const AuthorFeeBps = 100

// impl is zero-size and declared here, so core runs it with this realm's
// authority (interrealm v2 borrow rule #1).
type impl struct{}

func (impl) Manifest() engine.Manifest {
	m := art.Manifest()
	m.Author = author
	m.FeeBps = AuthorFeeBps
	return m
}

func (impl) ValidateParams(params string) error { return art.ValidateParams(params) }

func (impl) Traits(in engine.Input) []engine.Trait { return art.Traits(in) }

func (impl) Render(in engine.Input) string { return art.Render(in) }

// Register is an explicit call, not init: under the inert package policy
// init runs inside the approver's transaction (RA B-1). Anyone may call it;
// it can only ever register this realm, once.
func Register(cur realm) string {
	return core.RegisterEngine(cross(cur), impl{})
}

// RenderSeed and TraitsSeed are the plan-B surface (design §5.6): if
// dynamic registration fails on chain, readers call the engine directly.
func RenderSeed(seed, params string) string {
	if err := art.ValidateParams(params); err != nil {
		panic(err)
	}
	return art.SVG(seed)
}

func TraitsSeed(seed, params string) []engine.Trait {
	in := engine.SampleInput()
	in.Seed, in.Params = seed, params
	if err := art.ValidateParams(params); err != nil {
		panic(err)
	}
	return art.Traits(in)
}

package mint

import (
	"strings"

	"gno.land/r/sys/users"
	validators "gno.land/r/sys/validators/v2"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia2/core"
)

// Allowlist sets (design §4.6). A phase's set is a comma-separated
// union of terms; an address is eligible if any term admits it:
//
//	users             registered in r/sys/users (live check)
//	validators        in the active validator set (live check)
//	holders:<cid>     holds a token of collection <cid>
//	merkle:<root>     in a sha256 merkle tree; the minter passes the proof
//
// A term may carry "|"-separated provenance notes for humans, e.g.
// "merkle:<root>|src:<git-sha>|data:<sha256>"; notes never affect logic.
const (
	MaxSetLen   = 512
	MaxSetTerms = 4
)

type setTerm struct {
	name, arg string
}

// parseSet validates a set and returns its terms; it panics on any error so
// AddPhase rejects a malformed set before it is ever frozen.
func parseSet(set string) []setTerm {
	safe.AssertText("set", set, MaxSetLen)
	parts := strings.Split(set, ",")
	if len(parts) > MaxSetTerms {
		panic("set: at most 4 terms")
	}
	terms := make([]setTerm, 0, len(parts))
	for _, part := range parts {
		body, _, _ := strings.Cut(part, "|")
		name, arg, _ := strings.Cut(body, ":")
		switch name {
		case "users", "validators":
			if arg != "" {
				panic("set: " + name + " takes no argument")
			}
		case "holders":
			core.Info(arg) // panics for an unknown collection
		case "merkle":
			arg = safe.AssertHex("set merkle root", arg, 32)
		default:
			panic("set: unknown term " + name)
		}
		terms = append(terms, setTerm{name: name, arg: arg})
	}
	return terms
}

// eligible reports whether addr may mint in a phase with this set, and why
// not. Live sets are evaluated at mint time, so a deleted user or a removed
// validator loses eligibility immediately.
func eligible(cid, set string, addr address, proof string) (bool, string) {
	if set == "" {
		return true, ""
	}
	for _, t := range parseSet(set) {
		switch t.name {
		case "users":
			if users.ResolveAddress(addr) != nil {
				return true, ""
			}
		case "validators":
			if validators.IsValidator(addr) {
				return true, ""
			}
		case "holders":
			if n, err := core.BalanceOf(t.arg, addr); err == nil && n > 0 {
				return true, ""
			}
		case "merkle":
			// an empty proof is valid for a one-address tree (root == leaf, SA-L4)
			if safe.MerkleVerify(t.arg, safe.AllowlistLeaf(cid, addr), proof) {
				return true, ""
			}
		}
	}
	return false, "address is not in this phase's allowlist (" + set + ")"
}

// Package mint is the platform's first minter (design §2.5.3): sale
// phases, fixed price or Dutch auction, live and merkle allowlists, lifetime
// wallet caps, and payment settlement. It is replaceable: core binds each
// collection to the minter that created it, so a future mint/v2 serves new
// collections without touching sales in progress.
//
// Creator flow (one multi-message transaction from the frontend; safety does
// not depend on atomicity because nobody can mint a Draft):
//
//	Create -> AddPhase x1..3 -> Launch
//
// Collector flow: Mint, with Price / Phases / Eligible as the read side.
package mint

import (
	"chain"
	"chain/runtime"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia2/core"
)

const MaxPhases = 3

// sale is this minter's per-collection state. Phases can change only while
// core says Draft; after Launch they are frozen with the rest (I-6).
type sale struct {
	phases []types.Phase
}

var sales avl.Tree // cid -> *sale

// Create opens a Draft collection for the calling wallet and pays the
// protocol's create fee from the attached ugnot (excess refunded).
// Empty payee strings default to "creator:10000". expectedCID, when set,
// makes the transaction fail instead of creating a different id than the
// frontend showed (OA B2).
func Create(cur realm, name, symbol, description, engineID, params string,
	maxSupply, royaltyBps int64, primaryPayees, royaltyPayees, expectedCID string,
) string {
	paid := received(cur)
	creator := cur.Previous().Address()
	fee := core.FeeConfig()
	if paid < fee.CreateFee {
		panic("create fee is " + itoa(fee.CreateFee) + "ugnot, sent " + itoa(paid))
	}
	self := creator.String() + ":10000"
	if primaryPayees == "" {
		primaryPayees = self
	}
	if royaltyPayees == "" {
		royaltyPayees = self
	}

	cid := core.CreateCollection(cross(cur), creator, types.CollectionSpec{
		Name: name, Symbol: symbol, Description: description,
		EngineID: engineID, Params: params,
		MaxSupply: maxSupply, RoyaltyBps: royaltyBps,
		PrimaryPayees: primaryPayees, RoyaltyPayees: royaltyPayees,
	})
	if expectedCID != "" && cid != expectedCID {
		panic("collection id would be " + cid + ", expected " + expectedCID + "; retry")
	}
	sales.Set(cid, &sale{})

	pay(cur, fee.Treasury, fee.CreateFee)
	pay(cur, creator, paid-fee.CreateFee)
	return cid
}

// AddPhase appends a sale phase. Phases are ordered and do not overlap.
// kind is "allow" (set required) or "public" (set empty); a fixed price has
// startPrice == floorPrice and zero steps; walletCap 0 means no cap.
func AddPhase(cur realm, cid, kind, set string,
	startHeight, endHeight, startPrice, floorPrice, stepBlocks, stepAmount, walletCap int64,
) {
	assertNoDeposit(cur)
	s := mustDraftSale(cur, cid)
	if len(s.phases) >= MaxPhases {
		panic("at most " + itoa(MaxPhases) + " phases")
	}
	p := types.Phase{
		Kind: kind, Set: set,
		StartHeight: startHeight, EndHeight: endHeight,
		StartPrice: startPrice, FloorPrice: floorPrice,
		StepBlocks: stepBlocks, StepAmount: stepAmount,
		WalletCap: walletCap,
	}
	if err := p.Validate(); err != nil {
		panic(err)
	}
	if set != "" {
		parseSet(set)
	}
	if n := len(s.phases); n > 0 && p.StartHeight <= s.phases[n-1].EndHeight {
		panic("phases must not overlap: start after height " + itoa(s.phases[n-1].EndHeight))
	}
	s.phases = append(s.phases, p)
	chain.Emit("PhaseAdded", "cid", cid, "index", itoa(int64(len(s.phases)-1)), "kind", kind, "set", set)
}

// ClearPhases removes every phase of a Draft.
func ClearPhases(cur realm, cid string) {
	assertNoDeposit(cur)
	s := mustDraftSale(cur, cid)
	s.phases = nil
	chain.Emit("PhasesCleared", "cid", cid)
}

// Launch freezes the sale. creatorCommit is safe.Commit(chainID, cid,
// "creator", secret), computed off-chain — never send the secret to a node
// before reveal. beaconSource (with useBeacon) is "" / "committed" for the
// platform beacon or an approved randomness provider's package path
// (core.RandomnessProviders). The engine-author fee is snapshotted here.
func Launch(cur realm, cid, creatorCommit string, revealWindow int64, useBeacon bool, beaconSource string) {
	assertNoDeposit(cur)
	s := mustDraftSale(cur, cid)
	if len(s.phases) == 0 {
		panic("add at least one phase before launching")
	}
	core.Launch(cross(cur), cid, types.LaunchSpec{
		StartHeight:   s.phases[0].StartHeight,
		EndHeight:     s.phases[len(s.phases)-1].EndHeight,
		RevealWindow:  revealWindow,
		CreatorCommit: creatorCommit,
		UseBeacon:     useBeacon,
		BeaconSource:  beaconSource,
	})
}

// Abort returns a launched collection with no mints to Draft (core rules).
func Abort(cur realm, cid string) {
	assertNoDeposit(cur)
	assertCreator(cur, cid)
	core.AbortLaunch(cross(cur), cid)
}

// Reserve mints the creator's reserve to the creator before the sale.
func Reserve(cur realm, cid string, count int64) string {
	assertNoDeposit(cur)
	creator := assertCreator(cur, cid)
	first, last := core.ReserveTo(cross(cur), cid, creator, count)
	return itoa(first) + "-" + itoa(last)
}

// Mint buys count tokens in the phase open at this block, at that block's
// unit price, never above maxUnitPrice (a Dutch step cannot surprise the
// buyer). proof is the merkle proof for merkle sets, otherwise "". Returns
// "first-last". Every attached unit is paid out or refunded (I-3, I-4).
func Mint(cur realm, cid string, count, maxUnitPrice int64, proof string) string {
	paid := received(cur)
	buyer := cur.Previous().Address()
	h := runtime.ChainHeight()
	p, ok := mustSale(cid).phaseAt(h)
	if !ok {
		panic("no sale phase is open at height " + itoa(h))
	}
	if count <= 0 || count > core.MaxMintPerTx {
		panic("count must be 1.." + itoa(core.MaxMintPerTx))
	}
	if ok, reason := eligible(cid, p.Set, buyer, proof); !ok {
		panic(reason)
	}
	if p.WalletCap > 0 && core.MintedBy(cid, buyer)+count > p.WalletCap {
		panic("wallet cap: " + itoa(p.WalletCap) + " per wallet, already minted " + itoa(core.MintedBy(cid, buyer)))
	}
	price := p.PriceAt(h)
	if price > maxUnitPrice {
		panic("unit price at this block is " + itoa(price) + "ugnot, above maxUnitPrice " + itoa(maxUnitPrice))
	}
	cost := price * count
	if paid < cost {
		panic("send " + itoa(cost) + "ugnot, sent " + itoa(paid))
	}

	first, last := core.MintTo(cross(cur), cid, buyer, count)

	fee := core.FeeConfig()
	sp := split(cid, cost)
	pay(cur, fee.Treasury, sp.protocol)
	pay(cur, sp.engineAuthor, sp.engine)
	for i, payee := range sp.payees {
		pay(cur, payee.Addr, sp.shares[i])
	}
	pay(cur, buyer, paid-cost)

	chain.Emit("Sale", "cid", cid, "buyer", buyer.String(), "first", itoa(first), "last", itoa(last),
		"unitPrice", itoa(price), "protocolFee", itoa(sp.protocol), "engineFee", itoa(sp.engine),
		"engineAuthor", sp.engineAuthor.String())
	return itoa(first) + "-" + itoa(last)
}

// primarySplit is how a primary sale of `amount` is paid (I-4: protocol +
// engine + sum(shares) == amount): the protocol fee frozen at Launch
// (SA-I5), the engine author's fee (snapshot at Launch, 0 when the creator
// is the author), the rest split over the frozen primary payees.
type primarySplit struct {
	protocol, engine int64
	engineAuthor     address
	payees           []types.Payee
	shares           []int64
}

func split(cid string, amount int64) primarySplit {
	sp := primarySplit{protocol: safe.BpsOf(amount, core.PrimaryFeeBps(cid))}
	author, bps := core.EngineFee(cid)
	sp.engineAuthor, sp.engine = author, safe.BpsOf(amount, bps)
	sp.payees = core.PrimaryPayees(cid)
	sp.shares = safe.SplitByBps(amount-sp.protocol-sp.engine, sp.payees)
	return sp
}

func (s *sale) phaseAt(h int64) (types.Phase, bool) {
	for _, p := range s.phases {
		if p.Covers(h) {
			return p, true
		}
	}
	return types.Phase{}, false
}

func mustSale(cid string) *sale {
	v := sales.Get(cid)
	if v == nil {
		panic("collection " + cid + " was not created by this minter")
	}
	return v.(*sale)
}

func mustDraftSale(cur realm, cid string) *sale {
	assertCreator(cur, cid)
	if core.Info(cid).State != types.StateDraft {
		panic("phases are frozen after launch")
	}
	return mustSale(cid)
}

func assertCreator(cur realm, cid string) address {
	who := cur.Previous().Address()
	if core.Info(cid).Creator != who {
		panic("only the collection's creator can do this")
	}
	return who
}

// --- reads -------------------------------------------------------------------

// Price is the unit price at height h, or -1 when no phase covers h.
func Price(cid string, h int64) int64 {
	p, ok := mustSale(cid).phaseAt(h)
	if !ok {
		return -1
	}
	return p.PriceAt(h)
}

// Phases is the phase list as JSON.
func Phases(cid string) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	for _, p := range mustSale(cid).phases {
		w.BeginObject()
		w.StrField("kind", p.Kind)
		w.StrField("set", p.Set)
		w.IntField("startHeight", p.StartHeight)
		w.IntField("endHeight", p.EndHeight)
		w.IntField("startPrice", p.StartPrice)
		w.IntField("floorPrice", p.FloorPrice)
		w.IntField("stepBlocks", p.StepBlocks)
		w.IntField("stepAmount", p.StepAmount)
		w.IntField("walletCap", p.WalletCap)
		w.EndObject()
	}
	w.EndArray()
	return w.String()
}

// Eligible answers "can addr mint now, and how many?" with the same checks
// Mint runs, so the UI never disagrees with the chain (OA B3). JSON:
// {phase, kind, eligible, reason, remainingCap (-1 = no cap), price}.
func Eligible(cid string, addr address, proof string) string {
	h := runtime.ChainHeight()
	w := &safe.JSONWriter{}
	w.BeginObject()
	idx, p := -1, types.Phase{}
	for i, q := range mustSale(cid).phases {
		if q.Covers(h) {
			idx, p = i, q
			break
		}
	}
	w.IntField("phase", int64(idx))
	if idx < 0 {
		w.BoolField("eligible", false)
		w.StrField("reason", "no sale phase is open at height "+itoa(h))
		w.EndObject()
		return w.String()
	}
	ok, reason := eligible(cid, p.Set, addr, proof)
	remaining := int64(-1)
	if p.WalletCap > 0 {
		minted := core.MintedBy(cid, addr) // -1 once Final: nothing left to mint anyway
		if minted < 0 {
			minted = p.WalletCap
		}
		remaining = p.WalletCap - minted
		if remaining < 0 {
			remaining = 0
		}
		if remaining == 0 && ok {
			ok, reason = false, "wallet cap reached"
		}
	}
	if ok && core.Info(cid).State != types.StateMinting {
		ok, reason = false, "collection is not minting"
	}
	w.StrField("kind", p.Kind)
	w.BoolField("eligible", ok)
	w.StrField("reason", reason)
	w.IntField("remainingCap", remaining)
	w.IntField("price", p.PriceAt(h))
	w.EndObject()
	return w.String()
}

// Quote is what Mint(cid, count, …) pays at height h, as JSON: {count,
// unitPrice, cost, protocolFee, protocolBps, engineFee, engineBps,
// engineAuthor, payees:[{address, amount}]}; unitPrice -1 outside phases.
func Quote(cid string, count, h int64) string {
	price := Price(cid, h)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("count", count)
	w.IntField("unitPrice", price)
	if price < 0 || count <= 0 || count > core.MaxMintPerTx {
		w.EndObject()
		return w.String()
	}
	cost := price * count
	sp := split(cid, cost)
	_, bps := core.EngineFee(cid)
	w.IntField("cost", cost)
	w.IntField("protocolFee", sp.protocol)
	w.IntField("protocolBps", core.PrimaryFeeBps(cid))
	w.IntField("engineFee", sp.engine)
	w.IntField("engineBps", bps)
	w.StrField("engineAuthor", sp.engineAuthor.String())
	w.Key("payees")
	w.BeginArray()
	for i, p := range sp.payees {
		w.BeginObject()
		w.StrField("address", p.Addr.String())
		w.IntField("amount", sp.shares[i])
		w.EndObject()
	}
	w.EndArray()
	w.EndObject()
	return w.String()
}

func Render(path string) string {
	if path == "" {
		return "# mint/v1\n\nSale phases of the platform's collections. Use `:<cid>` for one collection.\n"
	}
	s := mustSale(path) // only known collection ids get this far
	out := "# Sale of collection " + path + "\n\n"
	for i, p := range s.phases {
		out += ufmt.Sprintf("%d. %s phase, heights %d-%d, price %d -> %d ugnot, wallet cap %d\n",
			i+1, p.Kind, p.StartHeight, p.EndHeight, p.StartPrice, p.FloorPrice, p.WalletCap)
	}
	return out
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package mint

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// I-3: this realm holds no balance. Each paying function receives the
// attached ugnot and pushes every unit out before returning: protocol fee,
// creator payees, and the refund. Nothing is ever kept for later.

// received returns the ugnot attached to a direct wallet call. Payments are
// accepted only when a wallet called us: the origin-send envelope is shared
// by every realm on the path, so a realm in between could have consumed it
// (chain/runtime/unsafe.OriginSend).
func received(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payments must come directly from a wallet, not through another realm")
	}
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != "ugnot" && c.Amount != 0 {
			panic("only ugnot is accepted")
		}
	}
	return sent.AmountOf("ugnot")
}

// assertNoDeposit refuses coins on functions that take none (RA L-1).
func assertNoDeposit(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func pay(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if to == cur.Address() {
		panic("refusing to pay the minter itself: the coins would be stranded (SA-L5)")
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// Package market is the platform's immutable fixed-price market
// (design §2.5.4). It never holds a token: the seller approves this
// realm in core, the token stays in the seller's wallet, and Buy moves it
// through core's official grc721 RealmTeller in the same transaction that
// pays everyone. It never holds coins either (I-3).
//
// A token has at most one listing, addressed by (cid, tid). Stale listings
// (RA H-2) cannot be bought: a listing pins the token's move counter and
// core's approval nonces at listing time, and Buy requires owner == seller,
// the counter unchanged and the approval it was listed under still in
// place, unchanged (I-8). Once stale, a listing stays dead: approving the
// market again later never revives it (SA-L3). A stale listing never blocks
// the new owner: List overwrites it and anyone may CancelStale it.
//
// Storage (storage-cost-analysis M1-M3): a listing is one packed string in
// `listings` (key cid:tid) plus one key in the price index `byCollection`
// (floor, collection pages). Per-seller history comes from the indexer
// ("Listed"/"Cancelled" events), not from an on-chain index.
//
// Deposit return: gno refunds a freed storage deposit to the signer of the
// transaction that frees it, so a Buy hands the buyer the deposit the
// seller locked for the listing. Buy therefore charges the buyer that
// amount on top of the price and pays it to the seller (ListingDeposit,
// measured). It is exact up to a few bytes because every listing costs the
// same storage objects: a sentinel key keeps both trees non-empty (an avl
// insert into an empty tree creates one node, any later insert two). Net,
// the seller is whole and the buyer pays the price (the chain's refund
// cancels the extra). Not compensated: the deposit of a per-token Approve,
// which the sale's transfer clears (~0.1-0.2 GNOT to the buyer, depending
// on the collection's other pending approvals); an approval-for-all is not
// cleared, so listing under SetApprovalForAll leaves nothing behind.
//
// Pause ("trade" in core) stops List and Buy only. Cancel, CancelStale and
// UpdatePrice are never paused (I-2).
package market

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia2/core"
)

const (
	MaxPageSize = 50
	priceWidth  = 16 // types.MaxUnitPrice has 16 digits

	// Deposit-return estimate (ugnot), from the bytes measured in this
	// package's z_bytes_* filetests at gno.land's storage price of 100
	// ugnot/byte (vm param storage_price on Onyx and gnoland-1). Re-measure
	// before a deploy to a chain with another price.
	StoragePrice   = 100
	ListingBytes   = 4_070 // one listing: a listings key + a byCollection key, two avl nodes each (measured 4,049-4,101 locked, 4,032-4,091 freed)
	ListingDeposit = ListingBytes * StoragePrice

	// sentinel is a key of both trees that is never a listing (it sorts
	// after every "cid:" prefix range), so neither tree is ever empty.
	sentinel = "~"
)

// listing is the decoded form of one packed `listings` value.
type listing struct {
	cid, tid string
	id       int64
	seller   address
	price    int64
	moves    int64 // core.TokenMoves at listing time
	height   int64
	feeBps   int64 // protocol fee at listing time; a sale never pays more (SA-I5)
	engBps   int64 // engine-author fee at listing time; a sale never pays more
	deposit  int64 // deposit return the buyer pays the seller (ListingDeposit, not stored)
	// approval the listing was made under (SA-L3): per-token and/or
	// approval-for-all, each pinned to core's nonce at listing time
	viaToken, viaAll          bool
	tokenNonce, operatorNonce int64
}

var (
	listings     avl.Tree // cid:tid -> packed listing (encode)
	byCollection avl.Tree // cid:paddedPrice:tid -> "" (floor = first key)
	nextID       int64
	selfPath     string // captured in init for read paths without a cur
)

func init(cur realm) {
	selfPath = cur.PkgPath()
	listings.Set(sentinel, "")
	byCollection.Set(sentinel, "")
}

// List offers a token of a Final collection at price (ugnot). The caller
// must own it and have approved this realm (Approve or SetApprovalForAll in
// core). A stale listing of the same token is replaced. Returns the
// listing's sequence id (events); the listing itself is addressed by
// (cid, tid).
func List(cur realm, cid, tid string, price int64) string {
	assertNoDeposit(cur)
	assertTradeOpen()
	assertPrice(price)
	seller := cur.Previous().Address()
	if core.Info(cid).State != types.StateFinal {
		panic("tokens of this collection are locked until it is final")
	}
	owner, err := core.OwnerOf(cid, tid)
	if err != nil {
		panic(err)
	}
	if owner != seller {
		panic("only the token owner can list it")
	}
	viaToken, viaAll := approvals(cid, tid, owner, cur.Address())
	if !viaToken && !viaAll {
		panic("approve the market for this token first: core.Approve(cid, tid, " + cur.Address().String() + ")")
	}
	if old, ok := lookup(cid, tid); ok {
		if live(old, cur.Address()) {
			panic("token is already listed as #" + itoa(old.id) + "; use UpdatePrice")
		}
		remove(old, "stale")
	}

	nextID++
	tn, on := core.ApprovalNonces(cid, tid, owner, cur.Address())
	_, engBps := core.EngineFee(cid)
	l := &listing{
		cid: cid, tid: tid, id: nextID, seller: seller, price: price,
		moves: core.TokenMoves(cid, tid), height: runtime.ChainHeight(),
		feeBps: core.FeeConfig().SecondaryBps, engBps: engBps,
		viaToken: viaToken, viaAll: viaAll, tokenNonce: tn, operatorNonce: on,
	}
	l.deposit = ListingDeposit
	store(l)
	chain.Emit("Listed", "id", itoa(l.id), "cid", cid, "tid", tid, "seller", seller.String(), "price", itoa(price),
		"deposit", itoa(l.deposit))
	return itoa(l.id)
}

// UpdatePrice changes the price of a live listing; Buy's expectedPrice
// protects buyers from a change racing their purchase (RA M-10).
func UpdatePrice(cur realm, cid, tid string, price int64) {
	assertNoDeposit(cur)
	assertPrice(price)
	l := mustListing(cid, tid)
	assertSeller(cur, l)
	if !live(l, cur.Address()) {
		panic("listing is stale; cancel it and list again")
	}
	byCollection.Remove(collectionKey(l))
	l.price = price
	store(l)
	chain.Emit("PriceUpdated", "id", itoa(l.id), "cid", l.cid, "tid", l.tid, "price", itoa(price))
}

// Cancel removes the caller's listing (its storage deposit returns to the
// caller). Never paused.
func Cancel(cur realm, cid, tid string) {
	assertNoDeposit(cur)
	l := mustListing(cid, tid)
	assertSeller(cur, l)
	remove(l, "cancelled")
}

// CancelStale lets anyone remove a listing that can no longer be bought;
// the freed deposit goes to the caller (gno's rule), a cleanup bounty.
func CancelStale(cur realm, cid, tid string) {
	assertNoDeposit(cur)
	l := mustListing(cid, tid)
	if live(l, cur.Address()) {
		panic("listing is still valid")
	}
	remove(l, "stale")
}

// Buy pays exactly expectedPrice for the token's listing, plus the
// listing's deposit return (see the package doc); excess attached ugnot is
// refunded. Order: checks, remove the listing, move the token, then pay —
// protocol fee to the treasury, royalty to the collection's sub-treasury
// (then distributed to its payees), the engine author's fee, the rest plus
// the deposit return to the seller. I-4: protocol + royalty + engine +
// seller + refund == attached.
func Buy(cur realm, cid, tid string, expectedPrice int64) {
	paid := received(cur)
	assertTradeOpen()
	buyer := cur.Previous().Address()
	l := mustListing(cid, tid)
	if l.price != expectedPrice {
		panic("price is " + itoa(l.price) + "ugnot, expected " + itoa(expectedPrice))
	}
	if paid < l.price+l.deposit {
		panic("send " + itoa(l.price+l.deposit) + "ugnot (price " + itoa(l.price) + " + deposit return " +
			itoa(l.deposit) + "), sent " + itoa(paid))
	}
	if buyer == l.seller {
		panic("cannot buy your own listing")
	}
	if !live(l, cur.Address()) {
		panic("listing is stale: the token moved or approval was revoked since it was listed")
	}
	remove(l, "sold")

	tok := core.Token(l.cid)
	if err := tok.RealmTeller(0, cur).TransferFrom(0, cur, l.seller, buyer, grc721.TokenID(l.tid)); err != nil {
		panic(err)
	}

	s := settle(l)
	pay(cur, s.treasury, s.protocol)
	pay(cur, s.royaltyTo, s.royalty)
	pay(cur, s.engineAuthor, s.engine)
	pay(cur, l.seller, s.seller)
	pay(cur, buyer, paid-l.price-l.deposit)
	if s.royalty > 0 {
		core.DistributeRoyalties(cross(cur), l.cid)
	}
	chain.Emit("Bought", "id", itoa(l.id), "cid", l.cid, "tid", l.tid,
		"seller", l.seller.String(), "buyer", buyer.String(), "price", itoa(l.price),
		"protocolFee", itoa(s.protocol), "royalty", itoa(s.royalty), "engineFee", itoa(s.engine),
		"engineAuthor", s.engineAuthor.String(), "deposit", itoa(l.deposit))
}

// settlement is how a sale of l is paid now (I-4: protocol + royalty +
// engine + seller == price + deposit).
type settlement struct {
	treasury, royaltyTo, engineAuthor address
	protocol, royalty, engine, seller int64
}

func settle(l *listing) settlement {
	fee := core.FeeConfig()
	feeBps := fee.SecondaryBps
	if l.feeBps < feeBps {
		feeBps = l.feeBps
	}
	author, engBps := core.EngineFee(l.cid)
	if l.engBps < engBps {
		engBps = l.engBps
	}
	s := settlement{treasury: fee.Treasury, engineAuthor: author}
	s.protocol = safe.BpsOf(l.price, feeBps)
	s.engine = safe.BpsOf(l.price, engBps)
	royaltyTo, royalty, err := core.Royalty(l.cid).RoyaltyInfo(grc721.TokenID(l.tid), l.price)
	if err != nil {
		panic(err)
	}
	s.royaltyTo, s.royalty = royaltyTo, royalty
	s.seller = l.price - s.protocol - s.royalty - s.engine + l.deposit
	return s
}

// --- reads ---------------------------------------------------------------------

// Listing is the token's listing as JSON, stale ones included with
// "live":false, or "null".
func Listing(cid, tid string) string {
	l, ok := lookup(cid, tid)
	if !ok {
		return "null"
	}
	w := &safe.JSONWriter{}
	writeListingLive(w, l, live(l, selfAddress()))
	return w.String()
}

// ListingOf is the live listing of a token as JSON, or "null".
func ListingOf(cid, tid string) string {
	l, ok := lookup(cid, tid)
	if !ok || !live(l, selfAddress()) {
		return "null"
	}
	w := &safe.JSONWriter{}
	writeListingLive(w, l, true)
	return w.String()
}

// ActiveListing is the typed read for other realms: the live listing of a
// token, if any (id is the sequence id).
func ActiveListing(cid, tid string) (id string, price int64, ok bool) {
	l, found := lookup(cid, tid)
	if !found || !live(l, selfAddress()) {
		return "", 0, false
	}
	return itoa(l.id), l.price, true
}

// Quote is what Buy(cid, tid, price) costs and pays now, as JSON: {live,
// id, seller, price, deposit, total (attach this), protocolFee, royalty,
// royaltyTo, engineFee, engineAuthor, sellerProceeds}; "null" if unlisted.
func Quote(cid, tid string) string {
	l, ok := lookup(cid, tid)
	if !ok {
		return "null"
	}
	s := settle(l)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.BoolField("live", live(l, selfAddress()))
	w.StrField("id", itoa(l.id))
	w.StrField("seller", l.seller.String())
	w.IntField("price", l.price)
	w.IntField("deposit", l.deposit)
	w.IntField("total", l.price+l.deposit)
	w.IntField("protocolFee", s.protocol)
	w.IntField("royalty", s.royalty)
	w.StrField("royaltyTo", s.royaltyTo.String())
	w.IntField("engineFee", s.engine)
	w.StrField("engineAuthor", s.engineAuthor.String())
	w.IntField("sellerProceeds", s.seller)
	w.EndObject()
	return w.String()
}

// ListingsByCollection lists by ascending price. Stale listings are
// included with "live":false so pages stay stable; frontends hide them.
// Listings by seller: use the indexer (Listed / Cancelled events).
func ListingsByCollection(cid string, offset, limit int64) string {
	if limit <= 0 || limit > MaxPageSize {
		limit = MaxPageSize
	}
	prefix := cid + ":"
	self := selfAddress()
	w := &safe.JSONWriter{}
	w.BeginArray()
	var skipped, written int64
	byCollection.Iterate(prefix, prefixEnd(prefix), func(k string, _ any) bool {
		if skipped < offset {
			skipped++
			return false
		}
		l := mustListing(cid, tidOfKey(k))
		writeListingLive(w, l, live(l, self))
		written++
		return written >= limit
	})
	w.EndArray()
	return w.String()
}

// Floor is the lowest live price in cid, or -1. It inspects at most
// MaxPageSize listings from the cheapest, so spam cannot make it unbounded.
func Floor(cid string) int64 {
	floor := int64(-1)
	seen := 0
	prefix := cid + ":"
	self := selfAddress()
	byCollection.Iterate(prefix, prefixEnd(prefix), func(k string, _ any) bool {
		seen++
		l := mustListing(cid, tidOfKey(k))
		if live(l, self) {
			floor = l.price
			return true
		}
		return seen >= MaxPageSize
	})
	return floor
}

func Render(path string) string {
	return "# market/v1\n\n" + itoa(int64(listings.Size()-1)) + " open listings. " +
		"Read them with `ListingsByCollection` or browse the gallery.\n"
}

// --- internals -------------------------------------------------------------------

// live: still owned by the seller, not moved since listing, and the
// approval it was listed under is still in place and untouched since: a
// per-token listing dies with any later Approve of that token, an
// approval-for-all listing with any later SetApprovalForAll of the market
// by the seller — even one that approves again (SA-L3).
func live(l *listing, market address) bool {
	owner, err := core.OwnerOf(l.cid, l.tid)
	if err != nil || owner != l.seller || core.TokenMoves(l.cid, l.tid) != l.moves {
		return false
	}
	viaToken, viaAll := approvals(l.cid, l.tid, owner, market)
	tn, on := core.ApprovalNonces(l.cid, l.tid, owner, market)
	return (l.viaToken && viaToken && tn == l.tokenNonce) || (l.viaAll && viaAll && on == l.operatorNonce)
}

// approvals reports whether market is approved for this token, and whether
// it is approved for all of owner's tokens.
func approvals(cid, tid string, owner, market address) (viaToken, viaAll bool) {
	tok := core.Token(cid)
	a, err := tok.GetApproved(grc721.TokenID(tid))
	return err == nil && a == market, tok.IsApprovedForAll(owner, market)
}

// store writes l and its price-index key.
func store(l *listing) {
	listings.Set(tokenKey(l.cid, l.tid), encode(l))
	byCollection.Set(collectionKey(l), "")
}

// remove deletes a listing and its index key; closed listings are not kept
// (RA L-6), the "Cancelled" event (reason sold/cancelled/stale) is the record.
func remove(l *listing, reason string) {
	listings.Remove(tokenKey(l.cid, l.tid))
	byCollection.Remove(collectionKey(l))
	chain.Emit("Cancelled", "id", itoa(l.id), "cid", l.cid, "tid", l.tid, "reason", reason)
}

// encode packs a listing as one comma-separated string (M1: an inline avl
// value instead of a *listing object, ~1.3 KB less per listing):
// id,seller,price,moves,height,feeBps,engBps,flags,tokenNonce,operatorNonce
// with flags = 1 (per-token) | 2 (for-all).
func encode(l *listing) string {
	flags := int64(0)
	if l.viaToken {
		flags |= 1
	}
	if l.viaAll {
		flags |= 2
	}
	return itoa(l.id) + "," + l.seller.String() + "," + itoa(l.price) + "," + itoa(l.moves) + "," +
		itoa(l.height) + "," + itoa(l.feeBps) + "," + itoa(l.engBps) + "," +
		itoa(flags) + "," + itoa(l.tokenNonce) + "," + itoa(l.operatorNonce)
}

func decode(cid, tid, v string) *listing {
	f := strings.Split(v, ",")
	if len(f) != 10 {
		panic("market: corrupt listing " + cid + ":" + tid)
	}
	n := func(i int) int64 {
		x, err := strconv.ParseInt(f[i], 10, 64)
		if err != nil {
			panic("market: corrupt listing " + cid + ":" + tid)
		}
		return x
	}
	flags := n(7)
	return &listing{
		cid: cid, tid: tid, id: n(0), seller: address(f[1]), price: n(2), moves: n(3), height: n(4),
		feeBps: n(5), engBps: n(6), deposit: ListingDeposit, viaToken: flags&1 != 0, viaAll: flags&2 != 0,
		tokenNonce: n(8), operatorNonce: n(9),
	}
}


func lookup(cid, tid string) (*listing, bool) {
	v := listings.Get(tokenKey(cid, tid))
	if v == nil {
		return nil, false
	}
	return decode(cid, tid, v.(string)), true
}

func mustListing(cid, tid string) *listing {
	l, ok := lookup(cid, tid)
	if !ok {
		panic("token " + cid + ":" + tid + " is not listed")
	}
	return l
}

func writeListingLive(w *safe.JSONWriter, l *listing, isLive bool) {
	w.BeginObject()
	w.StrField("id", itoa(l.id))
	w.StrField("cid", l.cid)
	w.StrField("tid", l.tid)
	w.StrField("seller", l.seller.String())
	w.IntField("price", l.price)
	w.IntField("deposit", l.deposit)
	w.IntField("moves", l.moves)
	w.IntField("height", l.height)
	w.IntField("engineFeeBps", l.engBps)
	w.BoolField("live", isLive)
	w.EndObject()
}

func assertSeller(cur realm, l *listing) {
	if cur.Previous().Address() != l.seller {
		panic("only the seller can do this")
	}
}

func assertTradeOpen() {
	if core.Paused("trade") {
		panic("paused: trade")
	}
}

func assertPrice(price int64) {
	if price <= 0 || price > types.MaxUnitPrice {
		panic("price must be 1.." + itoa(types.MaxUnitPrice) + " ugnot")
	}
}

func received(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payments must come directly from a wallet, not through another realm")
	}
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != "ugnot" && c.Amount != 0 {
			panic("only ugnot is accepted")
		}
	}
	return sent.AmountOf("ugnot")
}

func assertNoDeposit(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func pay(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if to == cur.Address() {
		panic("refusing to pay the market itself: the coins would be stranded (SA-L5)")
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// tokenKey is the listing key. cid and tid are canonical ids (core
// accepted the token), so the key has one spelling per token.
func tokenKey(cid, tid string) string { return cid + ":" + tid }

// collectionKey orders a collection's listings by price; the tid is the
// part after the last ':'.
func collectionKey(l *listing) string {
	return l.cid + ":" + safe.PadInt(l.price, priceWidth) + ":" + l.tid
}

func tidOfKey(k string) string { return k[strings.LastIndex(k, ":")+1:] }

// prefixEnd is the smallest key greater than every key with this prefix
// (prefixes here end in ':', so bump it to ';').
func prefixEnd(prefix string) string {
	return prefix[:len(prefix)-1] + string(rune(prefix[len(prefix)-1]+1))
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// selfAddress is this realm's address for read paths that have no cur.
func selfAddress() address { return chain.PackageAddress(selfPath) }

// Package reader is the batch JSON read API for the frontend and the
// aggregator (design §2.5.6). It is private (re-deployable in place, no
// other realm may import it) and holds no state or money: everything comes
// from core, market and r/sys/users.
//
// Every string goes out through safe.JSONWriter, so stored text can never
// forge a record (RA H-1: the old TSV reader split on tabs and newlines).
// Art is never batched: one token per Art call, because SVG rendering is
// what exhausted the query gas in nftread1 (RA L-9).
package reader

import (
	"gno.land/r/sys/users"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia2/core"
	market "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia2/market/v1"
)

// Batch limits. Hypothesis (S-4): sized for the genesis engine under the
// public qeval gas cap; measure on Onyx and lower if a full page runs out.
const (
	MaxCards       = 50
	MaxTraitCounts = 500
	MaxStudio      = 200
)

// Cards is one gallery page: [{tid, owner, ownerName, traits, listing}] for
// tokens offset+1 … offset+limit. Burned tokens are skipped; listing is
// {id, price} or null.
func Cards(cid string, offset, limit int64) string {
	info := core.Info(cid)
	w := &safe.JSONWriter{}
	w.BeginArray()
	for _, tid := range tokenRange(info.Minted, offset, limit, MaxCards) {
		owner, err := core.OwnerOf(cid, tid)
		if err != nil {
			continue // burned
		}
		w.BeginObject()
		w.StrField("tid", tid)
		w.StrField("owner", owner.String())
		w.StrField("ownerName", nameOf(owner))
		w.Key("traits")
		writeTraits(w, core.TokenTraitList(cid, tid))
		w.Key("listing")
		if id, price, ok := market.ActiveListing(cid, tid); ok {
			w.BeginObject()
			w.StrField("id", id)
			w.IntField("price", price)
			w.EndObject()
		} else {
			w.Raw("null")
		}
		w.EndObject()
	}
	w.EndArray()
	return w.String()
}

// TraitCounts counts trait values over tokens offset+1 … offset+limit:
// {"n": tokens counted, "counts": {type: {value: count}}}. Rarity % for a
// 1000-token collection takes two calls. Before Final every token reports
// Status=Unrevealed.
func TraitCounts(cid string, offset, limit int64) string {
	info := core.Info(cid)
	c := newCounter()
	for _, tid := range tokenRange(info.Minted, offset, limit, MaxTraitCounts) {
		if _, err := core.OwnerOf(cid, tid); err != nil {
			continue
		}
		c.add(core.TokenTraitList(cid, tid))
	}
	return c.json()
}

// StudioTraits is TraitCounts for an engine and params over n sample seeds
// (engine.SampleSeed(from) …), for the Studio's rarity preview.
func StudioTraits(engineID, params string, from, n int64) string {
	if n <= 0 || n > MaxStudio {
		n = MaxStudio
	}
	if from < 0 {
		from = 0
	}
	c := newCounter()
	for i := from; i < from+n; i++ {
		c.add(core.EngineTraits(engineID, params, engine.SampleSeed(int(i))))
	}
	return c.json()
}

// Art is one token's data URI (placeholder before Final).
func Art(cid, tid string) string {
	uri, err := core.TokenURI(cid, tid)
	if err != nil {
		panic(err)
	}
	return uri
}

func Collections(offset, limit int64) string { return core.Collections(offset, limit) }

// Profile is {address, name, collections} for one address. A seller's
// listings come from the indexer (market "Listed"/"Cancelled" events):
// market/v1 keeps no per-seller index on chain (storage, M2).
func Profile(addr address) string {
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("address", addr.String())
	w.StrField("name", nameOf(addr))
	w.Key("collections")
	w.Raw(core.CollectionsByCreator(addr, 0, MaxCards))
	w.EndObject()
	return w.String()
}

// --- helpers -----------------------------------------------------------------

// nameOf is the r/sys/users name of addr, or "".
func nameOf(addr address) string {
	if u := users.ResolveAddress(addr); u != nil {
		return u.Name()
	}
	return ""
}

func tokenRange(minted, offset, limit, max int64) []string {
	if limit <= 0 || limit > max {
		limit = max
	}
	if offset < 0 {
		offset = 0
	}
	var out []string
	for n := offset + 1; n <= minted && n <= offset+limit; n++ {
		out = append(out, itoa(n))
	}
	return out
}

func writeTraits(w *safe.JSONWriter, ts []engine.Trait) {
	w.BeginArray()
	for _, t := range ts {
		w.BeginObject()
		w.StrField("trait_type", t.Type)
		w.StrField("value", t.Value)
		w.EndObject()
	}
	w.EndArray()
}

// counter keeps first-seen order so the JSON is deterministic.
type counter struct {
	n      int64
	types  []string
	values map[string][]string       // type -> values in first-seen order
	counts map[string]map[string]int64 // type -> value -> count
}

func newCounter() *counter {
	return &counter{values: map[string][]string{}, counts: map[string]map[string]int64{}}
}

func (c *counter) add(ts []engine.Trait) {
	c.n++
	for _, t := range ts {
		byValue, ok := c.counts[t.Type]
		if !ok {
			byValue = map[string]int64{}
			c.counts[t.Type] = byValue
			c.types = append(c.types, t.Type)
		}
		if _, seen := byValue[t.Value]; !seen {
			c.values[t.Type] = append(c.values[t.Type], t.Value)
		}
		byValue[t.Value]++
	}
}

func (c *counter) json() string {
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("n", c.n)
	w.Key("counts")
	w.BeginObject()
	for _, typ := range c.types {
		w.Key(typ)
		w.BeginObject()
		for _, v := range c.values[typ] {
			w.IntField(v, c.counts[typ][v])
		}
		w.EndObject()
	}
	w.EndObject()
	w.EndObject()
	return w.String()
}

func itoa(n int64) string { return safe.PadInt(n, 1) }

// Package gallery is the platform's gnoweb face (design §2.5.7): the
// product stays browsable on gno.land even without the website. It is
// private (re-deployable in place), read-only and holds nothing.
//
// Routes:
//
//	""                    latest collections
//	c/<cid>[?page=N]      one collection, 20 tokens per page
//	c/<cid>/t/<tid>       one token: art, traits, owner, listing, provenance
//	e/<engine pkgpath>    an engine's manifest and status
//	u/<name>              a registered user's collections and listings
//
// Every user-supplied string is rendered as plain text (plainText: RA M-9,
// SA-M4): no heading, link, image, HTML or autolink can come out of a name,
// description, trait or manifest field. Every list is paginated.
package gallery

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/sys/users"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia2/core"
	market "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia2/market/v1"
)

const (
	pageSize   = 20
	homeLimit  = 20
	maxPageNum = 500
)

func Render(path string) string {
	route, query, _ := strings.Cut(path, "?")
	parts := strings.Split(route, "/")
	switch {
	case route == "":
		return home()
	case len(parts) == 2 && parts[0] == "c":
		return collectionPage(parts[1], pageFrom(query))
	case len(parts) == 4 && parts[0] == "c" && parts[2] == "t":
		return tokenPage(parts[1], parts[3])
	case len(parts) > 1 && parts[0] == "e":
		return enginePage(strings.TrimPrefix(route, "e/"))
	case len(parts) == 2 && parts[0] == "u":
		return userPage(parts[1])
	}
	return "# Not found\n\n[Back to the gallery](" + base() + ")\n"
}

func home() string {
	n := core.CollectionCount()
	out := ufmt.Sprintf("# Gallery\n\n%d collections. Art is computed on chain from each collection's engine and revealed seed.\n\n", n)
	for id := n; id >= 1 && id > n-homeLimit; id-- {
		info := core.Info(itoa(id))
		out += ufmt.Sprintf("- [%s](%s) — %s, %d/%d minted\n",
			plainText(info.Name), link("c/"+info.ID), info.State.String(), info.Minted, info.MaxSupply)
	}
	return out
}

func collectionPage(cid string, page int64) string {
	info := core.Info(cid)
	out := "# " + plainText(info.Name) + " (" + plainText(info.Symbol) + ")\n\n"
	if info.Description != "" {
		out += plainText(info.Description) + "\n\n"
	}
	out += ufmt.Sprintf("- State: **%s**, %d/%d minted, royalty %d bps\n", info.State.String(), info.Minted, info.MaxSupply, info.RoyaltyBps)
	out += "- Creator: " + who(info.Creator) + "\n"
	out += "- Engine: [" + plainText(info.EngineID) + "](" + link("e/"+info.EngineID) + ")\n"
	if info.Badge != "" {
		out += "- Provenance: **" + info.Badge + "** — " + fairness(cid) + "\n"
	}
	if f := market.Floor(cid); f > 0 {
		out += ufmt.Sprintf("- Floor: %d ugnot\n", f)
	}
	out += "\n## Tokens\n\n"
	first := (page-1)*pageSize + 1
	for n := first; n < first+pageSize && n <= info.Minted; n++ {
		tid := itoa(n)
		owner, err := core.OwnerOf(cid, tid)
		if err != nil {
			continue
		}
		line := "- [#" + tid + "](" + link("c/"+cid+"/t/"+tid) + ") owned by " + who(owner)
		if _, price, ok := market.ActiveListing(cid, tid); ok {
			line += ufmt.Sprintf(", listed at %d ugnot", price)
		}
		out += line + "\n"
	}
	if first+pageSize <= info.Minted {
		out += "\n[Next page](" + link(ufmt.Sprintf("c/%s?page=%d", cid, page+1)) + ")\n"
	}
	return out
}

func tokenPage(cid, tid string) string {
	info := core.Info(cid)
	owner, err := core.OwnerOf(cid, tid)
	if err != nil {
		return "# Token not found\n"
	}
	uri, _ := core.TokenURI(cid, tid)
	out := "# " + plainText(info.Name) + " #" + tid + "\n\n"
	out += "![" + plainText(info.Name) + " #" + tid + "](" + sanitize.ImageURL(uri) + ")\n\n"
	out += "- Owner: " + who(owner) + "\n"
	if id, price, ok := market.ActiveListing(cid, tid); ok {
		out += ufmt.Sprintf("- Listed: %d ugnot (listing %s)\n", price, id)
	}
	out += "\n## Traits\n\n"
	for _, t := range core.TokenTraitList(cid, tid) {
		out += "- " + plainText(t.Type) + ": " + plainText(t.Value) + "\n"
	}
	out += "\n## How to verify\n\n"
	if info.State != types.StateFinal {
		out += "The collection is not revealed yet; every token shows the same placeholder.\n"
		return out
	}
	out += "1. Read `Provenance(\"" + cid + "\")` on core from another RPC and recompute the commitments and the salt.\n"
	out += "2. Seed: `TokenSeed(\"" + cid + "\", \"" + tid + "\")` = sha256(\"" + "art|seed|v1|" + cid + "|" + tid + "|\" + salt).\n"
	out += "3. Render it yourself: `RenderWith(engine, params, seed)` must return this image.\n\n"
	out += "Provenance badge **" + info.Badge + "**, on-chain check: " + strconv.FormatBool(core.VerifyProvenance(cid)) +
		"; " + fairness(cid) + "\n"
	return out
}

// fairness never calls a collection "verified" unless it is a fair launch
// (core.FairLaunch): a consistent record is not enough when one party could
// choose the map (SA-M2).
func fairness(cid string) string {
	if core.FairLaunch(cid) {
		return "fair launch, verified on chain"
	}
	if !core.VerifyProvenance(cid) {
		return "NOT verified: the provenance record does not check out"
	}
	return "not a fair launch: one party could choose the map (record consistent)"
}

// plainText renders user text as inert markdown: sanitize.InlineText escapes
// every inline-active character (\ * _ [ ] ( ) ~ > - + . ! ` # < &) and folds
// newlines, and escaping ':' breaks bare-URL autolinks ("https\://…"), which
// InlineText leaves alone (SA-M4).
func plainText(s string) string {
	return strings.ReplaceAll(sanitize.InlineText(s), ":", "\\:")
}

func enginePage(id string) string {
	m := core.EngineManifest(id)
	out := "# Engine " + plainText(m.Name) + " " + plainText(m.Version) + "\n\n"
	out += "- Realm: " + sanitize.InlineCode(id) + "\n"
	out += "- Author: " + who(m.Author) + "\n"
	out += "- Status: **" + core.EngineStatus(id) + "**, sample fingerprint intact: " + strconv.FormatBool(core.VerifyEngine(id)) + "\n"
	out += "- License: " + plainText(m.License) + "\n"
	out += "- Traits: " + plainText(strings.Join(m.TraitTypes, ", ")) + "\n\n"
	if m.Description != "" {
		out += plainText(m.Description) + "\n"
	}
	return out
}

func userPage(name string) string {
	u, _ := users.ResolveName(name)
	if u == nil {
		return "# Unknown user\n"
	}
	addr := u.Addr()
	return "# @" + sanitize.InlineText(u.Name()) + "\n\n`" + addr.String() + "`\n\n" +
		"Collections and listings of this address: reader realm, `Profile(" + addr.String() + ")`.\n"
}

// who renders an address as its r/sys/users name when it has one.
func who(addr address) string {
	if u := users.ResolveAddress(addr); u != nil {
		return "[@" + sanitize.InlineText(u.Name()) + "](/u/" + sanitize.InlineText(u.Name()) + ")"
	}
	return "`" + addr.String() + "`"
}

func pageFrom(query string) int64 {
	for _, kv := range strings.Split(query, "&") {
		if strings.HasPrefix(kv, "page=") {
			if n, err := strconv.ParseInt(strings.TrimPrefix(kv, "page="), 10, 64); err == nil && n >= 1 && n <= maxPageNum {
				return n
			}
		}
	}
	return 1
}

// selfPath is captured at deploy; links are gnoweb paths without the domain.
var selfPath string

func init(cur realm) {
	selfPath = cur.PkgPath()
}

func base() string {
	return strings.TrimPrefix(selfPath, "gno.land")
}

func link(route string) string { return base() + ":" + route }

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package myrealm

import "strconv"

var count int

func Increment(_ realm) int {
	count++
	return count
}

func Render(path string) string {
	return "Count: " + strconv.Itoa(count)
}
